insert into public.course_modules (id, course_id, title, description, position) values
  ('294a25d0-64a7-c3ad-e0d2-7f12ca297dcb', '40abe0c4-0341-1c25-adee-8292a16408cf', 'Menaces, risques et référentiels', 'Ce module t’apprend à regarder une application web comme un système entier, puis à décrire ses faiblesses avec un vocabulaire commun et vérifiable. Critères de réussite : cartographier une surface d’attaque et ses frontières de confiance ; classer un constat dans la bonne famille OWASP Top 10:2025 ; distinguer CWE, CVE et CVSS sans confondre gravité technique et risque métier.', 3),
  ('ea34b780-982c-e579-95c4-bd5a43917439', '40abe0c4-0341-1c25-adee-8292a16408cf', 'Les injections', 'Tu y comprends pourquoi des données non fiables deviennent du code, et comment casser ce mécanisme avec des défenses sobres et vérifiables. Critères de réussite : reconnaître une injection SQL dans du code ou un journal ; appliquer le même raisonnement défensif aux commandes, filtres NoSQL et modèles ; normaliser, valider et encoder selon le bon contexte sans inventer de faux remèdes.', 4),
  ('01b61988-3e06-bd60-c093-4b3ce7f7c72a', '40abe0c4-0341-1c25-adee-8292a16408cf', 'XSS et sécurité du navigateur', 'Ce module t’apprend à reconnaître ce que le navigateur exécute ou charge quand une donnée non fiable traverse mal l’application, puis à ajouter des garde-fous réalistes sans les confondre avec le correctif principal. Critères de réussite : distinguer XSS réfléchi, stocké et DOM ; évaluer si une CSP ou un jeu d’en-têtes réduit vraiment le risque ; proposer une correction adaptée au contexte de sortie et aux protections du navigateur.', 5),
  ('0433df95-43a7-32ea-c662-689e1d682dbc', '40abe0c4-0341-1c25-adee-8292a16408cf', 'Sessions, jetons et authentification', 'Tu y suis l’identité technique d’un utilisateur ou d’un client web : cookie de session, jeton signé, puis délégation OAuth ou identité OIDC, avec leurs pièges de mise en œuvre les plus classiques. Critères de réussite : lire un « Set-Cookie » ou un JWT sans lui prêter de pouvoirs imaginaires ; expliquer quand régénérer, invalider ou vérifier un jeton ; décrire un flux OAuth 2.0 avec PKCE, « state » et portées minimales.', 6),
  ('59b4ce6c-101c-343c-1b5b-bd32a444aec7', '40abe0c4-0341-1c25-adee-8292a16408cf', 'Contrôle d’accès, CSRF et CORS', 'Tu y apprends à décider qui peut faire quoi, depuis quelle origine et avec quelles garanties quand un navigateur transporte déjà des cookies ou appelle une API. Critères de réussite : corriger un accès à l’objet d’un autre utilisateur côté serveur ; expliquer quand un jeton anti-CSRF et « SameSite » sont nécessaires ; configurer une liste d’origines CORS exacte sans refléter tout ce qui arrive.', 7),
  ('9680e491-932b-894b-5261-defeb80e8019', '40abe0c4-0341-1c25-adee-8292a16408cf', 'Fichiers, SSRF et API', 'Ce module relie les entrées les plus piégeuses d’une application web : fichiers envoyés par l’utilisateur, URLs récupérées par le serveur et objets exposés par l’API. Critères de réussite : vérifier un téléversement sans faire confiance au nom ou au type annoncé ; bloquer une destination SSRF locale, privée ou non autorisée ; borner une API par objet, propriété et rythme de requêtes avec des journaux utiles.', 8),
  ('014933f4-4c0b-c7cd-bff2-02fa5109ba11', '40abe0c4-0341-1c25-adee-8292a16408cf', 'Configuration, dépendances et défense', 'Ce module t’apprend à durcir une application web au-delà du code métier : configuration, secrets, dépendances, pipeline et défense en profondeur. Critères de réussite : repérer une mauvaise configuration ou un secret mal placé ; classer une alerte de dépendance selon son exposition réelle ; expliquer ce qu’un WAF, une limitation de débit et de bons journaux apportent, sans les confondre avec un correctif.', 9),
  ('0ffba43d-617c-5139-0143-06e458dfc382', '40abe0c4-0341-1c25-adee-8292a16408cf', 'Auditer un site et rendre compte', 'Tu y apprends à cadrer un audit, à le conduire avec méthode, puis à transformer les observations en rapport actionnable. Critères de réussite : vérifier un périmètre et des règles d’engagement avant tout test ; consigner des preuves reproductibles en distinguant lecture seule, hypothèse et conclusion ; rédiger un constat avec preuve, sévérité, recommandation et re-test.', 10)
insert into public.lessons (id, course_id, module_id, title, summary, content, duration_minutes, xp_reward, position) values
  ('0439a7a3-c56b-f42b-2098-752c25a889c4', '40abe0c4-0341-1c25-adee-8292a16408cf', '9cd4050a-9697-5bc1-6f15-903217984b6a', 'HTTP pour la sécurité : requêtes, réponses, méthodes et codes d’état', 'Lis un échange HTTP comme un développeur prudent : structure de la requête, sens des méthodes, codes d’état utiles et limites de confiance côté client.', '{"blocks":[{"type":"callout","content":"Objectifs : décrire une requête et une réponse HTTP, distinguer méthodes sûres et idempotentes, lire les codes d’état qui comptent pour la sécurité, repérer les en-têtes sensibles, puis expliquer pourquoi le serveur ne fait jamais confiance au client."},{"type":"callout","content":"Prérequis : avoir les bases des parcours Fondamentaux et Réseaux, ou connaître l’idée d’un client qui parle à un serveur."},{"type":"callout","content":"Mise en situation : Ama aide Baobab Tech à comprendre pourquoi une page de connexion refuse parfois des utilisateurs. Dans le journal, elle voit des requêtes, des codes 401, des cookies et des URL qui contiennent trop d’informations. Pour corriger sans casser le site, elle doit relire l’échange HTTP lui-même, pas seulement l’interface du navigateur."},{"type":"callout","content":"Vidéo à venir : Lire un échange HTTP avec l’œil de la sécurité"},{"type":"text","content":"HTTP est le langage de base du web. Un client, par exemple un navigateur ou « curl.exe », envoie une requête. Le serveur répond avec une ligne d’état, des en-têtes et parfois un corps. En sécurité web, ce détail compte car une fuite, une mauvaise méthode ou un code d’état mal choisi changent ce que le navigateur, un intermédiaire ou un journal vont conserver."},{"type":"schema","content":"{\"v\":1,\"kind\":\"table\",\"title\":\"Échange HTTP minimal\",\"columns\":[\"Partie\",\"Valeur\"],\"rows\":[[\"Requête\",\"GET /connexion HTTP/1.1\"],[\"En-tête\",\"Host: app.example.org\"],[\"En-tête\",\"Cookie: session=abc123\"],[\"Réponse\",\"HTTP/1.1 401 Unauthorized\"],[\"En-tête\",\"Content-Type: text/plain; charset=utf-8\"],[\"En-tête\",\"Set-Cookie: session=abc123; Path=/; HttpOnly; SameSite=Lax\"],[\"Corps\",\"auth required\"]],\"mono\":[1]}"},{"type":"text","content":"La méthode exprime l’intention. « GET », « HEAD », « OPTIONS » et « TRACE » sont dites sûres : elles ne devraient pas modifier l’état du serveur. « PUT » et « DELETE » sont idempotentes : si tu rejoues exactement la même requête, l’effet final reste le même. « POST » et « PATCH » ne le sont pas par défaut. Cette règle de conception a un impact défensif immédiat : si un « GET » déclenche une action sensible, tu facilites des erreurs et parfois des CSRF triviaux."},{"type":"code","content":"# Dans PowerShell 5.1 sous Windows, utilise bien curl.exe\ncurl.exe -i http://127.0.0.1:8080/connexion\n# exemple de sortie (valeurs fictives)\n# HTTP/1.1 401 Unauthorized\n# Content-Type: text/plain; charset=utf-8\n# Cache-Control: no-store\n# Set-Cookie: session=abc123; Path=/; HttpOnly; SameSite=Lax\n# X-From-Demo: cyberpingo\n# Date: Sun, 04 Oct 2026 04:02:19 GMT\n# Connection: close\n# Transfer-Encoding: chunked\n#\n# auth required","language":"bash"},{"type":"text","content":"Démonstration guidée : lance un petit serveur d’essai sur « 127.0.0.1:8080 », puis relis la réponse avec « curl.exe -i ». Tu vois ici un « 401 Unauthorized », qui veut dire en pratique « non authentifié ». Le serveur t’indique aussi qu’il ne faut pas mettre cette réponse en cache avec « Cache-Control: no-store », et renvoie un cookie de session. Cette manipulation marche aussi dans Git Bash, WSL ou Termux avec « curl » tout court."},{"type":"schema","content":"{\"v\":1,\"kind\":\"table\",\"title\":\"Codes d’état à retenir\",\"columns\":[\"Code\",\"Sens\"],\"rows\":[[\"301, 308\",\"redirection durable\"],[\"302, 307\",\"redirection temporaire\"],[\"401\",\"il manque une authentification valide\"],[\"403\",\"tu es identifié, mais l’action reste interdite\"],[\"404\",\"ressource absente, ou existence non révélée\"],[\"405\",\"méthode refusée sur cette route\"],[\"429\",\"trop de requêtes, limitation de débit\"],[\"500, 503\",\"erreur côté serveur\"]],\"mono\":[0]}"},{"type":"text","content":"Les en-têtes les plus utiles côté sécurité sont souvent « Host », « Cookie », « Set-Cookie », « Authorization », « Content-Type », « Location », « Origin » et « Referer ». Le piège central est là : tout ce que le client envoie peut être falsifié. Un script, un proxy, un téléphone modifié ou une requête fabriquée à la main peuvent mentir sur l’adresse d’origine, le navigateur, les champs cachés ou les validations JavaScript. La règle de sécurité vit donc côté serveur."},{"type":"example","content":"Exemple corrigé : dans l’échange ci-dessus, le bon point est le code « 401 » pour une route de connexion et le « no-store » pour éviter de laisser cette réponse dans un cache. Le mauvais point serait d’envoyer un jeton ou un mot de passe dans l’URL, car l’adresse finirait dans l’historique, les journaux et parfois dans « Referer ». Si tu vois « https://app.example.org/reset?token=... », considère cela comme un signal d’alerte à corriger."},{"type":"callout","content":"Erreurs fréquentes : mettre un secret dans une URL ; utiliser « 403 » et « 401 » comme s’ils étaient interchangeables ; faire modifier un état par « GET » ; croire qu’un champ caché ou un contrôle JavaScript suffit comme défense."},{"type":"callout","content":"Sécurité : tes essais se font sur ton serveur local, ta maquette ou un système pour lequel tu as une autorisation écrite. Même une simple requête fabriquée à la main reste hors cadre si elle vise le site d’un tiers. Les journaux HTTP contiennent souvent des données personnelles : ne les publie pas sans nécessité."},{"type":"callout","content":"À retenir : HTTP te montre ce qui est envoyé, reçu et conservé. Les méthodes disent l’intention, les codes d’état disent le résultat, et les en-têtes donnent le contexte. Côté sécurité, ne fais confiance à rien de ce qui vient du client sans vérification serveur."},{"type":"callout","content":"Pour pratiquer : Travaille dans « TP 1 : lire HTTP, cookies et en-têtes de sécurité » : repère les lignes de requête, les codes d’état et les en-têtes qui changent une décision de sécurité, puis termine par le quiz de la leçon."},{"type":"resource","content":"MDN : aperçu de HTTP","url":"https://developer.mozilla.org/fr/docs/Web/HTTP/Overview"},{"type":"resource","content":"RFC 9110 : sémantique HTTP (en anglais)","url":"https://www.rfc-editor.org/rfc/rfc9110"},{"type":"resource","content":"curl : la page de manuel (en anglais)","url":"https://curl.se/docs/manpage.html"}]}'::jsonb, 22, 30, 1),
  ('b947a3cc-f0fe-3ceb-a97f-d8d400e7b98d', '40abe0c4-0341-1c25-adee-8292a16408cf', '9cd4050a-9697-5bc1-6f15-903217984b6a', 'Le navigateur : origine, même origine et ce qu’il protège', 'Apprends ce que le navigateur isole, comment l’origine se calcule, pourquoi la même origine bloque la lecture et non l’envoi, et où SRI ajoute une vraie défense.', '{"blocks":[{"type":"callout","content":"Objectifs : définir une origine web, comparer même origine et même site, expliquer pourquoi le navigateur bloque surtout la lecture inter-origines, repérer le risque des ressources tierces, puis calculer une empreinte SRI simple."},{"type":"callout","content":"Prérequis : avoir suivi « HTTP pour la sécurité : requêtes, réponses, méthodes et codes d’état » et connaître la différence entre une URL et un nom de domaine."},{"type":"callout","content":"Mise en situation : Fatou ajoute un script tiers sur le site de l’association Teranga. Tout fonctionne, mais un collègue lui demande pourquoi ce script peut lire la page alors qu’un autre site ne peut pas. En même temps, une API distante accepte bien la requête, mais le navigateur refuse de laisser le code lire la réponse. Fatou doit comprendre la frontière de sécurité du navigateur, pas seulement celle du serveur."},{"type":"callout","content":"Vidéo à venir : Origine web, même site et ressources tierces sans confusion"},{"type":"text","content":"Le navigateur ne fait pas qu’afficher du texte. Il rend une page, exécute du JavaScript, gère des cookies, du stockage local, des formulaires, des iframes et des téléchargements. Pour éviter qu’un site lise les secrets d’un autre, il sépare les contenus par origine. Une origine se compose du schéma, de l’hôte et du port. Si l’un des trois change, l’origine change."},{"type":"schema","content":"{\"v\":1,\"kind\":\"table\",\"title\":\"Même origine ?\",\"columns\":[\"URL comparée à `https://app.example.org`\",\"Verdict\"],\"rows\":[[\"https://app.example.org/admin\",\"oui\"],[\"http://app.example.org\",\"non, schéma différent\"],[\"https://app.example.org:8443\",\"non, port différent\"],[\"https://api.example.org\",\"non, hôte différent\"],[\"https://shop.example.org:443\",\"origine différente si hôte différent\"]],\"mono\":[0]}"},{"type":"text","content":"La politique de même origine, souvent appelée SOP, empêche surtout une page de lire la réponse d’une autre origine sans accord explicite. En revanche, le navigateur sait envoyer des requêtes vers d’autres origines : charger une image, soumettre un formulaire, appeler une API. C’est pour cela qu’un CSRF existe : l’envoi est permis plus facilement que la lecture. « Même site » est une notion voisine, utile surtout pour les cookies « SameSite », mais elle n’est pas aussi stricte que l’origine. Une iframe d’une autre origine peut donc s’afficher dans ta page, mais son code ne lit pas librement ton DOM si l’origine diffère."},{"type":"code","content":"# Tester six paires d’URL avec Node.js\nnode -e \"const pairs=[[''https://app.example.org'',''https://app.example.org/admin''],[''https://app.example.org'',''http://app.example.org''],[''https://app.example.org'',''https://app.example.org:8443''],[''https://app.example.org'',''https://api.example.org''],[''https://shop.example.org'',''https://shop.example.org:443''],[''http://intranet.example.org:8080'',''http://intranet.example.org:8080/outils'']]; const same=(a,b)=>{const x=new URL(a),y=new URL(b); const px=x.port||(x.protocol===''https:''?''443'':''80''); const py=y.port||(y.protocol===''https:''?''443'':''80''); return x.protocol===y.protocol && x.hostname===y.hostname && px===py;}; for (const [a,b] of pairs) console.log(`${a} | ${b} | ${same(a,b)}`);\"\n# exemple de sortie (valeurs fictives)\n# https://app.example.org | https://app.example.org/admin | true\n# https://app.example.org | http://app.example.org | false\n# https://app.example.org | https://app.example.org:8443 | false\n# https://app.example.org | https://api.example.org | false\n# https://shop.example.org | https://shop.example.org:443 | true\n# http://intranet.example.org:8080 | http://intranet.example.org:8080/outils | true","language":"bash"},{"type":"text","content":"Démonstration guidée : commence par « node --version ». L’objet global « URL » utilisé ici est disponible depuis Node.js 10.0.0. Si ta version est plus ancienne, mets Node.js à jour ou colle le même code dans la console du navigateur. La fonction compare le schéma, l’hôte et le port effectif, y compris les ports implicites 80 et 443. Tu peux la rejouer telle quelle sur Windows avec Node.js, ou dans WSL et Termux. Le résultat illustre le point clé : un chemin différent ne change pas l’origine, mais un autre schéma, un autre hôte ou un autre port la change immédiatement."},{"type":"text","content":"Les ressources tierces demandent une deuxième vigilance. Un script chargé depuis un autre domaine s’exécute avec les droits de la page qui l’inclut. S’il est compromis, il peut agir comme ton application. SRI, « Subresource Integrity », ajoute une empreinte attendue dans la balise afin que le navigateur refuse un fichier modifié. Cela n’autorise pas le script à être moins surveillé : SRI protège l’intégrité du fichier chargé, pas la confiance métier dans le fournisseur. Retiens aussi qu’une partie des API sensibles du navigateur ne fonctionne qu’en contexte sécurisé, donc sur HTTPS, et que les extensions ou logiciels présents sur le poste de l’utilisateur restent hors du contrôle du développeur."},{"type":"code","content":"# Calculer une empreinte SRI en SHA-384 avec Node.js\nnode -e \"const c=require(''crypto''); const src=\\\"console.log(''Bonjour CyberPingo'');\\\\n\\\"; console.log(''sha384-''+c.createHash(''sha384'').update(src).digest(''base64''));\"\n# exemple de sortie (valeurs fictives)\n# sha384-ID7Mxm5d9IX/roLgTU97ZbmCAra5xPdxbrxWGA8G/2IJ7pOlMLDxLiHiiS4Ucye/","language":"bash"},{"type":"text","content":"Pour ce calcul SRI, vérifie aussi « node --version ». « crypto.createHash() » existe depuis les toutes premières versions de Node.js, donc toute version maintenue actuelle convient. Si « node » manque, mets Node.js à jour ou calcule l’empreinte avec l’outil de build de ton projet."},{"type":"example","content":"Exemple corrigé : une page de dons charge « https://cdn.example.org/widget.js ». Sans SRI, si ce fichier change côté CDN, le navigateur l’accepte. Avec l’attribut « integrity », il ne l’exécute que si l’empreinte correspond encore. En revanche, si ce script est légitime mais trop curieux, SRI ne limite pas ce qu’il fera une fois chargé : il faut aussi choisir ses dépendances et leurs permissions avec prudence."},{"type":"callout","content":"Erreurs fréquentes : confondre chemin et origine ; croire que le navigateur bloque tout trafic inter-origines alors qu’il bloque surtout la lecture ; traiter « même site » comme synonyme exact de « même origine » ; intégrer un script tiers sans réfléchir à son pouvoir sur la page."},{"type":"callout","content":"Sécurité : tes essais se font sur des URL d’exemple, ton navigateur et ton code local. N’utilise pas cette compréhension pour contourner les défenses d’un autre site. Si tu analyses des cookies ou du stockage réel, rappelle-toi qu’ils peuvent contenir des données personnelles ou de session."},{"type":"callout","content":"À retenir : L’origine web repose sur trois éléments : schéma, hôte, port. La politique de même origine protège surtout la lecture entre sites. Les ressources tierces vivent dans le contexte de ta page, donc leur intégrité et leur confiance comptent autant que ton propre code."},{"type":"callout","content":"Pour pratiquer : Travaille dans « TP 1 : lire HTTP, cookies et en-têtes de sécurité » : compare des origines, relis les cookies et juge quand un site tiers reçoit trop de pouvoir. Termine ensuite par le quiz de la leçon."},{"type":"resource","content":"MDN : la politique de même origine","url":"https://developer.mozilla.org/fr/docs/Web/Security/Defenses/Same-origin_policy"},{"type":"resource","content":"MDN : les cookies HTTP","url":"https://developer.mozilla.org/fr/docs/Web/HTTP/Guides/Cookies"},{"type":"resource","content":"RFC 6454 : le concept d’origine web (en anglais)","url":"https://www.rfc-editor.org/rfc/rfc6454"},{"type":"resource","content":"MDN : l’intégrité des sous-ressources (SRI)","url":"https://developer.mozilla.org/fr/docs/Web/Security/Subresource_Integrity"},{"type":"resource","content":"Node.js : le module url (en anglais)","url":"https://nodejs.org/api/url.html"}]}'::jsonb, 22, 30, 3),
  ('b3f2d856-7c5d-2169-ae53-175cc32fb4ce', '40abe0c4-0341-1c25-adee-8292a16408cf', 'cac61a27-3cf0-4193-c6f6-e0368abfd2a9', 'Stocker les mots de passe côté serveur : hachage, sel et politiques', 'Passe du côté serveur : hachage lent, sel unique, comparaison sûre, politique NIST raisonnable et réinitialisation de mot de passe qui ne crée pas une nouvelle faille.', '{"blocks":[{"type":"callout","content":"Objectifs : distinguer mot de passe en clair, chiffrement et hachage, expliquer le rôle du sel et du poivre, comparer Argon2id, scrypt, bcrypt et PBKDF2, vérifier un mot de passe proprement, puis décrire une politique et une réinitialisation conformes aux bonnes pratiques."},{"type":"callout","content":"Prérequis : avoir suivi « Protéger ses comptes avec un gestionnaire et la MFA » et connaître l’idée d’un secret unique côté utilisateur."},{"type":"callout","content":"Mise en situation : Kwame développe une petite application pour la boutique Soleil. Un collègue propose de stocker les mots de passe avec « SHA-256 » parce que c’est simple et déjà disponible. En parallèle, l’équipe veut des règles de mot de passe compliquées et un renouvellement mensuel. Kwame doit défendre une autre approche : stockage lent et robuste côté serveur, puis politique plus réaliste côté utilisateur."},{"type":"callout","content":"Vidéo à venir : Stocker un mot de passe sans stocker le mot de passe"},{"type":"text","content":"Un serveur ne garde jamais un mot de passe en clair. Il stocke une empreinte calculée par une fonction conçue pour cela : lente, coûteuse en mémoire ou en calcul, et différente pour chaque utilisateur grâce à un sel unique. Le hachage n’est pas du chiffrement : le but n’est pas de retrouver le secret, mais de vérifier qu’une nouvelle saisie produit la même empreinte. Une fonction rapide comme SHA-256 seule n’est donc pas adaptée, car elle aide aussi l’attaquant à tenter énormément d’essais."},{"type":"schema","content":"{\"v\":1,\"kind\":\"flow\",\"title\":\"Stockage correct, en bref\",\"nodes\":[{\"label\":\"mot de passe saisi\",\"icon\":\"key\"},{\"label\":\"sel unique aléatoire\",\"icon\":\"file\",\"tone\":\"blue\"},{\"label\":\"algorithme lent\",\"text\":\"par exemple Argon2id ou scrypt\",\"icon\":\"braces\",\"tone\":\"amber\"},{\"label\":\"empreinte stockée\",\"icon\":\"database\",\"tone\":\"green\"}],\"caption\":\"Optionnel : poivre côté serveur, séparé de la base.\"}"},{"type":"text","content":"Aujourd’hui, l’aide-mémoire OWASP recommande Argon2id avec au minimum 19 Mio de mémoire, 2 itérations et un parallélisme de 1. Si Argon2id n’est pas disponible, scrypt est une bonne option ; bcrypt reste acceptable pour l’existant avec un facteur d’au moins 10 et la limite connue de 72 octets ; PBKDF2 avec HMAC-SHA-256 et 600 000 itérations ou plus répond aux contextes FIPS. Le point clé n’est pas le nom seul : c’est le coût effectif pour ralentir une attaque hors ligne."},{"type":"code","content":"# Montrer que le même mot de passe donne deux empreintes différentes avec deux sels\nnode -e \"const c=require(''crypto''); const pwd=''motdepasse''; const h1=c.scryptSync(pwd,''salt-demo-1'',32).toString(''hex''); const h2=c.scryptSync(pwd,''salt-demo-2'',32).toString(''hex''); const ok=c.timingSafeEqual(Buffer.from(h1,''hex''), c.scryptSync(pwd,''salt-demo-1'',32)); const bad=c.timingSafeEqual(Buffer.from(h1,''hex''), c.scryptSync(''azerty'',''salt-demo-1'',32)); console.log(h1); console.log(h2); console.log(''ok=''+ok); console.log(''bad=''+bad);\"\n# exemple de sortie (valeurs fictives)\n# 4bd9b5ff181b311cede0488291585302a9d2fe3205904c77d5ca7a01b66fe926\n# 88a3bc3a31c51f094436a4157e55f67808362796e43a7fa51f4c98e9f3d06cd3\n# ok=true\n# bad=false","language":"bash"},{"type":"text","content":"Démonstration guidée : commence par « node --version ». « crypto.scryptSync() » est disponible depuis Node.js 10.5.0 et « timingSafeEqual() » depuis Node.js 6.6.0, donc ce script demande au minimum Node.js 10.5.0. Si ta version est plus ancienne, mets Node.js à jour avant de le rejouer. Le script ci-dessus utilise « crypto.scryptSync », disponible sans dépendance supplémentaire, pour montrer deux sels distincts et une vérification en temps constant avec « timingSafeEqual ». Les deux empreintes diffèrent alors que le mot de passe est identique. C’est exactement l’effet recherché : empêcher les comparaisons massives simples et obliger l’attaquant à recalculer pour chaque utilisateur."},{"type":"text","content":"La politique de mots de passe a aussi changé. Les recommandations NIST demandent au minimum 15 caractères quand le mot de passe est le seul facteur, et au minimum 8 caractères quand il fait partie d’une MFA. Elles insistent aussi sur l’acceptation des phrases de passe, des gestionnaires, du collage et du remplissage automatique, puis sur l’abandon des règles de composition arbitraires et du changement périodique imposé sans suspicion de compromission. Côté application, cela se traduit aussi par une vérification contre une liste de mots de passe compromis, des messages d’erreur semblables pour « compte inconnu » et « mot de passe faux », une limitation des tentatives, et une réinitialisation par jeton aléatoire, à usage unique et à courte durée de vie."},{"type":"example","content":"Exemple corrigé : bonne décision, stocker une empreinte Argon2id ou scrypt avec un sel unique, limiter les essais, accepter une phrase longue issue d’un gestionnaire, et réinitialiser par un jeton aléatoire expirant vite. Mauvaise décision, garder un SHA-256 seul, forcer un symbole spécial sans raison claire, exiger un changement mensuel et afficher « ce compte n’existe pas » quand l’adresse n’est pas connue."},{"type":"callout","content":"Erreurs fréquentes : parler de chiffrement alors qu’il s’agit de hachage ; réutiliser le même sel pour tout le monde ; journaliser des mots de passe ou des jetons de réinitialisation ; faire de la rotation forcée un réflexe alors qu’aucun indice de compromission n’existe."},{"type":"callout","content":"Sécurité : teste ces scripts uniquement avec des mots de passe d’exemple et des bases d’essai. N’envoie jamais un vrai mot de passe, une vraie base d’utilisateurs ou un vrai export de journaux à un service tiers. Les données d’authentification restent sensibles même en laboratoire."},{"type":"callout","content":"À retenir : Côté serveur, on vérifie un mot de passe sans le conserver en clair. Le duo gagnant est un algorithme lent et un sel unique par secret. La politique moderne privilégie la longueur, les gestionnaires et la récupération sûre plutôt que des contraintes arbitraires faciles à contourner."},{"type":"callout","content":"Pour pratiquer : Travaille dans « TP 4 : sessions, jetons JWT et mots de passe » pour comparer politiques, empreintes et erreurs de conception, puis termine par le quiz de la leçon."},{"type":"resource","content":"CNIL : sécurité, authentifier les utilisateurs","url":"https://www.cnil.fr/fr/securite-authentifier-les-utilisateurs"},{"type":"resource","content":"OWASP : aide-mémoire sur le stockage des mots de passe (en anglais)","url":"https://cheatsheetseries.owasp.org/cheatsheets/Password_Storage_Cheat_Sheet.html"},{"type":"resource","content":"OWASP : aide-mémoire sur l’authentification (en anglais)","url":"https://cheatsheetseries.owasp.org/cheatsheets/Authentication_Cheat_Sheet.html"},{"type":"resource","content":"OWASP : aide-mémoire sur la réinitialisation de mot de passe (en anglais)","url":"https://cheatsheetseries.owasp.org/cheatsheets/Forgot_Password_Cheat_Sheet.html"},{"type":"resource","content":"NIST SP 800-63B-4 : lignes directrices sur l’authentification (en anglais)","url":"https://pages.nist.gov/800-63-4/sp800-63b.html"},{"type":"resource","content":"Node.js : le module crypto (en anglais)","url":"https://nodejs.org/api/crypto.html"}]}'::jsonb, 24, 30, 3),
  ('5e091ada-f0d5-ca53-b60a-40d8ec87a40c', '40abe0c4-0341-1c25-adee-8292a16408cf', '294a25d0-64a7-c3ad-e0d2-7f12ca297dcb', 'La surface d’attaque d’une application web et la modélisation des menaces', 'Tu apprends à voir une application web comme un ensemble de portes d’entrée, de frontières de confiance et de décisions de risque, pas seulement comme des pages HTML.', '{"blocks":[{"type":"callout","content":"Objectifs : repérer la surface d’attaque d’une application web, distinguer les frontières de confiance, classer des menaces par probabilité et impact, puis décider quoi réduire ou protéger en premier."},{"type":"callout","content":"Prérequis : avoir compris ce qu’est une application web, une requête HTTP et un compte utilisateur."},{"type":"callout","content":"Mise en situation : Ama aide l’association Teranga à préparer une application de dons. L’équipe pense surtout à l’écran d’accueil et au formulaire de paiement, mais oublie l’administration, les sauvegardes, le stockage d’images, la messagerie et la chaîne d’intégration. Avant de parler de failles précises, Ama veut cartographier tout ce qui peut être touché, par qui et avec quelles conséquences."},{"type":"callout","content":"Vidéo à venir : Voir la surface d’attaque avant de chercher une faille"},{"type":"text","content":"La surface d’attaque d’une application web, c’est l’ensemble des points par lesquels une action non voulue peut entrer, sortir ou contourner une règle. Cela inclut les pages publiques, les formulaires, les API, les cookies, les comptes, le téléversement de fichiers, les tâches planifiées, les interfaces d’administration, les secrets, les dépendances, les journaux, les sauvegardes et les services tiers. Plus il y a de composants inutiles ou mal compris, plus la surface augmente."},{"type":"schema","content":"{\"v\":1,\"kind\":\"network\",\"title\":\"Application de dons : surface d’attaque minimale\",\"cols\":6,\"rows\":4,\"nodes\":[{\"id\":\"cicd\",\"label\":\"CI/CD\",\"icon\":\"code\",\"col\":0,\"row\":0,\"tone\":\"violet\"},{\"id\":\"nav\",\"label\":\"Navigateur\",\"icon\":\"laptop\",\"col\":0,\"row\":1.5,\"tone\":\"blue\"},{\"id\":\"support\",\"label\":\"Support\",\"icon\":\"users\",\"col\":0,\"row\":3,\"tone\":\"amber\"},{\"id\":\"admin\",\"label\":\"/admin\",\"icon\":\"lock\",\"col\":1,\"row\":0,\"tone\":\"amber\"},{\"id\":\"pages\",\"label\":\"Pages publiques\",\"icon\":\"document\",\"col\":1,\"row\":1,\"tone\":\"cyan\"},{\"id\":\"don\",\"label\":\"Formulaire don\",\"icon\":\"message\",\"col\":1,\"row\":2,\"tone\":\"green\"},{\"id\":\"membre\",\"label\":\"Espace membre\",\"icon\":\"user\",\"col\":1,\"row\":3,\"tone\":\"blue\"},{\"id\":\"build\",\"label\":\"Build et secrets\",\"icon\":\"key\",\"col\":2.5,\"row\":0,\"tone\":\"red\"},{\"id\":\"web\",\"label\":\"Serveur web\",\"icon\":\"server\",\"col\":3,\"row\":1.5,\"tone\":\"green\"},{\"id\":\"backups\",\"label\":\"Sauvegardes CSV\",\"icon\":\"archive\",\"col\":3,\"row\":3,\"tone\":\"amber\"},{\"id\":\"logs\",\"label\":\"Journaux\",\"icon\":\"file\",\"col\":5,\"row\":0,\"tone\":\"violet\"},{\"id\":\"base\",\"label\":\"Base\",\"icon\":\"database\",\"col\":5,\"row\":1,\"tone\":\"green\"},{\"id\":\"pay\",\"label\":\"Paiement tiers\",\"icon\":\"cloud\",\"col\":5,\"row\":2,\"tone\":\"amber\"},{\"id\":\"docs\",\"label\":\"Stockage docs\",\"icon\":\"folder\",\"col\":5,\"row\":3,\"tone\":\"blue\"}],\"links\":[{\"from\":\"nav\",\"to\":\"pages\"},{\"from\":\"nav\",\"to\":\"don\"},{\"from\":\"nav\",\"to\":\"membre\"},{\"from\":\"admin\",\"to\":\"web\",\"label\":\"/admin\",\"arrow\":\"to\",\"tone\":\"amber\"},{\"from\":\"pages\",\"to\":\"web\"},{\"from\":\"don\",\"to\":\"web\"},{\"from\":\"membre\",\"to\":\"web\"},{\"from\":\"web\",\"to\":\"base\"},{\"from\":\"don\",\"to\":\"pay\",\"label\":\"paiement\",\"arrow\":\"to\",\"tone\":\"amber\"},{\"from\":\"membre\",\"to\":\"docs\",\"label\":\"documents\",\"arrow\":\"to\",\"tone\":\"blue\"},{\"from\":\"web\",\"to\":\"logs\",\"label\":\"journaux\",\"arrow\":\"to\",\"tone\":\"violet\"},{\"from\":\"cicd\",\"to\":\"build\",\"label\":\"build\",\"arrow\":\"to\",\"tone\":\"violet\"},{\"from\":\"build\",\"to\":\"web\",\"label\":\"déploiement\",\"arrow\":\"to\",\"tone\":\"violet\"},{\"from\":\"support\",\"to\":\"backups\",\"label\":\"exports\",\"arrow\":\"to\",\"tone\":\"amber\"}]}"},{"type":"text","content":"Une frontière de confiance marque l’endroit où tu arrêtes de croire qu’une donnée est sûre. Le navigateur d’un visiteur n’est jamais une frontière de confiance, car il peut modifier les champs, les cookies, les en-têtes et le JavaScript. Un service tiers n’est pas une frontière magique non plus : tu lui délègues une fonction, pas ta responsabilité. La bonne question devient donc : qui contrôle cette donnée, qui la vérifie, et que se passe-t-il si elle ment ?"},{"type":"schema","content":"{\"v\":1,\"kind\":\"steps\",\"title\":\"Quatre questions de modélisation des menaces\",\"numbered\":true,\"items\":[{\"title\":\"Que construisons-nous ?\"},{\"title\":\"Qu’est-ce qui peut mal tourner ?\"},{\"title\":\"Que faisons-nous pour réduire le risque ?\"},{\"title\":\"Avons-nous bien vérifié ?\"}],\"caption\":\"STRIDE aide-mémoire : usurpation, falsification, répudiation, divulgation, déni de service, élévation.\"}"},{"type":"text","content":"Les acteurs ne se résument pas à « le pirate ». Tu peux rencontrer un curieux qui clique partout, un robot automatisé qui teste des milliers d’URL, un concurrent qui cherche une fuite de données, un employé qui abuse d’un accès déjà légitime, ou un attaquant ciblé qui connaît ton organisation. Le risque se juge ensuite avec deux axes simples : la probabilité et l’impact. Ce n’est pas une science exacte, mais c’est mieux qu’une intuition floue."},{"type":"text","content":"Démonstration guidée : le script ci-dessous prend huit menaces d’exemple pour une application fictive et leur attribue une priorité à partir d’une matrice 3 × 3. Le calcul ne remplace pas un atelier d’équipe, mais il t’oblige à écrire tes hypothèses. Le code a été exécuté avec Node.js, uniquement sur des valeurs inventées."},{"type":"code","content":"const threats = [\n  [''Formulaire de don sans anti-CSRF'', 2, 2],\n  [''Sauvegarde publique sur le web'', 2, 3],\n  [''Compte admin partage'', 2, 3],\n  [\"Portail d''admin masque mais expose\", 1, 3],\n  [''Plugin de statistique inutile'', 2, 1],\n  [''Bucket de journaux public'', 1, 3],\n  [''Ancienne API oubliee'', 2, 2],\n  [''Champ de recherche concatene en SQL'', 3, 3],\n];\nconst rows = threats.map(([name, p, i]) => ({\n  name, p, i, score: p * i,\n  priorite: p * i >= 6 ? ''haute'' : p * i >= 3 ? ''moyenne'' : ''basse'',\n}));\nconsole.log(rows);\n// exemple de sortie (valeurs fictives)\n// { name: ''Sauvegarde publique sur le web'', p: 2, i: 3, score: 6, priorite: ''haute'' }\n// { name: ''Champ de recherche concatene en SQL'', p: 3, i: 3, score: 9, priorite: ''haute'' }\n// { name: ''Plugin de statistique inutile'', p: 2, i: 1, score: 2, priorite: ''basse'' }","language":"javascript"},{"type":"example","content":"Exemple corrigé : dans cette matrice, la « sauvegarde publique sur le web » et le « champ de recherche concaténé en SQL » montent en priorité haute, mais pas pour la même raison. La première expose directement des données déjà présentes. Le second ouvre la porte à une faiblesse active sur un point d’entrée courant. À l’inverse, un plugin inutile augmente bien la surface d’attaque, mais avec un impact moindre tant qu’il n’expose ni donnée sensible ni privilège fort. La décision raisonnable est donc de supprimer d’abord l’inutile, puis de corriger en priorité les points qui combinent exposition et conséquence."},{"type":"callout","content":"Erreurs fréquentes : confondre surface d’attaque et nombre de pages visibles ; croire qu’un service tiers supprime la responsabilité de l’équipe ; noter le risque sans écrire l’hypothèse qui le justifie ; garder une vieille interface « au cas où » au lieu de la supprimer."},{"type":"callout","content":"Sécurité : quand tu parles de menaces, tu restes dans un cadre défensif. Tu cartographies ton propre site, ton environnement d’essai ou un périmètre couvert par une autorisation écrite. Les diagrammes, journaux et exports peuvent contenir des données personnelles : ne les publie pas et ne les envoie pas à un service tiers sans nécessité."},{"type":"callout","content":"À retenir : la première défense consiste souvent à réduire ce qui existe. Une surface d’attaque se lit par points d’entrée, frontières de confiance, acteurs et conséquences. Le risque n’est pas un chiffre magique : c’est un raisonnement explicite sur la probabilité et l’impact."},{"type":"callout","content":"Pour pratiquer : Travaille dans « Projet final : auditer l’application de réservation et rédiger le rapport » : cette leçon ne refait pas le projet à ta place, mais elle t’aide à repérer les zones à cartographier avant d’écrire tes constats. Termine ensuite par le quiz."},{"type":"resource","content":"OWASP : aide-mémoire sur l’analyse de la surface d’attaque (en anglais)","url":"https://cheatsheetseries.owasp.org/cheatsheets/Attack_Surface_Analysis_Cheat_Sheet.html"},{"type":"resource","content":"OWASP : aide-mémoire sur la modélisation des menaces (en anglais)","url":"https://cheatsheetseries.owasp.org/cheatsheets/Threat_Modeling_Cheat_Sheet.html"},{"type":"resource","content":"ANSSI : la méthode EBIOS Risk Manager","url":"https://cyber.gouv.fr/securisation/analyse-des-risques/methode-ebios-rm/"}]}'::jsonb, 22, 30, 1),
  ('f389fbae-e861-7aff-603a-29b9d907b891', '40abe0c4-0341-1c25-adee-8292a16408cf', '294a25d0-64a7-c3ad-e0d2-7f12ca297dcb', 'OWASP Top 10 : lire la liste, ses catégories et ses limites', 'Tu vas apprendre à utiliser l’OWASP Top 10:2025 comme une carte de sensibilisation utile, sans le confondre avec une norme exhaustive ni avec une checklist magique.', '{"blocks":[{"type":"callout","content":"Objectifs : nommer les catégories du Top 10:2025, relier un constat à la bonne famille, comparer 2021 et 2025, puis expliquer ce que le Top 10 apporte et ce qu’il ne remplace pas."},{"type":"callout","content":"Prérequis : avoir déjà vu ce qu’est une surface d’attaque et pourquoi une même application accumule plusieurs familles de faiblesses."},{"type":"callout","content":"Mise en situation : Koffi doit préparer un mini-audit pour la boutique Soleil. Son responsable lui demande « de vérifier l’OWASP Top 10 ». S’il prend cette demande au pied de la lettre, il risque de cocher dix cases trop vite. Il doit au contraire s’en servir pour structurer son regard, puis compléter avec des exigences et une méthode de test."},{"type":"callout","content":"Vidéo à venir : Utiliser l’OWASP Top 10 sans en faire une béquille"},{"type":"text","content":"L’OWASP est une fondation communautaire qui produit des guides pratiques sur la sécurité applicative. Le Top 10 est un document de sensibilisation : il regroupe les familles de risques web les plus importantes à un moment donné, à partir de données et d’un consensus de terrain. C’est très utile pour former une équipe, classer des constats et parler le même langage. Ce n’est pas, à lui seul, une norme de vérification complète."},{"type":"schema","content":"{\"v\":1,\"kind\":\"steps\",\"title\":\"OWASP Top 10:2025, en ordre\",\"numbered\":true,\"items\":[{\"title\":\"A01 Broken Access Control\"},{\"title\":\"A02 Security Misconfiguration\"},{\"title\":\"A03 Software Supply Chain Failures\"},{\"title\":\"A04 Cryptographic Failures\"},{\"title\":\"A05 Injection\"},{\"title\":\"A06 Insecure Design\"},{\"title\":\"A07 Authentication Failures\"},{\"title\":\"A08 Software or Data Integrity Failures\"},{\"title\":\"A09 Security Logging & Alerting Failures\"},{\"title\":\"A10 Mishandling of Exceptional Conditions\"}]}"},{"type":"text","content":"Chaque catégorie résume une famille, pas une seule faiblesse. A01 couvre par exemple l’IDOR, la fonction interdite exposée, le SSRF et le CSRF quand ils révèlent un contrôle d’accès défaillant. A02 parle de mauvaise configuration : mode debug, stockage public, en-têtes absents, CORS trop large, méthodes inutiles, pages d’erreur bavardes. A03 élargit l’ancienne question des composants vulnérables à toute la chaîne d’approvisionnement : dépendances, build, distribution, scripts d’installation et confiance mal placée. A04 vise les défaillances cryptographiques, comme un secret mal protégé ou un chiffrement mal appliqué. A05 regroupe les injections SQL, de commandes, NoSQL ou de gabarits."},{"type":"text","content":"A06 concerne la conception non sécurisée : une logique métier qui oublie les abus prévisibles reste fragile même avec un bon correctif local. A07 couvre les défaillances d’authentification, comme une MFA contournable ou une réinitialisation de mot de passe trop faible. A08 vise l’intégrité des mises à jour, des builds et des données signées. A09 traite de la journalisation et des alertes qui ne permettent pas de détecter ni de comprendre un abus. A10 couvre la mauvaise gestion des conditions exceptionnelles : erreurs, limites, délais d’attente, surcharge et comportements inattendus qui font tomber l’application ou fuir trop d’informations."},{"type":"schema","content":"{\"v\":1,\"kind\":\"table\",\"title\":\"Ce qui change entre 2021 et 2025\",\"columns\":[\"Sujet\",\"2021\",\"2025\"],\"rows\":[[\"SSRF\",\"A10\",\"rattaché à A01\"],[\"Supply chain\",\"A06 élargi\",\"A03\"],[\"Misconfiguration\",\"A05\",\"A02\"],[\"Exceptional conditions\",\"absent\",\"nouvelle A10\"]]}"},{"type":"text","content":"Le bon usage du Top 10 est simple : cartographier tes constats, former les développeurs, repérer les angles morts récurrents et prioriser une première revue. Le mauvais usage consiste à conclure « site conforme » parce qu’aucun constat n’entre clairement dans dix intitulés. Pour vérifier en profondeur, tu complètes avec l’ASVS, qui décrit des exigences de sécurité, et avec le WSTG, qui donne une méthode de test. Pour les API, tu ajoutes le Top 10 API 2023."},{"type":"text","content":"Démonstration guidée : le script suivant classe huit constats inventés dans des catégories 2025. Le but n’est pas de faire croire qu’un programme remplace le jugement humain. Il montre plutôt qu’un même audit peut être raconté avec un vocabulaire stable, utile ensuite dans un rapport ou un tableau de suivi."},{"type":"code","content":"const findings = {\n  ''Page admin sans verification de role'': ''A01 Broken Access Control'',\n  ''Bucket public et mode debug actif'': ''A02 Security Misconfiguration'',\n  ''Dependance typosquattee dans la CI'': ''A03 Software Supply Chain Failures'',\n  ''Requete SQL concatenee avec une entree'': ''A05 Injection'',\n  ''Jeton de reinitialisation faible'': ''A07 Authentication Failures'',\n  ''Secret signe dans le depot de build'': ''A08 Software or Data Integrity Failures'',\n  ''Journal absent sur changement de role'': ''A09 Security Logging & Alerting Failures'',\n  ''Application qui fuit en 500 sur un format inattendu'': ''A10 Mishandling of Exceptional Conditions'',\n};\nconsole.log(findings);\n// exemple de sortie (valeurs fictives)\n// ''Page admin sans verification de role'': ''A01 Broken Access Control''\n// ''Dependance typosquattee dans la CI'': ''A03 Software Supply Chain Failures''\n// ''Application qui fuit en 500 sur un format inattendu'': ''A10 Mishandling of Exceptional Conditions''","language":"javascript"},{"type":"example","content":"Exemple corrigé : un « bucket public et mode debug actif » relève mieux de A02 que de A09. Le problème principal n’est pas l’absence d’alerte, mais la mauvaise configuration elle-même. À l’inverse, une application qui ne journalise pas les changements de rôle touche directement A09, même si aucun compte n’a encore été abusé. Le Top 10 t’aide donc à ranger un constat selon sa famille dominante, pas à nier les recouvrements possibles."},{"type":"callout","content":"Erreurs fréquentes : traiter le Top 10 comme une certification ; oublier de préciser l’édition citée ; ranger mécaniquement chaque bug dans la première catégorie qui « ressemble » ; croire qu’une application est sûre parce qu’elle n’a pas encore été testée contre l’ASVS ou le WSTG."},{"type":"callout","content":"Sécurité : les catégories OWASP servent à défendre, pas à fournir un mode d’emploi d’exploitation. Quand tu prépares un audit réel, reste dans le périmètre autorisé et privilégie les plateformes d’entraînement légales pour apprendre les gestes techniques hors production."},{"type":"callout","content":"À retenir : le Top 10:2025 est une carte de lecture, pas la totalité du territoire. Il aide à classer, sensibiliser et prioriser. Pour vérifier en profondeur, complète-le avec le Top 10 API 2023, l’ASVS et le WSTG."},{"type":"callout","content":"Pour pratiquer : Travaille dans « Projet final : auditer l’application de réservation et rédiger le rapport » : cette leçon te prépare à classer honnêtement les constats du projet, mais le projet lui-même demande ensuite de prouver, noter et recommander. Termine par le quiz."},{"type":"resource","content":"OWASP : le Top 10:2025 des risques applicatifs (en anglais)","url":"https://top10.owasp.org/2025/"},{"type":"resource","content":"OWASP : le Top 10 de la sécurité des API (2023) (en anglais)","url":"https://owasp.org/API-Security/editions/2023/en/0x11-t10/"},{"type":"resource","content":"OWASP : l’Application Security Verification Standard (ASVS) (en anglais)","url":"https://owasp.org/www-project-application-security-verification-standard/"},{"type":"resource","content":"OWASP : le guide de test de sécurité web (WSTG) (en anglais)","url":"https://owasp.org/www-project-web-security-testing-guide/"}]}'::jsonb, 24, 30, 2),
  ('cc3864f5-d03f-ebac-19eb-79059e2edfb1', '40abe0c4-0341-1c25-adee-8292a16408cf', '294a25d0-64a7-c3ad-e0d2-7f12ca297dcb', 'Vulnérabilité, CVE, CWE et CVSS : parler le même langage', 'Cette leçon t’aide à distinguer une faiblesse, une vulnérabilité précise et une note de gravité, puis à calculer et interpréter un score CVSS v3.1 sans le confondre avec le risque.', '{"blocks":[{"type":"callout","content":"Objectifs : distinguer CVE, CWE, CVSS, NVD et EPSS, lire un vecteur CVSS v3.1, recalculer une note de base, puis expliquer pourquoi la gravité technique ne suffit pas à mesurer le risque."},{"type":"callout","content":"Prérequis : savoir ce qu’est une faiblesse applicative et pourquoi plusieurs constats peuvent appartenir à une même famille."},{"type":"callout","content":"Mise en situation : Fatou lit un avis de sécurité qui mentionne un CVE, plusieurs CWE et une note CVSS 9,8. Son équipe conclut tout de suite « risque critique partout ». Fatou doit remettre de l’ordre : comprendre ce que chaque sigle décrit, recalculer la note, puis ajouter le contexte de l’application avant de prioriser."},{"type":"callout","content":"Vidéo à venir : Lire un avis de vulnérabilité sans mélanger les sigles"},{"type":"text","content":"Une vulnérabilité précise dans un produit reçoit souvent un identifiant CVE, par exemple « CVE-2024-0001 ». Une CWE décrit au contraire un type de faiblesse, comme « CWE-89 » pour l’injection SQL ou « CWE-78 » pour l’injection de commandes. La NVD de NIST agrège et enrichit beaucoup de CVE. CVSS mesure la gravité technique d’une vulnérabilité. EPSS estime une probabilité d’exploitation à court terme. Le catalogue KEV de la CISA signale, lui, les vulnérabilités dont l’exploitation réelle est déjà confirmée. Quand tu lis une fiche CVE, relève au minimum le produit touché, les versions concernées, la CWE associée, le vecteur CVSS, la disponibilité d’un correctif et la présence éventuelle dans EPSS ou KEV. Ces objets se complètent, mais ne veulent pas dire la même chose."},{"type":"schema","content":"{\"v\":1,\"kind\":\"cards\",\"title\":\"Même langage, rôles différents\",\"columns\":2,\"items\":[{\"term\":\"CWE\",\"text\":\"type de faiblesse\",\"tone\":\"amber\"},{\"term\":\"CVE\",\"text\":\"cas précis dans un produit\",\"tone\":\"red\"},{\"term\":\"NVD\",\"text\":\"base enrichie de vulnérabilités\",\"tone\":\"blue\"},{\"term\":\"CVSS\",\"text\":\"gravité technique\",\"tone\":\"violet\"},{\"term\":\"EPSS\",\"text\":\"probabilité estimée d’exploitation\",\"tone\":\"green\"}],\"caption\":\"Exemple : une CVE peut relever de CWE-89 et recevoir une note CVSS de 9,8.\"}"},{"type":"text","content":"Le score CVSS v3.1 de base repose sur huit métriques : AV, AC, PR, UI, S, C, I et A. Tu lis ainsi comment l’attaque arrive, si elle demande des privilèges ou une interaction, si elle change de portée, et quels impacts elle produit sur la confidentialité, l’intégrité et la disponibilité. La note finale va de 0,0 à 10,0 et s’arrondit toujours au dixième supérieur, pas au plus proche."},{"type":"schema","content":"{\"v\":1,\"kind\":\"table\",\"title\":\"CVSS v3.1 : rappels utiles\",\"columns\":[\"Métrique\",\"Valeurs\",\"Sens\"],\"rows\":[[\"AV\",\"N/A/L/P\",\"vecteur d’attaque\"],[\"AC\",\"L/H\",\"complexité\"],[\"PR\",\"N/L/H\",\"privilèges requis\"],[\"UI\",\"N/R\",\"interaction utilisateur\"],[\"S\",\"U/C\",\"portée\"],[\"C I A\",\"N/L/H\",\"impacts\"]],\"caption\":\"Bandes : 0,0 aucune ; 0,1-3,9 faible ; 4,0-6,9 moyenne ; 7,0-8,9 élevée ; 9,0-10,0 critique.\"}"},{"type":"text","content":"Démonstration guidée : le script suivant implémente la formule officielle CVSS v3.1 avec son arrondi supérieur. Il calcule trois vecteurs, dont deux classiques : 9,8 pour un cas réseau sans privilège ni interaction avec impact fort sur C, I et A, puis 6,1 pour un cas demandant une interaction utilisateur et une portée modifiée. Le code a été exécuté avec Node.js et les deux premières notes ont été recoupées avec les exemples publiés par FIRST et le calculateur officiel."},{"type":"code","content":"const AV={N:.85,A:.62,L:.55,P:.2},AC={L:.77,H:.44},UI={N:.85,R:.62},CIA={H:.56,L:.22,N:0};\nconst up=(n)=>{const i=Math.round(n*100000);return i%10000===0?i/100000:(Math.floor(i/10000)+1)/10};\nconst pr=(v,s)=>v===''N''?0.85:v===''L''?(s===''C''?0.68:0.62):(s===''C''?0.5:0.27);\nfunction score(vector){\n  const x=Object.fromEntries(vector.replace(''CVSS:3.1/'','''').split(''/'').map((p)=>p.split('':'')));\n  const iss=1-((1-CIA[x.C])*(1-CIA[x.I])*(1-CIA[x.A]));\n  const impact=x.S===''U''?6.42*iss:7.52*(iss-0.029)-3.25*Math.pow(iss-0.02,15);\n  const exploit=8.22*AV[x.AV]*AC[x.AC]*pr(x.PR,x.S)*UI[x.UI];\n  return impact<=0?0:(x.S===''U''?up(Math.min(impact+exploit,10)):up(Math.min(1.08*(impact+exploit),10)));\n}\nconsole.log(score(''CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H''));\nconsole.log(score(''CVSS:3.1/AV:N/AC:L/PR:N/UI:R/S:C/C:L/I:L/A:N''));\nconsole.log(score(''CVSS:3.1/AV:L/AC:H/PR:H/UI:R/S:U/C:L/I:L/A:L''));\n// exemple de sortie (valeurs fictives)\n// 9.8\n// 6.1\n// 3.8","language":"javascript"},{"type":"text","content":"Une note CVSS n’est pas un risque d’organisation. Une faille à 9,8 sur un composant inaccessible depuis Internet peut être moins urgente qu’une faiblesse à 6,1 déjà exposée sur un portail métier critique sans journalisation correcte. Tu ajoutes donc le contexte : valeur de l’actif, exposition réelle, présence d’un correctif, exploitation connue, délai acceptable et capacité de détection. CVSS 4.0 existe déjà, mais la version 3.1 reste très utilisée et mérite d’être comprise."},{"type":"example","content":"Exemple corrigé : « CVE-2024-0001, CWE-89, CVSS 9,8 » se lit ainsi. La faiblesse de fond est une injection SQL, décrite par la CWE. La vulnérabilité précise dans un produit donné est identifiée par la CVE. Sa gravité technique de base est critique selon CVSS. Si l’application touchée n’est joignable que sur un réseau d’administration segmenté, la priorité de correction peut rester très élevée, mais le risque métier n’est pas identique à celui d’un portail client exposé publiquement."},{"type":"callout","content":"Erreurs fréquentes : prendre un score CVSS pour un risque métier complet ; confondre une CWE avec une CVE ; lire « 9,8 » sans regarder le vecteur ; oublier qu’une base de vulnérabilités enrichie ne remplace pas la connaissance de son propre périmètre."},{"type":"callout","content":"Sécurité : la lecture d’un avis de sécurité reste défensive : tu comprends une faiblesse pour corriger, prioriser et vérifier. N’essaie jamais d’exploiter une CVE sur un système réel hors périmètre autorisé, même « juste pour confirmer »."},{"type":"callout","content":"À retenir : CWE décrit la famille, CVE décrit le cas précis, CVSS mesure la gravité technique. Le vecteur compte autant que la note. Une priorité de correction sérieuse combine la gravité, l’exposition et le contexte métier."},{"type":"callout","content":"Pour pratiquer : Travaille dans « TP 6 : configuration, dépendances et notation CVSS » : tu y liras des vecteurs, recalculeras des notes et prioriseras des constats sans confondre gravité et risque. Termine ensuite par le quiz."},{"type":"resource","content":"CVE : le programme des identifiants de vulnérabilités (en anglais)","url":"https://www.cve.org/"},{"type":"resource","content":"CWE : la liste des faiblesses logicielles (en anglais)","url":"https://cwe.mitre.org/"},{"type":"resource","content":"FIRST : spécification CVSS v3.1 (en anglais)","url":"https://www.first.org/cvss/v3.1/specification-document"},{"type":"resource","content":"FIRST : EPSS, la probabilité d’exploitation d’une vulnérabilité (en anglais)","url":"https://www.first.org/epss/"},{"type":"resource","content":"CISA : le catalogue des vulnérabilités exploitées (KEV) (en anglais)","url":"https://www.cisa.gov/known-exploited-vulnerabilities-catalog"}]}'::jsonb, 26, 30, 3),
  ('bfba48bd-79c7-d629-1a5a-f63ec0a56915', '40abe0c4-0341-1c25-adee-8292a16408cf', 'ea34b780-982c-e579-95c4-bd5a43917439', 'Injection SQL : comprendre, reconnaître et empêcher', 'Tu vas voir comment une entrée non fiable devient du SQL, comment reconnaître les signes d’une injection dans du code ou un journal, et comment la bloquer proprement avec des requêtes paramétrées.', '{"blocks":[{"type":"callout","content":"Objectifs : expliquer le mécanisme d’une injection SQL, reconnaître une concaténation dangereuse, lire des indices dans un journal, puis corriger avec des requêtes paramétrées et des privilèges minimaux."},{"type":"callout","content":"Prérequis : avoir vu ce qu’est une requête HTTP, une base relationnelle simple et une frontière de confiance côté serveur."},{"type":"callout","content":"Mise en situation : Moussa maintient une petite application d’adhésion pour Baobab Tech. Une recherche d’utilisateur fonctionne « depuis toujours », mais les journaux montrent des apostrophes, des « OR 1=1 » et des réponses anormalement longues. Avant de parler d’attaque confirmée, Moussa veut comprendre le mécanisme, montrer la mauvaise pratique et prouver la correction."},{"type":"callout","content":"Vidéo à venir : Voir l’injection SQL comme une confusion entre code et données"},{"type":"text","content":"Une injection SQL apparaît quand une donnée non fiable est interprétée comme une partie de la requête au lieu de rester une simple valeur. Le problème n’est pas le caractère apostrophe lui-même : c’est la concaténation qui donne à l’entrée le pouvoir de casser la structure de la requête. Une injection peut alors lire trop de lignes, modifier des données, contourner une authentification ou provoquer des erreurs utiles à l’attaquant."},{"type":"schema","content":"{\"v\":1,\"kind\":\"compare\",\"title\":\"Chemin dangereux et chemin correct\",\"sides\":[{\"title\":\"Chemin dangereux\",\"tone\":\"red\",\"mark\":\"cross\",\"items\":[\"requête HTTP : paramètre q\",\"q est concaténé dans SQL\",\"la base interprète le tout comme du code\"]},{\"title\":\"Chemin correct\",\"tone\":\"green\",\"mark\":\"check\",\"items\":[\"requête HTTP : paramètre q\",\"q passe par un placeholder ?\",\"la base sépare code et valeur\"]}]}"},{"type":"text","content":"Les formes d’injection varient. En bande, l’attaquant récupère directement plus de données. En aveugle booléen, il observe seulement une différence de réponse. En aveugle par délai, il mesure un ralentissement. En second ordre, une donnée injectée est stockée puis réinterprétée plus tard. Même sans message d’erreur visible, l’injection reste possible. C’est pourquoi masquer les erreurs aide, mais ne remplace jamais la séparation du code et des données."},{"type":"text","content":"Démonstration guidée : l’exemple ci-dessous crée une petite base mémoire avec « node:sqlite ». Commence par vérifier ta version avec « node --version ». Le module existe depuis Node.js 22.5.0, mais sans drapeau expérimental seulement à partir de 22.13.0. Si ta version est plus ancienne, mets Node.js à jour avant de suivre cette démonstration. La version vulnérable fabrique la requête par concaténation. La version sûre utilise un paramètre. Le test a été exécuté avec Node.js sur des valeurs fictives de la leçon."},{"type":"code","content":"const { DatabaseSync } = require(''node:sqlite'');\nconst db = new DatabaseSync('':memory:'');\ndb.exec(\"CREATE TABLE users (id INTEGER PRIMARY KEY, name TEXT, role TEXT);\");\nfor (const row of [[''Ama'',''membre''],[''Koffi'',''admin''],[''Awa'',''membre'']]) {\n  db.prepare(''INSERT INTO users (name, role) VALUES (?, ?)'').run(...row);\n}\nconst userInput = \"Ama'' OR ''1''=''1\";\nconst unsafeSql = \"SELECT name FROM users WHERE name = ''\" + userInput + \"''\";\nconst unsafeRows = db.prepare(unsafeSql).all().map((r) => r.name);\nconst safeRows = db.prepare(''SELECT name FROM users WHERE name = ?'').all(userInput).map((r) => r.name);\nconsole.log({ unsafeSql, unsafeRows, safeRows });\n// exemple de sortie (valeurs fictives)\n// unsafeSql: SELECT name FROM users WHERE name = ''Ama'' OR ''1''=''1''\n// unsafeRows: [ ''Ama'', ''Koffi'', ''Awa'' ]\n// safeRows: []","language":"javascript"},{"type":"schema","content":"{\"v\":1,\"kind\":\"cards\",\"title\":\"Indices utiles dans un journal d’accès\",\"items\":[{\"term\":\"%27, apostrophes, --\",\"text\":\"caractères et commentaires répétés\",\"tone\":\"amber\"},{\"term\":\"UNION SELECT\",\"text\":\"recherche d’exfiltration ou d’énumération\",\"tone\":\"red\"},{\"term\":\"OR 1=1, sleep(, benchmark(\",\"text\":\"contournement booléen ou temporisation\",\"tone\":\"red\"},{\"term\":\"500 ou lenteur\",\"text\":\"rafale d’erreurs ou réponses anormalement lentes\",\"tone\":\"violet\"}],\"columns\":2}"},{"type":"text","content":"La défense principale tient en quatre points. D’abord, requêtes paramétrées partout où une valeur varie. Ensuite, liste autorisée pour les identifiants que la base ne paramètre pas, comme un nom de colonne ou le sens d’un tri. Puis moindre privilège pour le compte de base : pas de droits inutiles, pas d’accès à d’autres schémas. Enfin, erreurs détaillées côté serveur seulement. Un WAF peut réduire le bruit ou gagner du temps, mais il ne corrige pas le code."},{"type":"example","content":"Exemple corrigé : « SELECT * FROM users WHERE id = ? » est sûr sur le plan de l’injection si le pilote lie vraiment la valeur au placeholder. « SELECT * FROM users WHERE id = \" + req.query.id » est vulnérable parce qu’il mêle structure et donnée. « SELECT * FROM users ORDER BY \" + req.query.sort » reste dangereux même si le reste de la requête est paramétré, car un identifiant SQL ne se traite pas comme une valeur ordinaire : il faut une liste autorisée de colonnes et de directions."},{"type":"callout","content":"Erreurs fréquentes : croire qu’échapper quelques caractères remplace les requêtes paramétrées ; penser qu’un ORM protège même quand on lui passe du SQL brut ; oublier les noms de colonnes et l’ordre de tri dans la liste autorisée ; exposer au client le message d’erreur complet du moteur SQL."},{"type":"callout","content":"Sécurité : les chaînes d’exemple ici servent à comprendre et corriger sur une base fictive locale. Tu ne réessaies jamais ces motifs sur un site tiers. Analyse seulement tes journaux, ton code ou un environnement expressément autorisé, puis corrige et vérifie."},{"type":"callout","content":"À retenir : l’injection SQL n’est pas une question de caractère interdit, mais de séparation entre code et données. Paramètre les valeurs, autorise explicitement les identifiants, limite les privilèges de la base et garde les détails d’erreur côté serveur."},{"type":"callout","content":"Pour pratiquer : Travaille dans « TP 2 : injections : reconnaître, comprendre et corriger » pour repérer la route vulnérable et la bonne correction. Tu peux aussi relire « Intrusion web : du scan au webshell » pour voir ce que ces tentatives laissent dans un journal d’accès. Termine par le quiz."},{"type":"resource","content":"OWASP : aide-mémoire sur la prévention de l’injection SQL (en anglais)","url":"https://cheatsheetseries.owasp.org/cheatsheets/SQL_Injection_Prevention_Cheat_Sheet.html"},{"type":"resource","content":"OWASP : aide-mémoire sur les requêtes paramétrées (en anglais)","url":"https://cheatsheetseries.owasp.org/cheatsheets/Query_Parameterization_Cheat_Sheet.html"},{"type":"resource","content":"CWE-89 : injection SQL (en anglais)","url":"https://cwe.mitre.org/data/definitions/89.html"},{"type":"resource","content":"PHP : les requêtes préparées avec PDO","url":"https://www.php.net/manual/fr/pdo.prepared-statements.php"},{"type":"resource","content":"Node.js : le module node:sqlite (en anglais)","url":"https://nodejs.org/api/sqlite.html"}]}'::jsonb, 26, 30, 1),
  ('429c3614-039f-27d2-ce85-c920ba2fb553', '40abe0c4-0341-1c25-adee-8292a16408cf', 'ea34b780-982c-e579-95c4-bd5a43917439', 'Injections de commandes, NoSQL et modèles : la même famille, les mêmes remèdes', 'Cette leçon relie plusieurs injections moins visibles à la même cause profonde : une donnée non fiable qui traverse un interpréteur sans garde suffisante.', '{"blocks":[{"type":"callout","content":"Objectifs : reconnaître une injection de commandes, un filtre NoSQL dangereux et une SSTI, comparer leurs remèdes, puis choisir la défense la plus simple avant d’ajouter des validations complémentaires."},{"type":"callout","content":"Prérequis : avoir compris le principe général d’une injection et la différence entre code et donnée."},{"type":"callout","content":"Mise en situation : Awa corrige une application interne qui fait trois choses : elle lance un « ping » depuis un champ d’administration, elle construit un filtre JSON pour une connexion et elle affiche un modèle enrichi par l’utilisateur. Les bugs n’ont pas le même nom, mais Awa soupçonne la même erreur de fond."},{"type":"callout","content":"Vidéo à venir : Reconnaître la même famille d’injections derrière des technologies différentes"},{"type":"text","content":"L’injection de commandes du système apparaît quand une entrée utilisateur traverse un shell ou une commande construite comme une chaîne unique. L’injection NoSQL apparaît quand un objet JSON inattendu, par exemple avec « $ne » ou « $gt », est traité comme un filtre valide. La SSTI, ou injection de gabarit côté serveur, survient quand on compile ou évalue un modèle contenant une entrée non fiable. LDAP, XPath et même certains journaux peuvent tomber dans la même famille."},{"type":"schema","content":"{\"v\":1,\"kind\":\"cards\",\"title\":\"Même cause, interpréteurs différents\",\"columns\":2,\"items\":[{\"term\":\"shell\",\"text\":\"commande système concaténée\",\"tone\":\"red\"},{\"term\":\"NoSQL\",\"text\":\"opérateur JSON non attendu\",\"tone\":\"amber\"},{\"term\":\"SSTI\",\"text\":\"modèle compilé avec entrée\",\"tone\":\"red\"},{\"term\":\"LDAP\",\"text\":\"filtre concaténé\",\"tone\":\"amber\"},{\"term\":\"XPath\",\"text\":\"expression concaténée\",\"tone\":\"amber\"},{\"term\":\"journal\",\"text\":\"saut de ligne ou faux champ\",\"tone\":\"violet\"}]}"},{"type":"text","content":"La hiérarchie des remèdes commence avant la validation. Premier choix : éviter l’interpréteur quand ce n’est pas nécessaire. Deuxième choix : utiliser une API qui prend des arguments séparés, pas une chaîne. Troisième choix : valider par liste autorisée ce qui doit vraiment passer. Puis seulement, ajouter de l’encodage adapté au contexte et des privilèges minimaux. Nettoyer quelques caractères à la main ne suffit pas."},{"type":"schema","content":"{\"v\":1,\"kind\":\"steps\",\"title\":\"Ordre de défense recommandé\",\"numbered\":true,\"items\":[{\"title\":\"Éviter l’interpréteur\"},{\"title\":\"Paramétrer ou séparer les arguments\"},{\"title\":\"Valider par liste autorisée\"},{\"title\":\"Encoder selon le contexte\"},{\"title\":\"Limiter les privilèges\"}]}"},{"type":"text","content":"Démonstration guidée : ce script montre deux erreurs fréquentes. Vérifie d’abord « node --version ». Le code utilise l’API Node.js « child_process.execFileSync » et le binaire local « ping » : l’exemple ci-dessous choisit « -n » sous Windows et « -c » sous macOS ou Linux. D’un côté, une version vulnérable construit la commande comme une chaîne. De l’autre, une version sûre refuse les hôtes hors liste autorisée et passe les arguments séparément. Le même script refuse aussi un objet JSON inattendu pour une connexion NoSQL fictive. La chaîne vulnérable est seulement affichée, pas exécutée."},{"type":"code","content":"const { execFileSync } = require(''node:child_process'');\nfunction pingArgs(host){ return process.platform === ''win32'' ? [''-n'', ''1'', host] : [''-c'', ''1'', host]; }\nfunction buildUnsafe(host){ return ''ping '' + pingArgs(host).join('' ''); }\nfunction safePing(host){\n  if (!/^[A-Za-z0-9.-]+$/.test(host) || host.startsWith(''-'')) return { host, status: ''rejected'' };\n  execFileSync(''ping'', pingArgs(host), { encoding: ''utf8'' });\n  return { host, status: ''ok'' };\n}\nfunction safeLoginFilter(body){\n  if (typeof body.username !== ''string'') return { status: ''rejected'', reason: ''username type'' };\n  return { status: ''ok'', filter: { username: body.username } };\n}\nconsole.log({\n  unsafeCommand: buildUnsafe(''localhost;whoami''),\n  safePingLocalhost: safePing(''localhost''),\n  safePingRejected: safePing(''localhost;whoami''),\n  safeLoginOk: safeLoginFilter({ username: ''awa'' }),\n  safeLoginRejected: safeLoginFilter({ username: { ''$ne'': '''' } }),\n});\n// exemple de sortie (valeurs fictives)\n// unsafeCommand: ''ping -n 1 localhost;whoami''\n// safePingLocalhost: { host: ''localhost'', status: ''ok'' }\n// safePingRejected: { host: ''localhost;whoami'', status: ''rejected'' }\n// safeLoginRejected: { status: ''rejected'', reason: ''username type'' }","language":"javascript"},{"type":"text","content":"Pour les modèles côté serveur, la règle la plus sûre est simple : ne compile jamais un modèle qui contient une entrée utilisateur comme s’il s’agissait d’un morceau de code. Pour LDAP ou XPath, le raisonnement est le même qu’en SQL : pas de concaténation naïve. Pour les journaux, pense aussi à l’injection de sauts de ligne ou de faux séparateurs qui fabriquent une trace trompeuse."},{"type":"example","content":"Exemple corrigé : « ping -n 1 \" + host » est dangereux parce qu’il délègue l’interprétation au shell ou à la commande finale. « execFile(''ping'', [''-n'', ''1'', host]) » réduit fortement ce risque, mais seulement si « host » a été validé. Un objet « { username: { ''$ne'': '''' } } » ne doit jamais être accepté comme s’il s’agissait d’un simple nom d’utilisateur. Enfin, une entrée de support qui contient « \\nadmin=true » ne devrait pas pouvoir fabriquer une ligne de journal plus crédible qu’elle ne l’est réellement."},{"type":"callout","content":"Erreurs fréquentes : croire que seules les bases SQL sont concernées par les injections ; exécuter la chaîne vulnérable « pour voir » ; accepter un objet JSON entier quand une chaîne était attendue ; laisser un moteur de gabarit interpréter du texte fourni par l’utilisateur."},{"type":"callout","content":"Sécurité : les exemples restent défensifs et locaux. Tu n’exécutes jamais une chaîne de commande construite avec une entrée non fiable sur une machine réelle hors laboratoire. Quand tu analyses des journaux, rappelle-toi qu’ils peuvent contenir des données personnelles et des noms internes."},{"type":"callout","content":"À retenir : commande, filtre NoSQL, gabarit, LDAP ou XPath : la technologie change, mais l’erreur de fond reste la même. Sépare le code et la donnée, valide ce qui doit passer, puis réduis les privilèges pour limiter les dégâts si quelque chose échappe au contrôle."},{"type":"callout","content":"Pour pratiquer : Travaille dans « TP 2 : injections : reconnaître, comprendre et corriger » pour distinguer le point d’injection, le mauvais correctif et le vrai remède. Termine ensuite par le quiz."},{"type":"resource","content":"OWASP : aide-mémoire sur la défense contre l’injection de commandes (en anglais)","url":"https://cheatsheetseries.owasp.org/cheatsheets/OS_Command_Injection_Defense_Cheat_Sheet.html"},{"type":"resource","content":"OWASP : aide-mémoire sur la validation des entrées (en anglais)","url":"https://cheatsheetseries.owasp.org/cheatsheets/Input_Validation_Cheat_Sheet.html"},{"type":"resource","content":"CWE-78 : injection de commandes du système (en anglais)","url":"https://cwe.mitre.org/data/definitions/78.html"},{"type":"resource","content":"OWASP : aide-mémoire sur la désérialisation (en anglais)","url":"https://cheatsheetseries.owasp.org/cheatsheets/Deserialization_Cheat_Sheet.html"},{"type":"resource","content":"Node.js : le module child_process (en anglais)","url":"https://nodejs.org/api/child_process.html"}]}'::jsonb, 24, 30, 2),
  ('63895085-543d-c970-d288-3c4ff3b97a59', '40abe0c4-0341-1c25-adee-8292a16408cf', 'ea34b780-982c-e579-95c4-bd5a43917439', 'Valider, normaliser et encoder : la règle des entrées et des sorties', 'Tu apprendras à traiter toute donnée comme non fiable, à la normaliser avant validation, puis à encoder correctement les sorties sans croire qu’une seule règle protège tous les contextes.', '{"blocks":[{"type":"callout","content":"Objectifs : normaliser une entrée avant validation, choisir une liste autorisée, distinguer validation et encodage, reconnaître plusieurs contextes de sortie, puis tester un validateur sur des cas normaux et piégés."},{"type":"callout","content":"Prérequis : avoir compris que la sécurité côté client ne remplace jamais la vérification côté serveur."},{"type":"callout","content":"Mise en situation : Nadia reprend un formulaire d’inscription pour l’association Teranga. Le développeur précédent « nettoyait » quelques caractères puis affichait la même donnée dans un e-mail, une page HTML et un nom de fichier. Nadia veut remettre de l’ordre : quoi valider, quoi normaliser, quoi rejeter, et quoi encoder seulement au moment de la sortie."},{"type":"callout","content":"Vidéo à venir : Traiter les entrées et les sorties sans tout mélanger"},{"type":"text","content":"Toute entrée est non fiable : formulaire, URL, cookie, en-tête, corps JSON, fichier téléversé, donnée venue d’une API tierce ou d’un journal relu plus tard. Valider, c’est vérifier que la donnée correspond au type, à la longueur, à la plage et au format attendus. Une liste autorisée est presque toujours préférable à une liste noire, car tu définis ce qui est acceptable au lieu d’essayer de deviner tout ce qui pourrait être dangereux."},{"type":"schema","content":"{\"v\":1,\"kind\":\"flow\",\"title\":\"Entrer, normaliser, valider, sortir\",\"nodes\":[{\"label\":\"entrée brute\",\"tone\":\"amber\"},{\"label\":\"normaliser\",\"tone\":\"blue\"},{\"label\":\"valider\",\"tone\":\"violet\"},{\"label\":\"stocker\",\"tone\":\"green\"}],\"caption\":\"Si la valeur est hors règles, on la rejette. À la sortie, on encode selon le contexte.\"}"},{"type":"text","content":"La normalisation vient avant la validation. Tu peux devoir unifier la casse, réduire les espaces, convertir un type, ou décoder une forme encodée comme « %2e%2e » avant de décider si la valeur est acceptable. Sans cela, une même donnée peut contourner un contrôle selon la manière dont elle est écrite. Normaliser ne veut pourtant pas dire « nettoyer pour faire passer ». Si la donnée ne respecte pas la règle, tu la rejettes."},{"type":"schema","content":"{\"v\":1,\"kind\":\"table\",\"title\":\"Contexte de sortie : encodage adapté\",\"columns\":[\"Contexte\",\"Règle\"],\"rows\":[[\"HTML\",\"encodage HTML\"],[\"attribut\",\"attribut entre guillemets + encodage\"],[\"JavaScript\",\"JSON ou textContent, pas d’injection directe\"],[\"URL\",\"valider le schéma puis encoder l’URL\"],[\"CSS\",\"éviter l’injection directe, limiter les valeurs\"],[\"SQL\",\"requêtes paramétrées\"],[\"shell\",\"arguments séparés, pas de concaténation\"]],\"mono\":[0]}"},{"type":"text","content":"Validation et encodage n’ont pas le même rôle. Tu valides au plus tôt pour refuser une donnée hors contrat et tu imposes aussi des tailles maximales raisonnables. Tu encodes au plus tard, au moment où tu sors cette donnée vers un contexte précis. Une adresse e-mail stockée en base peut être valide comme donnée métier, puis devoir encore être encodée pour être affichée dans du HTML. Inversement, un bon encodage HTML ne protège pas un appel SQL ou un shell. Les expressions régulières aident, mais un motif trop gourmand peut aussi provoquer un déni de service par consommation excessive."},{"type":"text","content":"Démonstration guidée : ce validateur Node.js normalise un petit formulaire d’inscription, puis rejette les champs hors contrat. Il montre aussi qu’un chemin contenant « %2e%2e%2f » doit être décodé avant d’être jugé. Les huit cas d’essai ci-dessous ont été exécutés avec Node.js."},{"type":"code","content":"const allowed = new Set([''BJ'',''CI'',''SN'',''TG'']);\nconst normalizeName = (v) => v.normalize(''NFKC'').trim().replace(/\\s+/g, '' '');\nconst decodePath = (v) => v.replace(/%2e/gi, ''.'').replace(/%2f/gi, ''/'');\nfunction validate(x){\n  const name = normalizeName(x.name || '''');\n  const age = Number(x.age);\n  const email = String(x.email || '''').trim().toLowerCase();\n  const country = String(x.country || '''').trim().toUpperCase();\n  const avatar = decodePath(String(x.avatar || '''').trim());\n  const errors = [];\n  if (!/^[A-Za-zÀ-ÖØ-öø-ÿ'' -]{2,40}$/.test(name)) errors.push(''name'');\n  if (!Number.isInteger(age) || age < 13 || age > 120) errors.push(''age'');\n  if (!/^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$/.test(email)) errors.push(''email'');\n  if (!allowed.has(country)) errors.push(''country'');\n  if (avatar.includes(''..'')) errors.push(''avatar'');\n  return { ok: errors.length === 0, errors, name, email, country, avatar };\n}\nconst samples = [\n  { name: '' Awa  Ndiaye '', age: ''19'', email: ''AWA@Example.org '', country: ''sn'', avatar: ''profil.png'' },\n  { name: ''Moussa'', age: ''40'', email: ''moussa@example.org'', country: ''SN'', avatar: ''%2e%2e%2fsecret.txt'' },\n  { name: ''Ama'', age: ''12'', email: ''ama@example.org'', country: ''BJ'', avatar: ''profil.png'' },\n  { name: ''Koffi'', age: ''27'', email: ''koffi@example'', country: ''CI'', avatar: ''profil.png'' },\n  { name: ''Fatou'', age: ''33'', email: ''fatou@example.org'', country: ''GH'', avatar: ''profil.png'' },\n  { name: '' Fatou\\u00A0Diop '', age: ''33'', email: ''fatou@example.org'', country: ''tg'', avatar: ''avatars%2Ffatou.png'' },\n  { name: ''A'', age: ''20'', email: ''a@example.org'', country: ''SN'', avatar: ''profil.png'' },\n  { name: ''Kwame'', age: ''200'', email: ''kwame@example.org'', country: ''TG'', avatar: ''profil.png'' },\n];\nconsole.log(samples.map(validate));\n// exemple de sortie (valeurs fictives)\n// { ok: true, errors: [], name: ''Awa Ndiaye'', email: ''awa@example.org'', country: ''SN'', avatar: ''profil.png'' }\n// { ok: false, errors: [ ''avatar'' ], name: ''Moussa'', email: ''moussa@example.org'', country: ''SN'', avatar: ''../secret.txt'' }\n// { ok: false, errors: [ ''country'' ], name: ''Fatou'', email: ''fatou@example.org'', country: ''GH'', avatar: ''profil.png'' }","language":"javascript"},{"type":"example","content":"Exemple corrigé : si ton formulaire attend un pays parmi « BJ », « CI », « SN » et « TG », la valeur « gh » ne doit pas être « réparée » silencieusement. Elle doit être rejetée avec un message sobre. De même, « %2e%2e%2fsecret.txt » ne doit pas passer parce que les caractères critiques ne sont pas encore visibles : après normalisation, le danger apparaît. Enfin, une adresse e-mail valide pour le métier reste une simple chaîne quand tu l’affiches : si elle part dans du HTML, tu l’encoderas encore pour ce contexte précis."},{"type":"callout","content":"Erreurs fréquentes : nettoyer à la volée au lieu de rejeter les données hors contrat ; oublier la normalisation avant validation ; croire qu’un bon encodage HTML protège aussi une requête SQL ; écrire une regex compliquée sans réfléchir à sa taille, à ses performances et aux cas qu’elle oublie."},{"type":"callout","content":"Sécurité : valider côté serveur reste indispensable, même si le navigateur t’aide côté confort. Quand tu testes des validations, fais-le sur ton application ou ton environnement d’essai. Et quand un journal contient des adresses, noms ou e-mails, évite de le diffuser sans nécessité."},{"type":"callout","content":"À retenir : toute entrée est non fiable. Normalise avant de valider, rejette plutôt que « nettoyer », puis encode au moment exact de la sortie selon le contexte. Une seule règle ne protège pas tous les interpréteurs."},{"type":"callout","content":"Pour pratiquer : Travaille dans « TP 2 : injections : reconnaître, comprendre et corriger » : tu y verras comment une validation insuffisante laisse passer des valeurs trompeuses et comment une correction défensive doit rester explicite. Termine par le quiz."},{"type":"resource","content":"OWASP : aide-mémoire sur la validation des entrées (en anglais)","url":"https://cheatsheetseries.owasp.org/cheatsheets/Input_Validation_Cheat_Sheet.html"},{"type":"resource","content":"OWASP : aide-mémoire sur la prévention du XSS (en anglais)","url":"https://cheatsheetseries.owasp.org/cheatsheets/Cross_Site_Scripting_Prevention_Cheat_Sheet.html"},{"type":"resource","content":"OWASP : aide-mémoire sur la prévention de l’injection SQL (en anglais)","url":"https://cheatsheetseries.owasp.org/cheatsheets/SQL_Injection_Prevention_Cheat_Sheet.html"},{"type":"resource","content":"CWE-79 : cross-site scripting (en anglais)","url":"https://cwe.mitre.org/data/definitions/79.html"}]}'::jsonb, 22, 30, 3),
  ('0ff76209-a64d-bc00-0da6-f1c1d5df89e6', '40abe0c4-0341-1c25-adee-8292a16408cf', '01b61988-3e06-bd60-c093-4b3ce7f7c72a', 'Cross-Site Scripting : réfléchi, stocké, DOM et leurs remèdes', 'Tu vas distinguer les trois familles de XSS, lire leurs points d’injection, puis appliquer le bon remède : encodage de sortie, DOM sûr, assainissement du HTML riche et défenses en profondeur.', '{"blocks":[{"type":"callout","content":"Objectifs : définir ce qu’un XSS permet, distinguer les variantes réfléchi, stocké et DOM, reconnaître un point d’injection, choisir le bon encodage selon le contexte, remplacer « innerHTML » quand il ne faut que du texte, et expliquer les limites d’une défense seule."},{"type":"callout","content":"Prérequis : avoir vu la différence entre une entrée non fiable et une sortie HTML, et savoir qu’un navigateur exécute du JavaScript dans l’origine du site affiché."},{"type":"callout","content":"Mise en situation : Chez Baobab Tech, Awa relit une page de commentaires et un petit script de recherche. Rien ne ressemble à une « attaque » spectaculaire : seulement du HTML, une zone de texte et quelques lignes JavaScript. Pourtant, si une donnée non fiable ressort sans protection, le navigateur l’exécutera avec les droits du site. Awa doit donc reconnaître où le script naît, ce qu’il peut faire, et surtout comment l’empêcher proprement."},{"type":"callout","content":"Vidéo à venir : Comprendre un XSS sans l’exécuter dans un navigateur"},{"type":"text","content":"Un XSS, ou cross-site scripting, apparaît quand une application renvoie ou réinsère une donnée non fiable dans une page sans la traiter pour son contexte réel. L’attaquant n’exécute pas son code « sur le serveur » : il le fait exécuter dans le navigateur de la victime, mais dans l’origine du site visité. Cela suffit pour lire ou modifier le contenu de la page, déclencher des actions avec la session courante, voler ce qui reste accessible à JavaScript, ou piéger l’utilisateur avec une interface trompeuse."},{"type":"schema","content":"{\"v\":1,\"kind\":\"cards\",\"title\":\"Trois familles à distinguer\",\"columns\":3,\"items\":[{\"term\":\"XSS réfléchi\",\"text\":\"La donnée revient dans la réponse à la même requête. Exemple : un terme de recherche réaffiché sans encodage.\",\"tone\":\"amber\",\"icon\":\"message\"},{\"term\":\"XSS stocké\",\"text\":\"La donnée dangereuse est enregistrée puis servie à d’autres. Exemple : un commentaire publié et relu plus tard.\",\"tone\":\"red\",\"icon\":\"database\"},{\"term\":\"XSS DOM\",\"text\":\"Le navigateur réinjecte lui-même la donnée dans le DOM. Exemple : un script lit `location.hash` puis écrit dans `innerHTML`.\",\"tone\":\"violet\",\"icon\":\"code\"}]}"},{"type":"text","content":"La correction dépend du contexte de sortie. Dans le corps HTML, tu échappes au minimum « & », « < », « > », « \" » et « '' ». Dans un attribut, tu gardes toujours des guillemets autour de la valeur, puis tu l’échappes aussi. Dans le JavaScript, tu n’insères jamais une chaîne brute dans du code : tu la sors en JSON sérialisé, puis tu la traites comme donnée. Dans le DOM, « textContent » convient quand tu veux afficher du texte ; « innerHTML » devient un point d’injection dès que tu lui donnes une donnée non fiable. Pour une URL, tu valides le schéma et tu refuses « javascript: ». Pour du HTML riche volontaire, tu passes par un assainissement éprouvé, par exemple DOMPurify, avec une liste autorisée de balises."},{"type":"text","content":"Les moteurs de gabarits modernes échappent souvent par défaut. Les failles viennent alors des contournements : « |safe », « {{{ ... }}} », « dangerouslySetInnerHTML », « v-html » ou une réinjection directe avec « innerHTML ». Une CSP stricte, des cookies « HttpOnly » et, selon le navigateur, « Trusted Types » limitent l’impact, mais aucune de ces défenses ne remplace l’encodage de sortie. De la même manière, filtrer des mots comme « script » ne suffit pas : tu dois raisonner par contexte, pas par liste noire."},{"type":"text","content":"Démonstration guidée : ce script Node.js ne lance aucun navigateur. Il montre seulement la différence entre une sortie brute et une sortie échappée. Avant de le rejouer, vérifie ta version avec « node --version ». Si Node.js est trop ancien pour cette syntaxe JavaScript, mets-le à jour vers une version LTS récente. Tu peux le relire comme un test défensif : si la sortie « sûre » contient encore des balises interprétables, la fonction d’encodage est insuffisante."},{"type":"code","content":"const escapeHtml = (value) => String(value)\n  .replace(/&/g, \"&amp;\")\n  .replace(/</g, \"&lt;\")\n  .replace(/>/g, \"&gt;\")\n  .replace(/\\\"/g, \"&quot;\")\n  .replace(/''/g, \"&#39;\");\n\nconst inputs = [\n  \"bonjour\",\n  \"<b>promo</b>\",\n  \"\\\"citation\\\" & déjà\",\n  \"<img src=x onerror=alert(1)>\",\n  \"Ama & Koffi <admin>\",\n];\n\nfor (const input of inputs) {\n  const unsafe = `<p>${input}</p>`;\n  const safe = `<p>${escapeHtml(input)}</p>`;\n  console.log(JSON.stringify({ input, unsafe, safe }));\n}\n// exemple de sortie (valeurs fictives)\n// {\"input\":\"bonjour\",\"unsafe\":\"<p>bonjour</p>\",\"safe\":\"<p>bonjour</p>\"}\n// {\"input\":\"<b>promo</b>\",\"unsafe\":\"<p><b>promo</b></p>\",\"safe\":\"<p>&lt;b&gt;promo&lt;/b&gt;</p>\"}\n// {\"input\":\"\\\"citation\\\" & déjà\",\"unsafe\":\"<p>\\\"citation\\\" & déjà</p>\",\"safe\":\"<p>&quot;citation&quot; &amp; déjà</p>\"}\n// {\"input\":\"<img src=x onerror=alert(1)>\",\"unsafe\":\"<p><img src=x onerror=alert(1)></p>\",\"safe\":\"<p>&lt;img src=x onerror=alert(1)&gt;</p>\"}\n// {\"input\":\"Ama & Koffi <admin>\",\"unsafe\":\"<p>Ama & Koffi <admin></p>\",\"safe\":\"<p>Ama &amp; Koffi &lt;admin&gt;</p>\"}","language":"javascript"},{"type":"example","content":"Exemple corrigé : dans un journal d’accès, la chaîne « <script>alert(1)</script> » ou « <img src=x onerror=alert(1)> » signale une tentative, pas forcément une réussite. Si ton application la renvoie ensuite telle quelle dans une page de recherche, tu fabriques un XSS réfléchi. Si elle l’enregistre dans un commentaire et la ressert à tout le monde, tu fabriques un XSS stocké. Si ton script lit « location.hash » puis le colle dans « innerHTML », tu crées un XSS DOM. Dans les trois cas, le bon réflexe défensif reste le même : donnée non fiable, contexte de sortie identifié, remède adapté."},{"type":"callout","content":"Erreurs fréquentes : penser qu’un XSS « vole toujours les cookies » alors qu’un cookie « HttpOnly » limite précisément cette lecture ; croire qu’un filtre de mots interdits suffit ; utiliser « innerHTML » quand seul du texte doit être affiché ; faire confiance à un échappement par défaut puis le désactiver localement pour « aller plus vite »."},{"type":"callout","content":"Sécurité : les exemples de chaînes dangereuses servent uniquement à la défense et à la lecture des journaux. Tu ne les rejoues que sur ton code de test, jamais sur un site tiers. Un journal d’accès ou un commentaire exporté peuvent contenir des données personnelles : ne les publie pas et ne les envoie pas à un service externe sans nécessité."},{"type":"callout","content":"À retenir : un XSS exécute du JavaScript dans l’origine du site. La famille change, le principe reste : une donnée non fiable est réinterprétée comme du code ou du HTML actif. L’encodage de sortie selon le contexte est la défense de base ; CSP, « HttpOnly » et l’assainissement viennent ensuite en profondeur."},{"type":"callout","content":"Pour pratiquer : Travaille dans « TP 3 : XSS, CSP et en-têtes : évaluer une politique » : classe les points d’injection, explique quel contexte de sortie est concerné, puis justifie la correction attendue avant de finir par le quiz."},{"type":"resource","content":"OWASP : aide-mémoire sur la prévention du XSS (en anglais)","url":"https://cheatsheetseries.owasp.org/cheatsheets/Cross_Site_Scripting_Prevention_Cheat_Sheet.html"},{"type":"resource","content":"OWASP : aide-mémoire sur la prévention du XSS basé sur le DOM (en anglais)","url":"https://cheatsheetseries.owasp.org/cheatsheets/DOM_based_XSS_Prevention_Cheat_Sheet.html"},{"type":"resource","content":"OWASP : le cross-site scripting (XSS) (en anglais)","url":"https://owasp.org/www-community/attacks/xss/"},{"type":"resource","content":"MDN : l’API Trusted Types (en anglais)","url":"https://developer.mozilla.org/en-US/docs/Web/API/Trusted_Types_API"}]}'::jsonb, 26, 30, 1),
  ('e859b749-3d21-dfdc-7a24-3b14198bd752', '40abe0c4-0341-1c25-adee-8292a16408cf', '01b61988-3e06-bd60-c093-4b3ce7f7c72a', 'Content Security Policy : écrire et évaluer une politique', 'Tu apprendras à lire une politique CSP, à distinguer une politique faible d’une politique utile, puis à tester une politique avec des nonces, des hachages et un mode de déploiement prudent.', '{"blocks":[{"type":"callout","content":"Objectifs : définir ce que limite une CSP, reconnaître ses directives principales, distinguer une politique faible d’une politique forte, générer un nonce ou un hachage de script, repérer des sources dangereuses, et expliquer pourquoi la CSP complète mais ne remplace pas l’encodage."},{"type":"callout","content":"Prérequis : avoir compris ce qu’est un XSS et pourquoi une page peut charger du code depuis plusieurs origines ou depuis un script inline."},{"type":"callout","content":"Mise en situation : À l’association Teranga, Kwame doit durcir un petit tableau de bord sans tout casser. L’application a déjà des gabarits qui échappent correctement, mais l’équipe charge encore quelques scripts inline et une bibliothèque tierce. Kwame veut donc écrire une CSP qui limite vraiment les chargements, tout en gardant une phase d’observation avant d’appliquer la politique en production."},{"type":"callout","content":"Vidéo à venir : Passer d’une CSP décorative à une CSP utile"},{"type":"text","content":"La Content Security Policy, ou CSP, est un en-tête de réponse qui indique au navigateur quelles ressources une page est autorisée à charger ou à exécuter. Elle réduit l’impact d’un XSS, de certains chargements tiers non voulus et d’autres formes d’injection de contenu. Elle ne « corrige » pourtant pas une page vulnérable : si tu réinjectes une donnée non fiable, la cause reste là. La CSP agit comme une barrière supplémentaire entre cette faute et le navigateur."},{"type":"schema","content":"{\"v\":1,\"kind\":\"table\",\"title\":\"Directives utiles à connaître\",\"columns\":[\"Directive\",\"Rôle\"],\"rows\":[[\"default-src\",\"règle par défaut\"],[\"script-src\",\"scripts autorisés\"],[\"style-src\",\"feuilles de style autorisées\"],[\"img-src\",\"images autorisées\"],[\"connect-src\",\"appels réseau autorisés\"],[\"frame-ancestors\",\"qui peut intégrer la page\"],[\"base-uri\",\"contrôle la balise base\"],[\"form-action\",\"destinations de formulaire\"],[\"object-src\",\"souvent à `none` dans la majorité des cas\"]],\"mono\":[0]}"},{"type":"text","content":"Une politique faible laisse souvent « ''unsafe-inline'' », « ''unsafe-eval'' », « * » ou même « data: » dans « script-src ». À l’inverse, une politique moderne pour les scripts préfère un nonce aléatoire par réponse, éventuellement combiné à « ''strict-dynamic'' ». Pour un script inline stable, tu peux aussi calculer un hachage « sha256-… ». La directive « frame-ancestors » protège contre l’intégration dans un cadre, « base-uri » évite qu’une balise « base » change le sens des liens, et « object-src ''none'' » coupe une vieille surface d’attaque rarement nécessaire aujourd’hui."},{"type":"text","content":"Le déploiement prudent se fait en deux temps. D’abord « Content-Security-Policy-Report-Only », pour observer ce que la page casserait si la politique était appliquée. Ensuite la politique active, une fois les violations triées. Un rapport de violation arrive en JSON et peut partir vers un endpoint nommé avec « report-to », puis mappé par l’en-tête « Reporting-Endpoints ». Pour des navigateurs plus anciens, « report-uri » peut encore servir de repli. Cela ne dispense pas d’une relecture humaine : un site complexe peut produire beaucoup de bruit. De plus, un outil d’évaluation n’est qu’un indicateur. Une bonne note ne vaut pas revue d’architecture."},{"type":"text","content":"Démonstration guidée : ce script Node.js fait deux choses. Il génère un nonce, calcule le hachage d’un script inline, puis vérifie rapidement si une politique contient des sources trop permissives ou oublie des directives attendues. Avant de le rejouer, vérifie ta version avec « node --version ». Si Node.js est trop ancien pour cette syntaxe JavaScript, mets-le à jour vers une version LTS récente. Le but n’est pas de remplacer un parseur complet, mais d’apprendre les signaux défensifs à repérer immédiatement."},{"type":"code","content":"const crypto = require(\"crypto\");\n\nconst policy = \"default-src ''self''; script-src ''self'' ''unsafe-inline'' data:; style-src ''self''; img-src ''self'' https://cdn.example.org\";\nconst inlineScript = \"console.log(''bonjour'');\";\nconst nonce = crypto.randomBytes(16).toString(\"base64\");\nconst hash = crypto.createHash(\"sha256\").update(inlineScript).digest(\"base64\");\n\nconst findings = [];\nif (/script-src[^;]*''unsafe-inline''/.test(policy)) findings.push(\"script-src contient ''unsafe-inline''\");\nif (/script-src[^;]*''unsafe-eval''/.test(policy)) findings.push(\"script-src contient ''unsafe-eval''\");\nif (/script-src[^;]*\\*/.test(policy)) findings.push(\"script-src contient *\");\nif (/script-src[^;]*data:/.test(policy)) findings.push(\"script-src contient data:\");\nif (!/object-src/.test(policy)) findings.push(\"object-src manque\");\nif (!/base-uri/.test(policy)) findings.push(\"base-uri manque\");\n\nconsole.log(JSON.stringify({ nonce, hash: `sha256-${hash}`, findings }, null, 2));\n// exemple de sortie\n// {\n//   \"nonce\": \"<change à chaque exécution>\",\n//   \"hash\": \"sha256-Jn2Y2xtz4ER+BNZCE8baFKzydzPnBVF6+i6nOCQOYeA=\",\n//   \"findings\": [\n//     \"script-src contient ''unsafe-inline''\",\n//     \"script-src contient data:\",\n//     \"object-src manque\",\n//     \"base-uri manque\"\n//   ]\n// }","language":"javascript"},{"type":"example","content":"Exemple corrigé : compare trois politiques inventées. 1. « script-src ''self'' ''unsafe-inline'' » reste faible : le navigateur peut encore exécuter du script inline, ce qui réduit fortement la valeur de la CSP contre le XSS. 2. « script-src ''self'' ''nonce-…'' ''strict-dynamic''; object-src ''none''; base-uri ''none'' » est beaucoup plus défendable. 3. « script-src * » paraît simple, mais elle autorise trop de sources et ne protège presque rien. La question à te poser n’est pas « y a-t-il une CSP ? » mais « qu’autorise réellement cette CSP ? »"},{"type":"callout","content":"Erreurs fréquentes : poser une CSP et croire que l’application est « corrigée » ; conserver « ''unsafe-inline'' » par confort sans plan pour l’enlever ; oublier « object-src ''none'' » et « base-uri ''none'' » ; déployer directement une politique active sans phase « Report-Only » sur un site vivant."},{"type":"callout","content":"Sécurité : tu testes la CSP sur tes propres pages ou un environnement autorisé. Si tu collectes des rapports de violation, traite-les comme des données applicatives : ils peuvent contenir des chemins, des origines, voire des éléments de page qu’il ne faut pas publier sans contrôle."},{"type":"callout","content":"À retenir : la CSP dit au navigateur quoi charger et quoi exécuter. Une bonne politique réduit l’impact d’un XSS, mais elle ne remplace pas l’encodage de sortie. Cherche les signaux faibles d’une politique décorative : « ''unsafe-inline'' », « * », « data: », ou l’absence de directives de base comme « object-src » et « base-uri »."},{"type":"callout","content":"Pour pratiquer : Travaille dans « TP 3 : XSS, CSP et en-têtes : évaluer une politique » : lis plusieurs politiques, repère ce qu’elles laissent passer, interprète un rapport de violation, puis termine par le quiz."},{"type":"resource","content":"MDN : l’en-tête Content-Security-Policy","url":"https://developer.mozilla.org/fr/docs/Web/HTTP/Reference/Headers/Content-Security-Policy"},{"type":"resource","content":"OWASP : aide-mémoire sur la Content Security Policy (en anglais)","url":"https://cheatsheetseries.owasp.org/cheatsheets/Content_Security_Policy_Cheat_Sheet.html"},{"type":"resource","content":"CSP Evaluator : évaluer une politique de sécurité du contenu (en anglais)","url":"https://csp-evaluator.withgoogle.com/"},{"type":"resource","content":"MDN : la directive CSP report-to (en anglais)","url":"https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/Content-Security-Policy/report-to"},{"type":"resource","content":"MDN : la directive CSP report-uri (en anglais)","url":"https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/Content-Security-Policy/report-uri"},{"type":"resource","content":"MDN : l’en-tête Reporting-Endpoints (en anglais)","url":"https://developer.mozilla.org/en-US/docs/Web/HTTP/Reference/Headers/Reporting-Endpoints"}]}'::jsonb, 24, 30, 2),
  ('142e0fc3-a34d-d0e7-57d8-f823f1126400', '40abe0c4-0341-1c25-adee-8292a16408cf', '01b61988-3e06-bd60-c093-4b3ce7f7c72a', 'En-têtes de sécurité : HSTS, nosniff, cadres, référent et autorisations', 'Cette leçon t’apprend à lire les principaux en-têtes de sécurité, à savoir ce qu’ils empêchent réellement, puis à les poser côté serveur ou application sans leur prêter des pouvoirs qu’ils n’ont pas.', '{"blocks":[{"type":"callout","content":"Objectifs : identifier les principaux en-têtes de sécurité, expliquer l’effet réel de chacun, distinguer ce qui protège le navigateur de ce qui protège le serveur, lire un jeu d’en-têtes avec esprit critique, et proposer une valeur raisonnable quand elle est attendue."},{"type":"callout","content":"Prérequis : avoir déjà vu HTTPS, l’origine web, la CSP, et compris qu’un en-tête de réponse est une instruction envoyée par le serveur au navigateur."},{"type":"callout","content":"Mise en situation : À la boutique Soleil, Ama récupère les en-têtes d’un site après une mise en ligne. La page « fonctionne », mais le tableau de bord de vérification signale des absences et quelques valeurs discutables. Ama doit donc lire les en-têtes sans tomber dans le piège du score magique : certains manques sont graves, d’autres utiles mais secondaires, et aucun en-tête n’efface une faille applicative à lui seul."},{"type":"callout","content":"Vidéo à venir : Lire un jeu d’en-têtes sans confondre présence et protection réelle"},{"type":"text","content":"Les en-têtes de sécurité sont des instructions de réponse HTTP qui changent le comportement du navigateur. Ils n’empêchent pas tout, mais ils ferment des chemins d’exploitation fréquents ou limitent des fuites inutiles. Ils vivent dans la réponse, donc leur effet dépend de ce que le navigateur comprend et reçoit réellement. La bonne question n’est pas seulement « l’en-tête est-il là ? », mais « quelle valeur porte-t-il et quel risque couvre-t-il ? »."},{"type":"schema","content":"{\"v\":1,\"kind\":\"table\",\"title\":\"En-têtes de sécurité et rôle principal\",\"columns\":[\"En-tête\",\"Rôle défensif principal\"],\"rows\":[[\"Strict-Transport-Security\",\"force l’usage de HTTPS pour le domaine\"],[\"X-Content-Type-Options\",\"empêche le « sniffing » de type avec `nosniff`\"],[\"Referrer-Policy\",\"limite ce que le navigateur révèle en `Referer`\"],[\"Permissions-Policy\",\"autorise ou refuse certaines capacités du navigateur\"],[\"Cross-Origin-*\",\"isole la page ou ses ressources selon le besoin\"],[\"X-Frame-Options\",\"limite l’intégration en cadre, ancien mécanisme\"],[\"Content-Security-Policy\",\"cadre plus large, y compris `frame-ancestors`\"],[\"Cache-Control: no-store\",\"évite le stockage de réponses sensibles\"]],\"mono\":[0]}"},{"type":"text","content":"HSTS, via « Strict-Transport-Security », informe le navigateur que l’hôte doit être contacté en HTTPS seulement. Il aide aussi à empêcher le contournement d’erreurs de connexion sécurisée lors des visites suivantes. « max-age=31536000 » correspond à un an. « includeSubDomains » étend la règle aux sous-domaines, ce qui exige une vraie préparation. « nosniff » réduit l’interprétation hasardeuse des types par le navigateur. « Referrer-Policy » limite la quantité d’information transmise dans l’en-tête « Referer ». « Permissions-Policy » coupe des capacités comme la caméra, le micro ou la géolocalisation quand elles ne sont pas nécessaires. « Cross-Origin-Opener-Policy », « Cross-Origin-Embedder-Policy » et « Cross-Origin-Resource-Policy » servent, eux, à isoler une page ou ses ressources selon les besoins. « X-Frame-Options » reste utile sur d’anciens navigateurs, mais « frame-ancestors » dans la CSP offre aujourd’hui un contrôle plus moderne."},{"type":"text","content":"Tous ces en-têtes ont des limites. HSTS ne dit rien sur l’honnêteté du site et ne protège pas la toute première visite sans préchargement HSTS. « nosniff » ne corrige pas un téléversement dangereux. « Permissions-Policy » ne répare pas une logique métier. Cacher « Server » ou « X-Powered-By » réduit un peu la fuite d’information, mais ne constitue pas une protection au même niveau qu’une bonne authentification ou qu’un correctif. Enfin, « X-XSS-Protection » est obsolète : tu ne comptes pas dessus."},{"type":"text","content":"Démonstration guidée : ce script Node.js lit un petit jeu d’en-têtes inventé et produit une appréciation simple. Avant de le rejouer, vérifie ta version avec « node --version ». Si Node.js est trop ancien pour cette syntaxe JavaScript, mets-le à jour vers une version LTS récente. Le but n’est pas d’imiter un service d’audit complet, mais de vérifier si l’essentiel est présent avec une valeur cohérente. Tu peux ensuite poser les mêmes en-têtes côté serveur web, CDN ou application. Par exemple, dans Express, un « app.use » peut définir « nosniff » ou « Referrer-Policy » ; dans nginx, tu utiliserais une directive « add_header » dans le bon bloc."},{"type":"code","content":"const headers = {\n  \"strict-transport-security\": \"max-age=31536000; includeSubDomains\",\n  \"x-content-type-options\": \"nosniff\",\n  \"referrer-policy\": \"strict-origin-when-cross-origin\",\n  \"permissions-policy\": \"camera=(), microphone=(), geolocation=()\",\n  \"x-frame-options\": \"SAMEORIGIN\",\n  \"cache-control\": \"no-store\",\n};\n\nconst findings = [];\nif (!headers[\"strict-transport-security\"]) findings.push(\"HSTS manquant\");\nif (headers[\"x-content-type-options\"] !== \"nosniff\") findings.push(\"nosniff manquant ou incorrect\");\nif (!headers[\"referrer-policy\"]) findings.push(\"Referrer-Policy manquant\");\nif (!headers[\"permissions-policy\"]) findings.push(\"Permissions-Policy manquant\");\nif (!headers[\"x-frame-options\"]) findings.push(\"X-Frame-Options manquant\");\nif (!/no-store/.test(headers[\"cache-control\"] || \"\")) findings.push(\"Cache-Control sans no-store pour réponse sensible\");\n\nconsole.log(JSON.stringify({ ok: findings.length === 0, findings }, null, 2));\n// exemple de sortie (valeurs fictives)\n// {\n//   \"ok\": true,\n//   \"findings\": []\n// }","language":"javascript"},{"type":"example","content":"Exemple corrigé : un site peut obtenir une « bonne allure » avec HSTS et « nosniff », tout en laissant une page d’administration intégrable dans un cadre si « frame-ancestors » ou « X-Frame-Options » manquent. À l’inverse, une valeur « Referrer-Policy: strict-origin-when-cross-origin » réduit déjà proprement la fuite d’URL complètes vers d’autres origines. Le jugement défensif consiste donc à hiérarchiser : d’abord TLS et les protections du navigateur réellement utiles, puis les réductions de bruit ou d’empreinte comme « Server »."},{"type":"callout","content":"Erreurs fréquentes : confondre présence et qualité d’une valeur ; croire qu’un score d’outil remplace une lecture humaine ; poser HSTS avant d’être prêt sur tous les sous-domaines ; s’appuyer sur « X-XSS-Protection » alors qu’il est obsolète."},{"type":"callout","content":"Sécurité : vérifie ces en-têtes seulement sur ton propre site ou dans le périmètre autorisé. Un outil externe d’audit doit rester dans le cadre prévu par ton organisation. Et si tu captures des réponses contenant des données personnelles, ne diffuse pas plus d’informations que nécessaire."},{"type":"callout","content":"À retenir : les en-têtes de sécurité parlent surtout au navigateur. Ils ferment des chemins connus, mais ne remplacent ni un correctif applicatif ni une revue d’architecture. Lis leur valeur exacte, comprends leur rôle, puis décide lesquels sont essentiels pour le risque que tu traites."},{"type":"callout","content":"Pour pratiquer : Travaille dans « TP 3 : XSS, CSP et en-têtes : évaluer une politique » : lis un jeu d’en-têtes, explique ce que chaque valeur protège ou non, puis termine par le quiz."},{"type":"resource","content":"RFC 6797 : HTTP Strict Transport Security (HSTS) (en anglais)","url":"https://www.rfc-editor.org/rfc/rfc6797"},{"type":"resource","content":"OWASP : aide-mémoire sur les en-têtes HTTP de sécurité (en anglais)","url":"https://cheatsheetseries.owasp.org/cheatsheets/HTTP_Headers_Cheat_Sheet.html"},{"type":"resource","content":"MDN : l’en-tête X-Content-Type-Options","url":"https://developer.mozilla.org/fr/docs/Web/HTTP/Reference/Headers/X-Content-Type-Options"},{"type":"resource","content":"MDN : l’en-tête Referrer-Policy","url":"https://developer.mozilla.org/fr/docs/Web/HTTP/Reference/Headers/Referrer-Policy"},{"type":"resource","content":"MDN : l’en-tête Permissions-Policy","url":"https://developer.mozilla.org/fr/docs/Web/HTTP/Reference/Headers/Permissions-Policy"},{"type":"resource","content":"MDN : l’en-tête Cross-Origin-Opener-Policy","url":"https://developer.mozilla.org/fr/docs/Web/HTTP/Reference/Headers/Cross-Origin-Opener-Policy"},{"type":"resource","content":"MDN : l’en-tête X-Frame-Options","url":"https://developer.mozilla.org/fr/docs/Web/HTTP/Reference/Headers/X-Frame-Options"}]}'::jsonb, 24, 30, 3),
  ('a0523f46-076e-f08d-8acf-2198afcb66dd', '40abe0c4-0341-1c25-adee-8292a16408cf', '0433df95-43a7-32ea-c662-689e1d682dbc', 'Sessions et cookies : identifiant, fixation, expiration et déconnexion', 'Tu verras comment HTTP sans état devient une session, quels attributs de cookie comptent vraiment, puis comment éviter fixation, réutilisation et déconnexion incomplète.', '{"blocks":[{"type":"callout","content":"Objectifs : expliquer pourquoi HTTP est sans état, décrire le rôle d’un identifiant de session, lire un en-tête « Set-Cookie », repérer une fixation de session, distinguer expiration d’inactivité et durée absolue, puis vérifier qu’une déconnexion invalide bien la session côté serveur."},{"type":"callout","content":"Prérequis : avoir vu les cookies HTTP, l’origine web et le fait que le navigateur renvoie automatiquement un cookie au même site selon ses attributs."},{"type":"callout","content":"Mise en situation : Pour la boutique Soleil, Fatou audite une petite application qui fonctionne « simplement ». Pourtant, un détail la gêne : le même identifiant de session apparaît avant et après la connexion, et la déconnexion ne coupe pas toujours toutes les actions en arrière-plan. Fatou doit montrer pourquoi ces détails comptent, même quand la page semble correcte pour l’utilisateur."},{"type":"callout","content":"Vidéo à venir : Suivre une session du premier cookie à la vraie déconnexion"},{"type":"text","content":"HTTP est sans état : chaque requête arrive sans mémoire native de la précédente. La session côté serveur contourne cette limite en associant un identifiant aléatoire à un état conservé sur le serveur, puis en transportant cet identifiant dans un cookie. Ce cookie n’est donc pas « la session » : il n’en est que la clé côté client. Si cette clé est prévisible, réutilisée ou mal protégée, toute la session devient fragile."},{"type":"schema","content":"{\"v\":1,\"kind\":\"anatomy\",\"title\":\"Cookie de session défensif\",\"lines\":[[{\"text\":\"Set-Cookie:\",\"label\":\"en-tête HTTP\",\"tone\":\"neutral\"},{\"text\":\"__Host-session=RND...\",\"label\":\"nom et identifiant\",\"tone\":\"green\"}],[{\"text\":\"Path=/\",\"label\":\"racine du site\",\"tone\":\"blue\"},{\"text\":\"Secure\",\"label\":\"HTTPS seulement\",\"tone\":\"green\"},{\"text\":\"HttpOnly\",\"label\":\"pas via JavaScript\",\"tone\":\"violet\"}],[{\"text\":\"SameSite=Lax\",\"label\":\"limite l’intersite\",\"tone\":\"amber\"},{\"text\":\"Max-Age=1800\",\"label\":\"durée du cookie\",\"tone\":\"cyan\"}]],\"caption\":\"`__Host-` impose `Secure`, `Path=/` et l’absence de `Domain`.\"}"},{"type":"text","content":"Les attributs du cookie réduisent des risques précis. « Secure » évite l’envoi en clair sur HTTP. « HttpOnly » empêche JavaScript de lire le cookie directement, ce qui limite le vol par XSS sans empêcher un script injecté d’utiliser la session déjà présente. « SameSite » réduit des scénarios de CSRF selon la valeur choisie, et « SameSite=None » exige aussi « Secure ». Le préfixe « __Host- » renforce le cadre en exigeant « Secure », « Path=/ » et l’absence de « Domain ». Mais ces attributs ne suffisent pas : la vraie logique de session vit côté serveur."},{"type":"text","content":"La fixation de session apparaît quand l’application accepte de continuer après la connexion avec le même identifiant qu’avant. La défense consiste à régénérer l’identifiant à la connexion et à chaque changement de privilège. La déconnexion doit invalider la session côté serveur, pas seulement supprimer le cookie dans le navigateur. Sinon, une copie du même identifiant peut rester exploitable ailleurs. Enfin, une bonne gestion de session combine au moins une expiration d’inactivité et une durée absolue, car un identifiant vivant trop longtemps augmente la surface de réutilisation."},{"type":"text","content":"Démonstration guidée : ce petit serveur Node.js d’essai écoute en local. Il pose un cookie « invité », puis le régénère lors de la connexion sans accepter un identifiant inventé par le client. Avant de le rejouer, vérifie « node --version » et « curl.exe --version ». Comme cette démo reste volontairement en HTTP local pour rester simple avec « curl.exe », le cookie d’essai retire temporairement « Secure » afin que la rotation soit observable ; en production HTTPS, tu remets « Secure ». Avec « curl -i », tu lis les en-têtes « Set-Cookie » avant et après la connexion en réutilisant le même bocal de cookies. La preuve utile est là : l’identifiant change réellement."},{"type":"code","content":"# server-session-demo.cjs\nconst http = require(\"http\");\nconst crypto = require(\"crypto\");\nconst sessions = new Map();\nconst newId = () => crypto.randomBytes(12).toString(\"hex\");\nconst getId = (cookie = \"\") => {\n  const match = /demo-session=([^;]+)/.exec(cookie);\n  return match ? match[1] : null;\n};\n// Démo locale en HTTP : Secure est retiré ici pour que curl.exe puisse rejouer la rotation.\nconst sendCookie = (res, id) => res.setHeader(\"Set-Cookie\", `demo-session=${id}; Path=/; HttpOnly; SameSite=Lax; Max-Age=1800`);\nconst server = http.createServer((req, res) => {\n  const current = getId(req.headers.cookie);\n  if (req.url === \"/\") {\n    const id = current && sessions.has(current) ? current : newId();\n    if (!sessions.has(id)) sessions.set(id, { role: \"guest\" });\n    sendCookie(res, id);\n    res.end(`role=${sessions.get(id).role}`);\n    return;\n  }\n  if (req.url === \"/login\") {\n    if (current && sessions.has(current)) sessions.delete(current);\n    const id = newId();\n    sessions.set(id, { role: \"member\" });\n    sendCookie(res, id);\n    res.end(`role=${sessions.get(id).role}`);\n    return;\n  }\n  res.statusCode = 404;\n  res.end(\"not found\");\n});\nserver.listen(8087, \"127.0.0.1\", () => console.log(\"ready\"));\n\n# commandes vérifiées avec curl\ncurl.exe -i -c cookies.txt http://127.0.0.1:8087/\ncurl.exe -i -b cookies.txt -c cookies.txt http://127.0.0.1:8087/login\n# exemple de sortie (valeurs fictives)\n# HTTP/1.1 200 OK\n# Set-Cookie: demo-session=4fd4c0a8cdd4d15777c4185f; Path=/; HttpOnly; SameSite=Lax; Max-Age=1800\n#\n# role=guest\n# HTTP/1.1 200 OK\n# Set-Cookie: demo-session=ce6d6b4fce2685ad21351767; Path=/; HttpOnly; SameSite=Lax; Max-Age=1800\n#\n# role=member","language":"javascript"},{"type":"example","content":"Exemple corrigé : si le même identifiant de session reste visible avant et après la connexion, tu notes un risque de fixation de session. Si le journal montre la même session réutilisée depuis deux zones géographiques incompatibles en quelques minutes, tu notes une réutilisation suspecte. Et si la déconnexion efface seulement le cookie sans invalider l’état côté serveur, tu notes une déconnexion incomplète. Dans tous les cas, la correction prioritaire n’est pas cosmétique : elle touche la logique de génération, rotation et invalidation côté serveur."},{"type":"callout","content":"Erreurs fréquentes : croire que le cookie contient forcément un secret ou un rôle digne de confiance ; supprimer seulement le cookie à la déconnexion ; oublier de régénérer l’identifiant à la connexion ; stocker l’identifiant de session dans l’URL, les journaux ou un espace trop exposé côté client."},{"type":"callout","content":"Sécurité : teste ces mécanismes uniquement sur ton application ou sur un environnement autorisé. Les cookies et journaux de session peuvent contenir des données personnelles ou sensibles. Ne publie pas de vraies valeurs de session, même tronquées, et évite tout service tiers non nécessaire pour les analyser."},{"type":"callout","content":"À retenir : la session côté serveur repose sur un identifiant de cookie bien généré, bien tourné et bien invalidé. « Secure », « HttpOnly », « SameSite » et « __Host- » aident, mais la vraie sécurité vient aussi de la régénération à la connexion, de la déconnexion côté serveur et d’expirations raisonnables."},{"type":"callout","content":"Pour pratiquer : Travaille dans « TP 4 : sessions, jetons JWT et mots de passe » : lis des « Set-Cookie », repère une fixation ou une expiration douteuse, puis termine par le quiz."},{"type":"resource","content":"MDN : les cookies HTTP","url":"https://developer.mozilla.org/fr/docs/Web/HTTP/Guides/Cookies"},{"type":"resource","content":"MDN : l’en-tête Set-Cookie","url":"https://developer.mozilla.org/fr/docs/Web/HTTP/Reference/Headers/Set-Cookie"},{"type":"resource","content":"RFC 6265 : HTTP State Management Mechanism (cookies) (en anglais)","url":"https://www.rfc-editor.org/rfc/rfc6265"},{"type":"resource","content":"Brouillon IETF rfc6265bis : cookies, SameSite et préfixes (en anglais)","url":"https://datatracker.ietf.org/doc/draft-ietf-httpbis-rfc6265bis/"},{"type":"resource","content":"OWASP : aide-mémoire sur la gestion des sessions (en anglais)","url":"https://cheatsheetseries.owasp.org/cheatsheets/Session_Management_Cheat_Sheet.html"},{"type":"resource","content":"Node.js : le module crypto (en anglais)","url":"https://nodejs.org/api/crypto.html"}]}'::jsonb, 24, 30, 1),
  ('fe2a3450-e735-5b6f-eeae-b6623d9a8159', '40abe0c4-0341-1c25-adee-8292a16408cf', '0433df95-43a7-32ea-c662-689e1d682dbc', 'Jetons JWT : structure, vérification et erreurs classiques', 'Tu apprendras à décoder un JWT, à vérifier sa signature et ses déclarations, puis à reconnaître les erreurs de mise en œuvre les plus coûteuses : « alg » non maîtrisé, secret faible ou stockage trop exposé.', '{"blocks":[{"type":"callout","content":"Objectifs : décrire les trois parties d’un JWT, décoder un jeton en base64url, vérifier sa signature, contrôler « iss », « aud », « exp » et « nbf », distinguer HS256 de RS256, puis reconnaître plusieurs erreurs de mise en œuvre classiques."},{"type":"callout","content":"Prérequis : savoir ce qu’est un jeton d’authentification et accepter qu’un encodage lisible n’est pas un chiffrement."},{"type":"callout","content":"Mise en situation : Chez Baobab Tech, Moussa trouve un jeton dans un en-tête « Authorization ». Un collègue lui dit : « on ne peut rien en tirer, c’est chiffré ». Moussa doit justement expliquer l’inverse : un JWT signé n’est pas secret par nature, et le vrai travail consiste à vérifier ce qui est déclaré et comment la signature est contrôlée."},{"type":"callout","content":"Vidéo à venir : Décoder et vérifier un JWT sans le prendre pour une boîte noire"},{"type":"text","content":"Un JSON Web Token, ou JWT, est une représentation compacte de déclarations transportées entre deux parties. Sa forme la plus courante tient en trois parties séparées par des points : l’en-tête, la charge utile et la signature. L’en-tête et la charge sont encodés en base64url, donc lisibles par tous après décodage. Ce n’est pas du chiffrement. Tu n’y places donc jamais de secret. La sécurité vient de la signature ou, dans d’autres cas, d’un chiffrement séparé."},{"type":"schema","content":"{\"v\":1,\"kind\":\"packet\",\"title\":\"Structure compacte d’un JWT\",\"rows\":[{\"label\":\"Format\",\"fields\":[{\"name\":\"en-tête\",\"note\":\"typ, alg\",\"weight\":2,\"tone\":\"blue\"},{\"name\":\"charge\",\"note\":\"iss, sub, aud, exp, nbf, iat, jti\",\"weight\":4,\"tone\":\"violet\"},{\"name\":\"signature\",\"note\":\"vérifie les deux premières parties\",\"weight\":3,\"tone\":\"green\"}]}],\"caption\":\"Forme compacte : `en-tête.charge.signature`.\"}"},{"type":"text","content":"Avec HS256, la signature repose sur un secret partagé. Avec RS256 ou ES256, la vérification utilise une clé publique distincte de la clé privée de signature. Les erreurs les plus coûteuses sont connues : accepter « alg: none », laisser le jeton choisir lui-même l’algorithme, utiliser un secret HS256 faible, oublier de vérifier « exp » ou « aud », ou stocker le jeton dans un espace trop exposé à un XSS. Le serveur doit imposer sa liste d’algorithmes attendus et valider les déclarations utiles à son contexte."},{"type":"text","content":"Le point important est double : un jeton signé peut être lisible et pourtant intègre, et un jeton bien signé peut tout de même être refusé si son « aud » ne correspond pas, s’il a expiré, ou s’il n’est pas encore valable. La signature seule n’est donc pas la totalité de la vérification. Pour relire l’en-tête ou la charge, tu peux passer par Node.js, PowerShell ou Git Bash tant que tu ne confonds pas ce décodage avec une vérification cryptographique. Et la révocation reste difficile pour un JWT autonome : on compense souvent par des durées courtes, un jeton de rafraîchissement distinct et, selon le produit, une liste d’exclusion."},{"type":"text","content":"Démonstration guidée : ce script fabrique un JWT HS256 d’essai avec le secret « secret-d-exemple », le décode, le vérifie, puis montre qu’une charge modifiée casse immédiatement la signature. Avant de le rejouer, vérifie ta version avec « node --version ». Si Node.js est trop ancien pour cette syntaxe JavaScript, mets-le à jour vers une version LTS récente. C’est une lecture défensive, pas un conseil pour fabriquer des jetons maison en production."},{"type":"code","content":"const crypto = require(\"crypto\");\nconst secret = \"secret-d-exemple\";\nconst b64url = (value) => Buffer.from(value).toString(\"base64\").replace(/=/g, \"\").replace(/\\+/g, \"-\").replace(/\\//g, \"_\");\nconst jsonB64 = (obj) => b64url(JSON.stringify(obj));\nconst sign = (head, body) => crypto.createHmac(\"sha256\", secret).update(`${head}.${body}`).digest(\"base64\").replace(/=/g, \"\").replace(/\\+/g, \"-\").replace(/\\//g, \"_\");\n\nconst header = jsonB64({ alg: \"HS256\", typ: \"JWT\" });\nconst payload = jsonB64({ iss: \"https://id.example.org\", aud: \"boutique-soleil\", sub: \"awa\", exp: 1910000000, nbf: 1909996400 });\nconst signature = sign(header, payload);\nconst token = `${header}.${payload}.${signature}`;\nconst decoded = JSON.parse(Buffer.from(payload.replace(/-/g, \"+\").replace(/_/g, \"/\"), \"base64\").toString(\"utf8\"));\nconst valid = sign(header, payload) === signature;\nconst tamperedPayload = jsonB64({ ...decoded, aud: \"autre-service\" });\nconst tamperedStillValid = sign(header, tamperedPayload) === signature;\n\nconsole.log(JSON.stringify({ token, decoded, valid, tamperedStillValid }, null, 2));\n// exemple de sortie abrégée pour la lisibilité\n// {\n//   \"token\": \"<jwt-d-exemple>\",\n//   \"decoded\": {\n//     \"iss\": \"https://id.example.org\",\n//     \"aud\": \"boutique-soleil\",\n//     \"sub\": \"awa\",\n//     \"exp\": 1910000000,\n//     \"nbf\": 1909996400\n//   },\n//   \"valid\": true,\n//   \"tamperedStillValid\": false\n// }","language":"javascript"},{"type":"example","content":"Exemple corrigé : si un client t’envoie un JWT parfaitement décodé avec « aud: autre-service », une signature encore valide ne suffit pas. Tu le refuses parce que ce jeton n’est pas destiné à ton service. De même, si « exp » est passé, tu le refuses même si la signature reste intacte. La règle saine est donc : signature correcte, algorithme attendu, déclarations contrôlées, contexte respecté."},{"type":"callout","content":"Erreurs fréquentes : croire qu’un JWT « cache » son contenu ; accepter l’algorithme annoncé sans le comparer à la configuration attendue ; garder un secret HS256 trop simple ; ignorer « aud », « iss » ou « exp » sous prétexte que la signature passe."},{"type":"callout","content":"Sécurité : tu ne décodes et ne vérifies que des jetons de test ou des jetons dont l’analyse est autorisée. Un JWT peut contenir des données personnelles, même s’il ne devrait pas contenir de secret. Ne le colle pas dans un service externe sans nécessité, et n’enregistre pas de vrais jetons dans un rapport partagé."},{"type":"callout","content":"À retenir : un JWT signé n’est pas un coffre-fort : en-tête et charge restent lisibles. Ce qui protège le jeton, c’est la signature correcte plus la vérification des déclarations et de l’algorithme attendu. Refuse tout jeton qui ne correspond pas exactement à ton contexte."},{"type":"callout","content":"Pour pratiquer : Travaille dans « TP 4 : sessions, jetons JWT et mots de passe » : décode plusieurs jetons, contrôle leurs déclarations et explique pourquoi certains doivent être refusés, puis termine par le quiz."},{"type":"resource","content":"RFC 7519 : JSON Web Token (JWT) (en anglais)","url":"https://www.rfc-editor.org/rfc/rfc7519"},{"type":"resource","content":"RFC 8725 : bonnes pratiques d’utilisation des JWT (en anglais)","url":"https://www.rfc-editor.org/rfc/rfc8725"},{"type":"resource","content":"RFC 7515 : JSON Web Signature (JWS) (en anglais)","url":"https://www.rfc-editor.org/rfc/rfc7515"},{"type":"resource","content":"Node.js : le module crypto (en anglais)","url":"https://nodejs.org/api/crypto.html"}]}'::jsonb, 24, 30, 2),
  ('d027f928-53c8-5026-a782-465b5000afda', '40abe0c4-0341-1c25-adee-8292a16408cf', '0433df95-43a7-32ea-c662-689e1d682dbc', 'OAuth 2.0 et OpenID Connect : déléguer sans partager son mot de passe', 'Tu vas distinguer délégation et authentification, suivre le flux code d’autorisation avec PKCE, puis repérer les pièges de redirection, de « state » ou de portées trop larges.', '{"blocks":[{"type":"callout","content":"Objectifs : expliquer le but d’OAuth 2.0, distinguer OAuth d’OpenID Connect, nommer les rôles du protocole, suivre le flux code d’autorisation avec PKCE, calculer un « code_challenge », puis reconnaître plusieurs erreurs de mise en œuvre à éviter."},{"type":"callout","content":"Prérequis : avoir déjà vu les sessions et les JWT, et comprendre qu’une application peut avoir besoin d’un accès délégué sans recevoir le mot de passe d’un autre service."},{"type":"callout","content":"Mise en situation : Kwame ajoute une connexion via un fournisseur d’identité à une application de dons de l’association Teranga. L’équipe veut « faire comme les grands sites » sans jamais demander le mot de passe du fournisseur à l’utilisateur. Kwame doit donc expliquer le vrai rôle d’OAuth 2.0, ce qu’OpenID Connect ajoute, et pourquoi un détail comme « state », PKCE ou l’URI de redirection exacte change réellement la sécurité du flux."},{"type":"callout","content":"Vidéo à venir : Comprendre le flux OAuth avec PKCE sans le confondre avec une simple session locale"},{"type":"text","content":"OAuth 2.0 sert à déléguer une autorisation. L’utilisateur n’a pas à donner son mot de passe du fournisseur au client. À la place, le client obtient des jetons après un dialogue avec le serveur d’autorisation, dans un cadre de portées limitées. Les rôles classiques sont le propriétaire de ressource, le client, le serveur d’autorisation et le serveur de ressources. OpenID Connect, ou OIDC, ajoute une couche d’authentification et d’identité au-dessus de ce socle. Il apporte notamment un jeton d’identité et le paramètre « nonce » pour aider à rejeter la relecture d’une réponse d’authentification qui ne correspond pas à la demande en cours."},{"type":"schema","content":"{\"v\":1,\"kind\":\"steps\",\"title\":\"Flux code d’autorisation avec PKCE\",\"numbered\":true,\"items\":[{\"title\":\"1. Préparation\",\"text\":\"Le client prépare un `code_verifier` aléatoire.\",\"icon\":\"key\",\"tone\":\"cyan\"},{\"title\":\"2. Dérivation\",\"text\":\"Il en dérive un `code_challenge`.\",\"icon\":\"hash\",\"tone\":\"blue\"},{\"title\":\"3. Redirection\",\"text\":\"Il envoie l’utilisateur vers le serveur d’autorisation.\",\"icon\":\"share\",\"tone\":\"violet\"},{\"title\":\"4. Retour\",\"text\":\"Le serveur renvoie un code d’autorisation.\",\"icon\":\"log-in\",\"tone\":\"green\"},{\"title\":\"5. Échange\",\"text\":\"Le client échange ce code avec le `code_verifier`.\",\"icon\":\"refresh\",\"tone\":\"amber\"},{\"title\":\"6. Vérification\",\"text\":\"Le serveur compare puis remet les jetons.\",\"icon\":\"shield-check\",\"tone\":\"green\"}],\"caption\":\"Vérifications : `state`, `redirect_uri` exacte, portées minimales et PKCE.\"}"},{"type":"text","content":"Le flux recommandé ici est le code d’autorisation avec PKCE. Aujourd’hui, tu l’appliques à tous les clients, pas seulement aux clients publics : le client crée un « code_verifier » aléatoire, puis en dérive un « code_challenge », souvent avec la méthode « S256 ». Plus tard, il doit prouver qu’il connaît encore le « code_verifier ». Le paramètre « state » protège contre des confusions de réponse et des scénarios de type CSRF du flux. L’URI de redirection doit correspondre exactement à ce qui est enregistré. Une redirection trop large ou partiellement contrôlée ruine le cadre."},{"type":"text","content":"Les pièges classiques sont connus : redirection ouverte, « state » absent, portées trop larges, jeton mis dans l’URL quand il ne le faut pas, ou confusion entre OAuth et « login rapide ». Le flux implicite et le mot de passe du propriétaire de ressource ne sont plus les choix à enseigner ici. En OIDC, tu vérifies aussi le jeton d’identité, le « nonce » et les informations de profil réellement nécessaires. Enfin, déléguer ne veut pas dire tout recevoir : les portées demandées doivent rester minimales, et un service ne devrait pas demander des droits qu’il n’utilise pas réellement."},{"type":"text","content":"Démonstration guidée : ce script Node.js génère un « code_verifier » et son « code_challenge » en « S256 », selon le principe de PKCE. Avant de le rejouer, vérifie ta version avec « node --version ». Si Node.js est trop ancien pour cette syntaxe JavaScript, mets-le à jour vers une version LTS récente. Le résultat est en base64url sans rembourrage. C’est ce couple qui lie la phase d’autorisation à l’échange du code."},{"type":"code","content":"const crypto = require(\"crypto\");\nconst base64url = (buffer) => buffer.toString(\"base64\").replace(/=/g, \"\").replace(/\\+/g, \"-\").replace(/\\//g, \"_\");\nconst codeVerifier = base64url(crypto.randomBytes(32));\nconst codeChallenge = base64url(crypto.createHash(\"sha256\").update(codeVerifier).digest());\n\nconsole.log(JSON.stringify({ codeVerifier, codeChallenge, method: \"S256\" }, null, 2));\n// exemple de sortie (valeurs fictives)\n// {\n//   \"codeVerifier\": \"9EnA0r2Yv7Vh2LQb1mBq7s4M0uXwyuXIE6ALl94m7VQ\",\n//   \"codeChallenge\": \"XwPip7gG8Q7xLO_5V12m6H4mM-7qJfU5aK3C7Xv6I_A\",\n//   \"method\": \"S256\"\n// }","language":"javascript"},{"type":"example","content":"Exemple corrigé : si un client redirige vers un domaine trop large ou oublie « state », un tiers peut tenter d’injecter une réponse non attendue ou d’abuser d’une redirection ouverte. Si, en plus, les portées demandées dépassent le besoin réel, le problème n’est plus seulement l’authentification : c’est une délégation trop généreuse. La bonne lecture reste donc : rôle de chaque acteur, portées minimales, PKCE, « state », et URI de redirection exacte."},{"type":"callout","content":"Erreurs fréquentes : dire « OAuth fait le login » sans préciser qu’il s’agit d’abord d’autorisation déléguée ; oublier « state » ou PKCE ; enregistrer des URI de redirection trop souples ; demander toutes les portées disponibles « au cas où » ; confondre jeton d’identité OIDC et jeton d’accès."},{"type":"callout","content":"Sécurité : tu n’expérimentes ce flux que sur un bac à sable ou une application à toi. Les jetons, codes et URI de redirection réels sont sensibles. Ne les colle pas dans un service tiers, ne les publie pas dans un rapport partagé, et respecte les conditions du fournisseur d’identité utilisé."},{"type":"callout","content":"À retenir : OAuth 2.0 sert à déléguer sans partager le mot de passe du fournisseur. OIDC ajoute une couche d’identité. Le flux à retenir ici est le code d’autorisation avec PKCE, « state », URI de redirection exacte et portées minimales. La bonne sécurité vient du protocole bien appliqué, pas seulement d’un bouton « Se connecter avec… »."},{"type":"callout","content":"Pour pratiquer : Travaille dans « TP 4 : sessions, jetons JWT et mots de passe » : distingue les rôles, lis un flux simplifié, contrôle PKCE et les paramètres de sécurité, puis termine par le quiz."},{"type":"resource","content":"RFC 6749 : le cadre d’autorisation OAuth 2.0 (en anglais)","url":"https://www.rfc-editor.org/rfc/rfc6749"},{"type":"resource","content":"RFC 7636 : Proof Key for Code Exchange (PKCE) (en anglais)","url":"https://www.rfc-editor.org/rfc/rfc7636"},{"type":"resource","content":"RFC 9700 : bonnes pratiques de sécurité d’OAuth 2.0 (en anglais)","url":"https://www.rfc-editor.org/rfc/rfc9700"},{"type":"resource","content":"OpenID Connect Core 1.0 : la spécification (en anglais)","url":"https://openid.net/specs/openid-connect-core-1_0.html"},{"type":"resource","content":"Node.js : le module crypto (en anglais)","url":"https://nodejs.org/api/crypto.html"}]}'::jsonb, 24, 30, 3),
  ('78c5d35a-bc04-2800-9d2f-c07835ea0190', '40abe0c4-0341-1c25-adee-8292a16408cf', '59b4ce6c-101c-343c-1b5b-bd32a444aec7', 'Contrôle d’accès : IDOR, élévation de privilèges et moindre privilège', 'Tu apprends à distinguer authentification et autorisation, à reconnaître un IDOR, puis à corriger un contrôle d’accès côté serveur sans te laisser tromper par une URL cachée ou un identifiant compliqué.', '{"blocks":[{"type":"callout","content":"Objectifs : distinguer authentification et autorisation, repérer un IDOR dans une route d’API, corriger un contrôle d’accès au niveau de l’objet et de la fonction, tester avec deux comptes, et reconnaître une énumération d’identifiants dans un journal."},{"type":"callout","content":"Prérequis : avoir suivi les leçons sur les sessions et les jetons, et savoir lire une requête HTTP simple."},{"type":"callout","content":"Mise en situation : Fatou maintient l’application de commandes de la boutique Soleil. Un collègue lui dit que la page d’administration est « protégée » parce qu’elle n’apparaît dans aucun menu. En relisant l’API, Fatou voit aussi une route « /api/commandes/:id » qui renvoie une commande si l’on connaît son numéro. Elle doit prouver ce qui manque, le corriger côté serveur, puis vérifier avec deux comptes de test que l’utilisateur A ne lit pas les objets de l’utilisateur B."},{"type":"callout","content":"Vidéo à venir : Vérifier un contrôle d’accès sans confondre identité et droits"},{"type":"text","content":"S’authentifier, c’est prouver qui tu es. S’autoriser, c’est décider ce que tu as le droit de faire. Une application peut très bien reconnaître un utilisateur, puis lui donner trop de pouvoir sur une autre ressource. C’est pour cela que le contrôle d’accès reste la première famille du Top 10 OWASP 2025 : le serveur doit refuser par défaut, puis vérifier à chaque requête la fonction demandée et l’objet visé. Un lien caché, un bouton absent ou un champ désactivé dans le navigateur ne sont jamais des contrôles de sécurité."},{"type":"schema","content":"{\"v\":1,\"kind\":\"steps\",\"title\":\"Relire une requête vers `/api/commandes/1042`\",\"numbered\":true,\"items\":[{\"title\":\"Identifier l’utilisateur\",\"text\":\"Qui appelle la route et avec quelle identité prouvée ?\",\"icon\":\"user\",\"tone\":\"cyan\"},{\"title\":\"Vérifier le rôle\",\"text\":\"La fonction demandée est-elle permise pour ce rôle ?\",\"icon\":\"shield-check\",\"tone\":\"blue\"},{\"title\":\"Vérifier l’objet\",\"text\":\"L’utilisateur a-t-il le droit sur l’objet `1042` ?\",\"icon\":\"search\",\"tone\":\"violet\"},{\"title\":\"Décider\",\"text\":\"Autoriser ou refuser côté serveur.\",\"icon\":\"gavel\",\"tone\":\"green\"}],\"caption\":\"Si l’étape 3 manque : IDOR ou BOLA. Si l’étape 2 manque : élévation de fonction.\"}"},{"type":"text","content":"Le cas classique s’appelle IDOR, ou BOLA dans le vocabulaire des API : l’application prend un identifiant contrôlé par l’utilisateur, comme « 1042 », puis retourne l’objet sans vérifier qu’il lui appartient. Une élévation horizontale laisse un utilisateur agir sur le compte d’un pair. Une élévation verticale laisse appeler une fonction réservée à l’administration. Les identifiants imprévisibles, comme les UUID, réduisent l’énumération mais ne remplacent jamais la règle principale : filtrer côté serveur par propriétaire, par rôle, ou par les deux."},{"type":"text","content":"Un autre piège fréquent est l’assignation en masse. Si ton API accepte tout le corps JSON tel quel, un champ « role » ou « isAdmin » peut être injecté par un client que tu ne maîtrises pas. Le remède est le même esprit : liste autorisée de champs, validation du type attendu, puis décision côté serveur. Tu testes toujours avec deux comptes réels de démonstration, pas seulement avec le compte administrateur qui peut masquer le défaut."},{"type":"text","content":"Démonstration guidée : vérifie d’abord « node --version ». Ce script Node.js lance deux mini serveurs locaux sur « 127.0.0.1 ». Le premier est volontairement vulnérable : il renvoie une commande si l’identifiant existe. Le second ajoute le contrôle d’accès côté serveur. Tu peux le rejouer sur Windows avec Node.js puis « curl.exe ». Si ta version de Node.js est trop ancienne pour lancer le script, mets Node.js à jour puis rejoue la démonstration. Arrête-le ensuite avec « Ctrl+C »."},{"type":"code","content":"# fichier demo-acces.cjs\nconst http = require(\"node:http\");\nconst commandes = [\n  { id: \"100\", owner: \"awa\", total: 7500 },\n  { id: \"101\", owner: \"awa\", total: 18000 },\n  { id: \"102\", owner: \"koffi\", total: 9500 },\n];\n\nfunction serveur(mode) {\n  return http.createServer((req, res) => {\n    const m = req.url.match(/^\\/api\\/commandes\\/(\\d+)$/);\n    if (!m) { res.writeHead(404).end(\"not found\"); return; }\n    const user = req.headers[\"x-user\"] || \"anonyme\";\n    const role = req.headers[\"x-role\"] || \"user\";\n    const commande = commandes.find((item) => item.id === m[1]);\n    if (!commande) { res.writeHead(404).end(\"absent\"); return; }\n    if (mode === \"corrige\" && role !== \"admin\" && commande.owner !== user) {\n      res.writeHead(403, { \"content-type\": \"application/json\" });\n      res.end(JSON.stringify({ error: \"forbidden\" }));\n      return;\n    }\n    res.writeHead(200, { \"content-type\": \"application/json\" });\n    res.end(JSON.stringify(commande));\n  });\n}\n\nserveur(\"vulnerable\").listen(8081, \"127.0.0.1\");\nserveur(\"corrige\").listen(8082, \"127.0.0.1\");\nconsole.log(\"8081 vulnerable, 8082 corrige\");","language":"javascript"},{"type":"code","content":"# lancer le serveur de démonstration\nnode demo-acces.cjs\n# exemple de sortie (valeurs fictives)\n# 8081 vulnerable, 8082 corrige\n\n# Awa lit la commande de Koffi sur le serveur vulnérable\ncurl.exe -s -H \"X-User: awa\" http://127.0.0.1:8081/api/commandes/102\n# exemple de sortie (valeurs fictives)\n# {\"id\":\"102\",\"owner\":\"koffi\",\"total\":9500}\n\n# La même requête est refusée sur le serveur corrigé\ncurl.exe -i -s -H \"X-User: awa\" http://127.0.0.1:8082/api/commandes/102\n# exemple de sortie (valeurs fictives)\n# HTTP/1.1 403 Forbidden\n# Content-Type: application/json\n# Date: Tue, 10 Mar 2026 09:15:00 GMT\n# Connection: keep-alive\n# Keep-Alive: timeout=5\n# Transfer-Encoding: chunked\n#\n# {\"error\":\"forbidden\"}\n\n# L’administratrice conserve l’accès\ncurl.exe -s -H \"X-User: fatou\" -H \"X-Role: admin\" http://127.0.0.1:8082/api/commandes/102\n# exemple de sortie (valeurs fictives)\n# {\"id\":\"102\",\"owner\":\"koffi\",\"total\":9500}","language":"bash"},{"type":"schema","content":"{\"v\":1,\"kind\":\"timeline\",\"title\":\"Journal inventé à relire\",\"events\":[{\"at\":\"09:15:01\",\"title\":\"Awa lit `GET /api/commandes/100`\",\"text\":\"réponse `200`\",\"icon\":\"check\",\"tone\":\"green\"},{\"at\":\"09:15:02\",\"title\":\"Awa lit `GET /api/commandes/101`\",\"text\":\"réponse `200`\",\"icon\":\"check\",\"tone\":\"green\"},{\"at\":\"09:15:03\",\"title\":\"Awa tente `GET /api/commandes/102`\",\"text\":\"réponse `403`\",\"icon\":\"alert\",\"tone\":\"amber\"},{\"at\":\"09:15:04\",\"title\":\"Awa tente `GET /api/commandes/103`\",\"text\":\"réponse `403`\",\"icon\":\"alert\",\"tone\":\"amber\"},{\"at\":\"09:15:05\",\"title\":\"Awa tente `GET /api/commandes/104`\",\"text\":\"réponse `403`\",\"icon\":\"alert\",\"tone\":\"red\"}],\"caption\":\"Même compte, IDs successifs : énumération probable.\"}"},{"type":"example","content":"Exemple corrigé : dans l’extrait ci-dessus, Awa demande cinq identifiants successifs. Deux réponses « 200 » concernent ses propres commandes, puis trois « 403 » arrivent d’affilée. Ce motif ne prouve pas une attaque à lui seul, mais il ressemble à une énumération d’objets. La bonne réaction est de vérifier si le client parcourait vraiment son propre historique, puis de confirmer que la route filtre bien sur « owner = utilisateur connecté » et que les refus sont journalisés sans renvoyer de détail sensible."},{"type":"callout","content":"Erreurs fréquentes : croire qu’une URL non liée dans l’interface suffit à protéger une fonction ; vérifier le rôle sans vérifier l’objet demandé ; accepter un champ « role » ou « isAdmin » venu du client ; tester uniquement avec un compte administrateur, ce qui masque souvent l’IDOR."},{"type":"callout","content":"Sécurité : ne teste que ton application, ton environnement de démonstration local ou un périmètre autorisé par écrit. Les journaux d’accès et les exports de commandes peuvent contenir des données personnelles ou commerciales : ne les publie pas et ne les envoie pas à un service tiers sans nécessité."},{"type":"callout","content":"À retenir : le contrôle d’accès vit côté serveur, à chaque requête. L’authentification ne suffit pas : il faut vérifier la fonction et l’objet. Un identifiant compliqué aide, mais il ne remplace jamais un filtrage par propriétaire, rôle et liste autorisée de champs."},{"type":"callout","content":"Pour pratiquer : Travaille dans « TP 5 : contrôle d’accès, API et SSRF dans les journaux » : lis la matrice de droits, repère les accès à l’objet d’un autre utilisateur, puis relie-les au journal d’API avant de terminer par le quiz."},{"type":"resource","content":"OWASP Top 10:2025 : A01, contrôle d’accès défaillant (en anglais)","url":"https://top10.owasp.org/2025/A01_2025-Broken_Access_Control/"},{"type":"resource","content":"OWASP : aide-mémoire sur l’autorisation (en anglais)","url":"https://cheatsheetseries.owasp.org/cheatsheets/Authorization_Cheat_Sheet.html"},{"type":"resource","content":"OWASP : aide-mémoire sur la prévention des références directes d’objet non sécurisées (IDOR) (en anglais)","url":"https://cheatsheetseries.owasp.org/cheatsheets/Insecure_Direct_Object_Reference_Prevention_Cheat_Sheet.html"},{"type":"resource","content":"CWE-639 : contournement d’autorisation par clé contrôlée par l’utilisateur (en anglais)","url":"https://cwe.mitre.org/data/definitions/639.html"},{"type":"resource","content":"OWASP : le Top 10 de la sécurité des API (2023) (en anglais)","url":"https://owasp.org/API-Security/editions/2023/en/0x11-t10/"},{"type":"resource","content":"Node.js : le module http (en anglais)","url":"https://nodejs.org/api/http.html"}]}'::jsonb, 24, 30, 1),
  ('73fb525a-51de-945e-c72c-d0381229adc2', '40abe0c4-0341-1c25-adee-8292a16408cf', '59b4ce6c-101c-343c-1b5b-bd32a444aec7', 'CSRF : une requête que l’utilisateur n’a pas voulue, et ses défenses', 'Tu comprends comment un navigateur joint automatiquement les cookies, pourquoi cela ouvre la porte au CSRF, puis comment combiner SameSite, jeton anti-CSRF et contrôles d’origine sans te raconter d’histoire.', '{"blocks":[{"type":"callout","content":"Objectifs : expliquer le mécanisme du CSRF, reconnaître les conditions qui rendent une requête falsifiable, générer et vérifier un jeton anti-CSRF lié à une session, distinguer cookie et jeton Bearer, et interpréter un journal montrant une origine inattendue."},{"type":"callout","content":"Prérequis : connaître les cookies de session et savoir qu’un navigateur peut envoyer automatiquement des en-têtes à un site déjà ouvert."},{"type":"callout","content":"Mise en situation : Ama gère un espace adhérents pour l’association Teranga. Un formulaire permet de changer l’adresse de livraison et l’application utilise un cookie de session classique. Un jour, l’équipe découvre des modifications inattendues alors qu’aucun mot de passe n’a été volé. Ama doit comprendre comment un autre site peut déclencher une requête au nom d’un utilisateur déjà connecté, puis ajouter plusieurs barrières au bon endroit."},{"type":"callout","content":"Vidéo à venir : Bloquer un CSRF sans casser les formulaires légitimes"},{"type":"text","content":"Le CSRF, ou falsification de requête intersite, exploite un fait simple : le navigateur joint automatiquement les cookies associés au site cible. Si la victime est déjà connectée, une page tierce peut lui faire envoyer une requête qu’elle n’avait pas l’intention d’envoyer. La politique de même origine ne bloque pas cet envoi : elle bloque surtout la lecture de la réponse par le script tiers. C’est pourquoi un formulaire de changement d’adresse ou de mot de passe reste sensible tant qu’il modifie l’état avec un simple cookie de session et sans secret supplémentaire."},{"type":"schema","content":"{\"v\":1,\"kind\":\"steps\",\"title\":\"Chaîne d’un CSRF classique\",\"numbered\":true,\"items\":[{\"title\":\"1. Session ouverte\",\"text\":\"La victime est connectée à `boutique.example`.\",\"icon\":\"user-check\",\"tone\":\"cyan\"},{\"title\":\"2. Cookie gardé\",\"text\":\"Le navigateur conserve un cookie de session.\",\"icon\":\"file-lock\",\"tone\":\"blue\"},{\"title\":\"3. Site piégé\",\"text\":\"La victime ouvre aussi une page contrôlée par l’attaquant.\",\"icon\":\"skull\",\"tone\":\"red\"},{\"title\":\"4. Requête déclenchée\",\"text\":\"Ce site provoque une requête vers `boutique.example`.\",\"icon\":\"send\",\"tone\":\"violet\"},{\"title\":\"5. Cookie joint\",\"text\":\"Le navigateur renvoie le cookie automatiquement.\",\"icon\":\"refresh\",\"tone\":\"amber\"},{\"title\":\"6. Action acceptée\",\"text\":\"Sans défense, le serveur croit à une action voulue.\",\"icon\":\"alert\",\"tone\":\"red\"}]}"},{"type":"text","content":"Pour qu’un CSRF réussisse, il faut en général une session ouverte, une requête prévisible et une action qui change l’état sans vérifier un secret supplémentaire. Un « GET » qui supprime, valide ou paye quelque chose est donc une très mauvaise idée. Les défenses utiles se complètent : « SameSite=Lax » ou « Strict » réduit les envois automatiques de cookies, mais ne remplace pas un jeton anti-CSRF. Le serveur peut aussi vérifier « Origin » et les en-têtes « Sec-Fetch-Site », puis exiger un en-tête personnalisé pour les appels AJAX légitimes."},{"type":"text","content":"Une API protégée par « Authorization: Bearer <jeton> » n’est pas touchée de la même manière, car le navigateur n’ajoute pas tout seul ce jeton dans l’en-tête. En revanche, une API consommée depuis le navigateur avec un cookie de session reste concernée. Et rappelle-toi la limite importante : une faille XSS peut contourner les protections CSRF en agissant depuis l’origine légitime. Le CSRF se traite donc avec les sessions, mais aussi avec l’hygiène XSS."},{"type":"text","content":"Démonstration guidée : vérifie d’abord « node --version ». Ce script Node.js fabrique une session et un jeton aléatoire, puis vérifie le jeton reçu avec « timingSafeEqual ». Le secret n’est jamais déduit du navigateur : il est généré côté serveur et stocké avec la session. Si ta version de Node.js est trop ancienne pour lancer le script, mets Node.js à jour puis rejoue la démonstration. La comparaison en temps constant évite une comparaison naïve qui pourrait fuir des informations."},{"type":"code","content":"# fichier demo-csrf.cjs\nconst crypto = require(\"node:crypto\");\n\nconst sessionId = crypto.randomBytes(8).toString(\"hex\");\nconst csrfToken = crypto.randomBytes(16).toString(\"hex\");\nconst sessionStore = new Map([[sessionId, { csrfToken }]]);\n\nfunction verifier(sessionIdRecu, tokenRecu) {\n  const session = sessionStore.get(sessionIdRecu);\n  if (!session || typeof tokenRecu !== \"string\") return false;\n  const attendu = Buffer.from(session.csrfToken, \"utf8\");\n  const recu = Buffer.from(tokenRecu, \"utf8\");\n  if (attendu.length !== recu.length) return false;\n  return crypto.timingSafeEqual(attendu, recu);\n}\n\nconsole.log({ sessionId, csrfToken });\nconsole.log(\"valide\", verifier(sessionId, csrfToken));\nconst tokenModifie = csrfToken.endsWith(\"0\") ? csrfToken.slice(0, -1) + \"1\" : csrfToken.slice(0, -1) + \"0\";\nconsole.log(\"modifie\", verifier(sessionId, tokenModifie));\nconsole.log(\"autre session\", verifier(\"session-inconnue\", csrfToken));","language":"javascript"},{"type":"code","content":"# lancer la démonstration\nnode demo-csrf.cjs\n# exemple de sortie (valeurs fictives)\n# { sessionId: ''b54f4f9d2c13a88c'', csrfToken: ''2f8f5b8f5f4c4c3f5a5d13d9a8ff4a20'' }\n# valide true\n# modifie false\n# autre session false","language":"bash"},{"type":"schema","content":"{\"v\":1,\"kind\":\"timeline\",\"title\":\"Extrait inventé de journal\",\"events\":[{\"at\":\"09:15:00\",\"title\":\"`POST /profil/adresse`\",\"text\":\"`200`, `Origin: https://boutique.example`\",\"icon\":\"check\",\"tone\":\"green\"},{\"at\":\"09:17:42\",\"title\":\"`POST /profil/adresse`\",\"text\":\"`200`, `Referer: https://cadeaux.example/promo`\",\"icon\":\"alert\",\"tone\":\"red\"}],\"caption\":\"Même action sensible, mais deuxième origine inattendue.\"}"},{"type":"example","content":"Exemple corrigé : si une requête « POST /profil/adresse » arrive avec un cookie valide mais sans jeton anti-CSRF, puis porte un « Referer » ou un « Origin » étranger au domaine attendu, tu ne conclus pas seulement à un clic maladroit. Tu vérifies d’abord si le formulaire exige un jeton synchronisé, si « SameSite » est bien réglé, puis si l’action pouvait encore être déclenchée par un « GET ». Le bon correctif combine au minimum une méthode non sûre adaptée, un jeton lié à la session et un contrôle d’origine."},{"type":"callout","content":"Erreurs fréquentes : croire que « SameSite » suffit toujours à lui seul ; modifier l’état avec « GET » parce que c’est plus simple à relire ; oublier que les formulaires classiques et les appels AJAX n’ont pas les mêmes signaux ; penser qu’un jeton Bearer placé dans « Authorization » est joint automatiquement comme un cookie."},{"type":"callout","content":"Sécurité : n’essaie pas de rejouer un CSRF sur un service qui n’est pas le tien. Travaille sur un formulaire de démonstration local, sur ton propre site ou dans un cadre autorisé par écrit. Les journaux de profils, d’achats ou de formulaires contiennent souvent des données personnelles : garde-les en interne."},{"type":"callout","content":"À retenir : le CSRF existe parce que le navigateur joint les cookies automatiquement. Une défense sérieuse combine « SameSite », un jeton anti-CSRF, des méthodes HTTP cohérentes et un contrôle d’origine. Et si une XSS existe, elle peut contourner ces barrières."},{"type":"callout","content":"Pour pratiquer : Travaille dans « TP 5 : contrôle d’accès, API et SSRF dans les journaux » : ce TP ne rejoue pas de CSRF, mais il te fait lire des journaux et une matrice de droits pour reconnaître une action sensible qui manque de garde-fous, puis terminer par le quiz."},{"type":"resource","content":"MDN : la politique de même origine","url":"https://developer.mozilla.org/fr/docs/Web/Security/Defenses/Same-origin_policy"},{"type":"resource","content":"MDN : l’en-tête Set-Cookie","url":"https://developer.mozilla.org/fr/docs/Web/HTTP/Reference/Headers/Set-Cookie"},{"type":"resource","content":"OWASP : l’attaque CSRF (en anglais)","url":"https://owasp.org/www-community/attacks/csrf"},{"type":"resource","content":"CWE-352 : falsification de requête intersites (CSRF) (en anglais)","url":"https://cwe.mitre.org/data/definitions/352.html"},{"type":"resource","content":"MDN : l’en-tête Sec-Fetch-Site","url":"https://developer.mozilla.org/fr/docs/Web/HTTP/Reference/Headers/Sec-Fetch-Site"},{"type":"resource","content":"Node.js : le module crypto (en anglais)","url":"https://nodejs.org/api/crypto.html"}]}'::jsonb, 22, 30, 2),
  ('b3f18a0f-c8cc-22a0-912a-4a100b736394', '40abe0c4-0341-1c25-adee-8292a16408cf', '59b4ce6c-101c-343c-1b5b-bd32a444aec7', 'CORS : partager entre origines sans ouvrir la porte', 'Tu comprends quand le navigateur déclenche une pré-requête CORS, pourquoi « * » et les cookies ne vont pas ensemble, puis comment écrire une liste d’origines exacte au lieu de refléter tout ce qui arrive.', '{"blocks":[{"type":"callout","content":"Objectifs : rappeler ce qu’est une origine web, distinguer requête simple et pré-requête CORS, interpréter les en-têtes « Access-Control-* », tester une liste d’origines exacte, et expliquer pourquoi CORS ne protège pas le serveur contre un client hors navigateur."},{"type":"callout","content":"Prérequis : avoir compris la politique de même origine et savoir lire une requête HTTP avec ses en-têtes."},{"type":"callout","content":"Mise en situation : Koffi ouvre une API pour une application frontale et voit vite arriver la demande classique : « mets juste Access-Control-Allow-Origin: * pour que tout marche ». L’API utilise pourtant aussi des cookies de session pour le back-office. Koffi doit partager ce qu’il faut avec l’application officielle, sans transformer le navigateur en passe-partout pour des origines qu’il ne contrôle pas."},{"type":"callout","content":"Vidéo à venir : Configurer CORS proprement sans refléter toutes les origines"},{"type":"text","content":"Une origine web est définie par le schéma, l’hôte et le port. « https://app.example.org » et « https://app.example.org:8443 » sont donc deux origines différentes. La politique de même origine empêche un script chargé depuis une origine de lire librement les réponses d’une autre. CORS est un assouplissement contrôlé de cette règle : le serveur dit au navigateur quelles origines peuvent lire la réponse, avec quels en-têtes et quelles méthodes."},{"type":"schema","content":"{\"v\":1,\"kind\":\"compare\",\"title\":\"Deux chemins CORS selon le type de requête\",\"sides\":[{\"title\":\"Requête simple\",\"tone\":\"green\",\"icon\":\"globe\",\"items\":[\"Navigateur sur `https://app.example.org`\",\"`GET` simple vers `https://api.example.org`\",\"La réponse annonce `Access-Control-Allow-Origin`\"]},{\"title\":\"Requête non simple\",\"tone\":\"amber\",\"icon\":\"refresh\",\"items\":[\"Le navigateur envoie d’abord `OPTIONS`\",\"`Access-Control-Request-Method` précise la méthode visée\",\"`Access-Control-Request-Headers` annonce les en-têtes non simples\"]}]}"},{"type":"text","content":"Une requête simple, comme un « GET » sans en-tête exotique, part directement. Une requête avec « Content-Type: application/json » ou un en-tête personnalisé déclenche souvent une pré-requête « OPTIONS ». Le navigateur demande alors si la méthode et les en-têtes sont autorisés. Le serveur répond avec « Access-Control-Allow-Origin », « Access-Control-Allow-Methods » et, si besoin, « Access-Control-Allow-Headers ». Quand la réponse varie selon l’origine, ajoute aussi « Vary: Origin » pour éviter un cache trompeur."},{"type":"text","content":"Le piège le plus grave est de refléter l’origine reçue sans la vérifier. Un autre piège est d’accepter « null », origine que l’on retrouve avec certains contextes locaux, des documents isolés ou des schémas comme « file: », ou d’écrire une expression trop large comme « example.com » qui laisse passer « example.com.attaquant.example ». Enfin, retiens la règle pratique essentielle : « Access-Control-Allow-Credentials: true » ne peut pas être combiné avec « * ». Si des cookies ou d’autres informations d’authentification voyagent, la réponse doit viser une origine exacte."},{"type":"text","content":"Démonstration guidée : vérifie d’abord « node --version ». Cette fonction Node.js applique une liste d’origines exactes. Elle refuse les pièges fréquents, comme le mauvais schéma, le bon domaine en suffixe, ou la chaîne littérale « null ». Tu peux la rejouer telle quelle avec Node.js avant de la traduire dans ton application. Si ta version de Node.js est trop ancienne pour lancer le script, mets Node.js à jour puis rejoue la démonstration."},{"type":"code","content":"# fichier demo-cors.cjs\nconst autorisees = new Set([\n  \"https://app.example.org\",\n  \"https://admin.example.org\",\n]);\n\nfunction originAutorisee(origin) {\n  if (typeof origin !== \"string\") return false;\n  if (origin === \"null\") return false;\n  return autorisees.has(origin);\n}\n\nconst tests = [\n  \"https://app.example.org\",\n  \"https://admin.example.org\",\n  \"http://app.example.org\",\n  \"https://app.example.org:8443\",\n  \"https://example.org\",\n  \"https://app.example.org.attaquant.example\",\n  \"null\",\n  undefined,\n];\n\nfor (const valeur of tests) {\n  console.log(String(valeur), originAutorisee(valeur));\n}","language":"javascript"},{"type":"code","content":"# lancer la démonstration\nnode demo-cors.cjs\n# exemple de sortie (valeurs fictives)\n# https://app.example.org true\n# https://admin.example.org true\n# http://app.example.org false\n# https://app.example.org:8443 false\n# https://example.org false\n# https://app.example.org.attaquant.example false\n# null false\n# undefined false","language":"bash"},{"type":"schema","content":"{\"v\":1,\"kind\":\"table\",\"title\":\"Configuration saine pour un front officiel\",\"columns\":[\"En-tête\",\"Valeur\"],\"rows\":[[\"Access-Control-Allow-Origin\",\"https://app.example.org\"],[\"Access-Control-Allow-Credentials\",\"true\"],[\"Access-Control-Allow-Methods\",\"GET, POST\"],[\"Access-Control-Allow-Headers\",\"Content-Type, X-CSRF-Token\"],[\"Vary\",\"Origin\"]],\"mono\":[0,1]}"},{"type":"example","content":"Exemple corrigé : si ton back-office envoie des cookies et que tu réponds « Access-Control-Allow-Origin: * », le navigateur refusera de toute façon les réponses avec « credentials ». La bonne correction n’est pas de supprimer les cookies au hasard, mais de lister précisément « https://admin.example.org » et « https://app.example.org », puis de refuser tout le reste. CORS aide le navigateur à lire une réponse : il ne remplace ni l’authentification ni le contrôle d’accès de l’API."},{"type":"callout","content":"Erreurs fréquentes : confondre CORS avec une protection du serveur contre tous les clients ; refléter l’origine reçue sans liste autorisée ; oublier « Vary: Origin » quand la réponse dépend de l’origine ; croire que « * » fonctionne encore avec les cookies et « Allow-Credentials: true »."},{"type":"callout","content":"Sécurité : ne teste les en-têtes CORS que sur ton site, ton API locale ou un périmètre autorisé. Un client hors navigateur ignore CORS : ne révèle donc jamais plus de données que ce que ton contrôle d’accès serveur permet réellement."},{"type":"callout","content":"À retenir : CORS indique au navigateur qui peut lire une réponse. Il ne décide pas qui peut appeler ton API. Si des cookies sont en jeu, vise une origine exacte, ajoute « Vary: Origin » et refuse la tentation du reflet automatique."},{"type":"callout","content":"Pour pratiquer : Travaille dans « TP 5 : contrôle d’accès, API et SSRF dans les journaux » : ce TP ne rejoue pas de pré-requête CORS complète, mais il te fait relire une matrice de droits et des journaux d’API pour distinguer partage légitime entre origines et ouverture trop large, puis terminer par le quiz."},{"type":"resource","content":"MDN : le partage des ressources entre origines (CORS)","url":"https://developer.mozilla.org/fr/docs/Web/HTTP/Guides/CORS"},{"type":"resource","content":"MDN : l’en-tête Access-Control-Allow-Origin","url":"https://developer.mozilla.org/fr/docs/Web/HTTP/Reference/Headers/Access-Control-Allow-Origin"},{"type":"resource","content":"RFC 6454 : le concept d’origine web (en anglais)","url":"https://www.rfc-editor.org/rfc/rfc6454"}]}'::jsonb, 22, 30, 3),
  ('a1a1c2ef-9afc-8a84-c92b-fe83daa3f7d2', '40abe0c4-0341-1c25-adee-8292a16408cf', '9680e491-932b-894b-5261-defeb80e8019', 'Téléversement de fichiers et traversée de chemin', 'Tu apprends à traiter un téléversement comme une chaîne de contrôles, puis à bloquer une traversée de chemin en validant à la fois le contenu réel, le nom servi et le chemin canonique.', '{"blocks":[{"type":"callout","content":"Objectifs : énumérer les risques du téléversement de fichiers, vérifier un type réel par signature simple, corriger une traversée de chemin avec un chemin canonique, choisir un stockage non exécutable, et interpréter un journal montrant des « ../ » ou des encodages suspects."},{"type":"callout","content":"Prérequis : savoir lire un chemin de fichier et connaître les bases des requêtes HTTP avec un corps de formulaire."},{"type":"callout","content":"Mise en situation : Moussa ajoute un envoi de justificatifs pour une application associative. Le client lui fournit un nom de fichier et un « Content-Type », puis le produit veut aussi un téléchargement des pièces déjà déposées. Moussa doit empêcher trois classes de problèmes à la fois : téléverser un contenu actif, écraser un fichier existant, ou demander un autre chemin que celui prévu pour la ressource."},{"type":"callout","content":"Vidéo à venir : Accepter un fichier sans lui faire confiance"},{"type":"text","content":"Un téléversement n’est jamais « juste un fichier ». C’est une donnée non fiable qui peut chercher à faire exécuter du code, à consommer le disque, à tromper ton application sur son type réel ou à viser un autre chemin que celui prévu. La défense se fait en couches : taille maximale, extension en liste autorisée, signature du fichier, renommage aléatoire, stockage hors de la racine web ou dans un stockage objet sans exécution, puis service avec « Content-Disposition » et « X-Content-Type-Options: nosniff ». Le « Content-Type » envoyé par le client est utile comme indice, jamais comme preuve."},{"type":"schema","content":"{\"v\":1,\"kind\":\"steps\",\"title\":\"Chaîne de contrôle d’un téléversement\",\"items\":[{\"title\":\"Taille\",\"text\":\"Vérifier que la taille reste acceptable.\",\"icon\":\"gauge\",\"tone\":\"cyan\"},{\"title\":\"Extension\",\"text\":\"N’accepter qu’une liste autorisée.\",\"icon\":\"file\",\"tone\":\"blue\"},{\"title\":\"Signature\",\"text\":\"Contrôler que le contenu réel est cohérent.\",\"icon\":\"file-search\",\"tone\":\"violet\"},{\"title\":\"Nom interne\",\"text\":\"Remplacer le nom par un identifiant côté serveur.\",\"icon\":\"hash\",\"tone\":\"green\"},{\"title\":\"Stockage\",\"text\":\"Conserver le fichier hors exécution.\",\"icon\":\"hard-drive\",\"tone\":\"amber\"},{\"title\":\"Service\",\"text\":\"Servir avec `Content-Disposition` et `nosniff`.\",\"icon\":\"download\",\"tone\":\"green\"}]}"},{"type":"text","content":"La traversée de chemin est un défaut voisin. Si ton application construit un chemin avec une entrée utilisateur, « ../ », « ..%2f » ou un séparateur inattendu peuvent sortir du dossier prévu. Le bon réflexe est d’éviter autant que possible les chemins libres, puis de résoudre le chemin canonique et de vérifier qu’il reste sous le dossier autorisé. Cette idée vaut aussi pour l’extraction d’archives : un fichier interne nommé « ../../webroot/index.js » peut écrire hors du répertoire d’arrivée si tu ne normalises pas."},{"type":"text","content":"Démonstration guidée : vérifie d’abord « node --version ». La fonction suivante bloque un chemin qui sort du dossier prévu, puis reconnaît trois signatures simples : PNG, JPEG et PDF. La logique ne remplace pas un antivirus ni une bibliothèque spécialisée, mais elle montre les deux réflexes incontournables : ne pas faire confiance au nom demandé, et ne pas faire confiance au type déclaré. Si ta version de Node.js est trop ancienne pour lancer le script, mets Node.js à jour puis rejoue la démonstration."},{"type":"code","content":"# fichier demo-upload.cjs\nconst path = require(\"node:path\");\n\nfunction cheminSur(base, demande) {\n  const baseCanonique = path.resolve(base);\n  const cible = path.resolve(baseCanonique, demande);\n  const prefixe = baseCanonique + path.sep;\n  return cible === baseCanonique || cible.startsWith(prefixe);\n}\n\nfunction signature(buffer) {\n  if (buffer.slice(0, 8).equals(Buffer.from([0x89,0x50,0x4e,0x47,0x0d,0x0a,0x1a,0x0a]))) return \"png\";\n  if (buffer.slice(0, 3).equals(Buffer.from([0xff,0xd8,0xff]))) return \"jpeg\";\n  if (buffer.slice(0, 5).toString(\"ascii\") === \"%PDF-\") return \"pdf\";\n  return \"inconnu\";\n}\n\nconst base = path.join(\"C:\\\\\", \"uploads-demo\");\nfor (const demande of [\"photo.png\", \"docs/rapport.pdf\", \"../secret.txt\", \"..\\\\windows.ini\", \"images/../../config.json\", \".\"]) {\n  console.log(demande, cheminSur(base, demande));\n}\n\nconsole.log(signature(Buffer.from([0x89,0x50,0x4e,0x47,0x0d,0x0a,0x1a,0x0a,0x00])));\nconsole.log(signature(Buffer.from([0xff,0xd8,0xff,0xe0,0x00])));\nconsole.log(signature(Buffer.from(\"%PDF-1.7\\n\", \"ascii\")));\nconsole.log(signature(Buffer.from(\"MZ....\", \"ascii\")));","language":"javascript"},{"type":"code","content":"# lancer la démonstration\nnode demo-upload.cjs\n# exemple de sortie (valeurs fictives)\n# photo.png true\n# docs/rapport.pdf true\n# ../secret.txt false\n# ..\\windows.ini false\n# images/../../config.json false\n# . true\n# png\n# jpeg\n# pdf\n# inconnu","language":"bash"},{"type":"schema","content":"{\"v\":1,\"kind\":\"timeline\",\"title\":\"Journal inventé à relire\",\"events\":[{\"at\":\"09:15:00\",\"title\":\"`GET /fichiers/rapport.pdf`\",\"text\":\"réponse `200`\",\"icon\":\"file\",\"tone\":\"green\"},{\"at\":\"09:15:05\",\"title\":\"`GET /fichiers/../../config.json`\",\"text\":\"réponse `400`\",\"icon\":\"alert\",\"tone\":\"red\"},{\"at\":\"09:15:06\",\"title\":\"`GET /fichiers/%2e%2e%2fsecret.txt`\",\"text\":\"réponse `400`\",\"icon\":\"alert\",\"tone\":\"red\"},{\"at\":\"09:15:08\",\"title\":\"`POST /upload`\",\"text\":\"`Content-Type: image/png`, réponse `415`\",\"icon\":\"upload\",\"tone\":\"amber\"}],\"caption\":\"Le type annoncé et le chemin demandé ne suffisent pas.\"}"},{"type":"example","content":"Exemple corrigé : dans ce journal, deux lectures essaient de sortir du dossier prévu avec « ../ » et « %2e%2e%2f ». Une autre envoie « Content-Type: image/png » mais finit en « 415 », signe que le serveur n’a pas cru le type annoncé. Le bon comportement est précisément celui-là : vérifier le contenu réel, renommer le fichier côté serveur, puis servir ensuite la pièce avec un nom contrôlé et un type fixé par le serveur, pas par le client."},{"type":"callout","content":"Erreurs fréquentes : faire confiance au seul « Content-Type » envoyé par le client ; conserver le nom fourni comme nom de stockage interne ; servir un téléversement directement depuis une zone exécutable ; normaliser le chemin après avoir déjà tenté d’ouvrir le fichier."},{"type":"callout","content":"Sécurité : ne manipule que des fichiers de démonstration sur ta propre machine ou dans un environnement autorisé. Un téléversement peut contenir des données personnelles, des pièces d’identité ou des documents métier : ne les envoie pas à un service tiers pour « vérifier le type » si ce n’est pas nécessaire et encadré."},{"type":"callout","content":"À retenir : un téléversement sûr additionne des couches : taille, extension, signature, renommage, stockage non exécutable et service contrôlé. Pour les chemins, le mot d’ordre est simple : résoudre, vérifier, puis seulement accéder au fichier."},{"type":"callout","content":"Pour pratiquer : Travaille dans « TP 5 : contrôle d’accès, API et SSRF dans les journaux » : repère les tentatives de traversée de chemin et les téléchargements suspects dans les traces fournies, puis relie-les à la logique de validation avant de terminer par le quiz."},{"type":"resource","content":"OWASP : aide-mémoire sur le téléversement de fichiers (en anglais)","url":"https://cheatsheetseries.owasp.org/cheatsheets/File_Upload_Cheat_Sheet.html"},{"type":"resource","content":"CWE-434 : téléversement de fichier de type dangereux (en anglais)","url":"https://cwe.mitre.org/data/definitions/434.html"},{"type":"resource","content":"CWE-22 : traversée de chemin (en anglais)","url":"https://cwe.mitre.org/data/definitions/22.html"},{"type":"resource","content":"MDN : l’en-tête X-Content-Type-Options","url":"https://developer.mozilla.org/fr/docs/Web/HTTP/Reference/Headers/X-Content-Type-Options"}]}'::jsonb, 24, 30, 1),
  ('a4f419b8-7ceb-5ebc-2654-b1396bae5a86', '40abe0c4-0341-1c25-adee-8292a16408cf', '9680e491-932b-894b-5261-defeb80e8019', 'SSRF, XXE et désérialisation : quand le serveur fait ce qu’on lui souffle', 'Tu apprends à reconnaître une SSRF, à limiter les destinations qu’un serveur peut appeler, puis à éviter les pièges voisins que sont les entités XML externes et la désérialisation d’objets non fiables.', '{"blocks":[{"type":"callout","content":"Objectifs : décrire une SSRF avec ses cibles internes, refuser des destinations locales ou privées dans une fonction Node.js, expliquer pourquoi les redirections et la résolution DNS comptent, résumer le risque XXE, et distinguer JSON validé d’une désérialisation d’objet dangereuse."},{"type":"callout","content":"Prérequis : savoir qu’un serveur peut appeler d’autres services HTTP et connaître la différence entre une URL et une adresse IP."},{"type":"callout","content":"Mise en situation : Awa ajoute un aperçu d’image à partir d’une URL dans une petite API. Le produit veut aussi un import XML hérité d’un ancien partenaire. Pendant la revue, Awa réalise qu’un serveur qui « va chercher pour toi » peut atteindre des endroits invisibles depuis l’extérieur : un service local, une adresse de métadonnées ou un outil d’administration interne. Elle doit donc fermer les destinations dangereuses, puis empêcher qu’un XML ou un objet sérialisé ne pilote plus que prévu."},{"type":"callout","content":"Vidéo à venir : Limiter ce qu’un serveur a le droit d’aller chercher"},{"type":"text","content":"Une SSRF, ou falsification de requête côté serveur, apparaît quand l’application récupère une URL choisie par l’utilisateur. Le problème n’est pas seulement l’Internet public : le serveur peut souvent joindre « 127.0.0.1 », des plages privées, une adresse locale de lien comme « 169.254.169.254 », ou des services d’administration internes invisibles pour le navigateur. C’est pour cela qu’une fonction « importe cette image » ou « vérifie ce webhook » mérite le même sérieux qu’un accès base de données."},{"type":"schema","content":"{\"v\":1,\"kind\":\"network\",\"title\":\"SSRF : ce que le serveur peut atteindre\",\"cols\":4,\"rows\":3,\"nodes\":[{\"id\":\"user\",\"label\":\"Utilisateur\",\"sub\":\"fournit une URL\",\"icon\":\"user\",\"col\":0,\"row\":1,\"tone\":\"cyan\"},{\"id\":\"app\",\"label\":\"Serveur applicatif\",\"icon\":\"server\",\"col\":1.5,\"row\":1,\"tone\":\"blue\"},{\"id\":\"public\",\"label\":\"Internet public\",\"sub\":\"attendu\",\"icon\":\"internet\",\"col\":3,\"row\":0,\"tone\":\"green\"},{\"id\":\"local\",\"label\":\"localhost\",\"sub\":\"à refuser\",\"icon\":\"home\",\"col\":3,\"row\":1,\"tone\":\"red\"},{\"id\":\"private\",\"label\":\"Réseau privé\",\"sub\":\"à refuser\",\"icon\":\"network\",\"col\":3,\"row\":1.5,\"tone\":\"red\"},{\"id\":\"meta\",\"label\":\"Métadonnées cloud\",\"sub\":\"à refuser\",\"icon\":\"cloud\",\"col\":3,\"row\":2,\"tone\":\"red\"}],\"links\":[{\"from\":\"user\",\"to\":\"app\",\"label\":\"URL fournie\",\"arrow\":\"to\"},{\"from\":\"app\",\"to\":\"public\",\"label\":\"appel attendu\",\"arrow\":\"to\",\"tone\":\"green\"},{\"from\":\"app\",\"to\":\"local\",\"label\":\"bloquer\",\"arrow\":\"to\",\"tone\":\"red\"},{\"from\":\"app\",\"to\":\"private\",\"label\":\"bloquer\",\"arrow\":\"to\",\"tone\":\"red\"},{\"from\":\"app\",\"to\":\"meta\",\"label\":\"bloquer\",\"arrow\":\"to\",\"tone\":\"red\"}]}"},{"type":"text","content":"La défense la plus sûre est une liste autorisée de destinations exactes ou de domaines métier connus. Ensuite, il faut revalider après la résolution DNS et après chaque redirection, car un nom apparemment bénin peut finir sur une adresse privée. Le schéma compte aussi : « https » seulement dans beaucoup de cas, pas de « file: », pas de « gopher: ». Et même après ces filtres, la segmentation réseau et le moindre privilège de la machine restent importants, car un défaut de validation n’est jamais impossible."},{"type":"text","content":"Le risque XXE est voisin par sa logique : un analyseur XML mal réglé peut résoudre des entités externes et lire un fichier local ou appeler une URL. La réponse moderne est simple : désactiver les DTD et les entités externes, puis préférer JSON quand le protocole le permet. Pour la désérialisation, le principe défensif est le même : un objet natif venu du client n’est pas une simple donnée, c’est parfois du comportement emballé. Choisis donc JSON, valide-le par schéma, puis reconstruis toi-même les structures autorisées."},{"type":"text","content":"Démonstration guidée : vérifie d’abord « node --version ». Cette fonction Node.js choisit une politique volontairement stricte. Elle n’accepte que « https » et deux hôtes autorisés. Toutes les adresses IP littérales sont refusées, y compris les adresses locales ou privées. En production, une application qui doit accepter plus large revalide aussi l’adresse obtenue après la résolution DNS et chaque redirection. Si ta version de Node.js est trop ancienne pour lancer le script, mets Node.js à jour puis rejoue la démonstration."},{"type":"code","content":"# fichier demo-ssrf.cjs\nconst net = require(\"node:net\");\nconst { URL } = require(\"node:url\");\n\nconst autorises = new Set([\"api.example.org\", \"cdn.example.org\"]);\n\nfunction destinationAutorisee(valeur) {\n  let url;\n  try { url = new URL(valeur); } catch { return false; }\n  if (url.protocol !== \"https:\") return false;\n  const host = url.hostname.replace(/^\\[|\\]$/g, \"\");\n  if (net.isIP(host)) return false;\n  return autorises.has(host);\n}\n\nfor (const valeur of [\n  \"https://api.example.org/avatar.png\",\n  \"https://cdn.example.org/media.pdf\",\n  \"http://api.example.org/avatar.png\",\n  \"https://127.0.0.1/admin\",\n  \"https://169.254.169.254/latest/meta-data/\",\n  \"https://10.1.2.3/\",\n  \"https://192.168.1.9/\",\n  \"https://[::1]/\",\n  \"file:///etc/passwd\",\n  \"https://inconnu.example.org/\",\n]) console.log(valeur, destinationAutorisee(valeur));","language":"javascript"},{"type":"code","content":"# lancer la démonstration\nnode demo-ssrf.cjs\n# exemple de sortie (valeurs fictives)\n# https://api.example.org/avatar.png true\n# https://cdn.example.org/media.pdf true\n# http://api.example.org/avatar.png false\n# https://127.0.0.1/admin false\n# https://169.254.169.254/latest/meta-data/ false\n# https://10.1.2.3/ false\n# https://192.168.1.9/ false\n# https://[::1]/ false\n# file:///etc/passwd false\n# https://inconnu.example.org/ false","language":"bash"},{"type":"schema","content":"{\"v\":1,\"kind\":\"anatomy\",\"title\":\"Extrait XML à ne pas accepter tel quel\",\"lines\":[[{\"text\":\"<!DOCTYPE note [\",\"label\":\"DTD active\",\"tone\":\"amber\"}],[{\"text\":\"<!ENTITY ext SYSTEM \\\"file:///etc/passwd\\\">\",\"label\":\"entité externe\",\"tone\":\"red\"}],[{\"text\":\"]>\",\"label\":\"fin de DTD\",\"tone\":\"neutral\"},{\"text\":\"<note>&ext;</note>\",\"label\":\"résout l’entité\",\"tone\":\"red\"}]],\"caption\":\"Remède : désactiver les DTD et les entités externes.\"}"},{"type":"example","content":"Exemple corrigé : un journal sortant qui montre « GET https://169.254.169.254/latest/meta-data/ » depuis un service d’aperçu d’images n’indique pas une simple erreur de copier-coller. Il révèle que le serveur a essayé d’atteindre une destination interne ou locale de lien qui n’aurait jamais dû faire partie de la fonction métier. La correction minimale est de limiter les hôtes autorisés, de refuser les schémas non prévus, puis de revalider aussi les redirections et l’adresse réellement résolue."},{"type":"callout","content":"Erreurs fréquentes : laisser n’importe quelle URL externe passer parce que « ce n’est qu’un aperçu » ; vérifier le nom de domaine avant redirection puis oublier de recontrôler après ; conserver un import XML sans désactiver DTD et entités externes ; désérialiser directement un objet natif fourni par le client parce que « c’est plus pratique »."},{"type":"callout","content":"Sécurité : ne tente pas d’atteindre des services internes ou des métadonnées cloud hors de ton propre environnement de test. Une SSRF touche souvent des composants qui n’étaient pas prévus pour être exposés. Garde aussi les journaux sortants en interne : ils peuvent révéler l’architecture, des noms de services et des chemins sensibles."},{"type":"callout","content":"À retenir : un serveur qui récupère une URL pour l’utilisateur agrandit sa surface d’attaque. La défense prioritaire est la liste autorisée, complétée par la revalidation DNS et des redirections. Pour XML et la désérialisation, le même principe gagne : limiter ce que l’analyseur ou le décodeur a le droit de faire."},{"type":"callout","content":"Pour pratiquer : Travaille dans « TP 5 : contrôle d’accès, API et SSRF dans les journaux » : repère les requêtes sortantes vers l’intérieur, distingue ce qui est métier de ce qui ne l’est pas, puis termine par le quiz."},{"type":"resource","content":"OWASP : aide-mémoire sur la prévention du SSRF (en anglais)","url":"https://cheatsheetseries.owasp.org/cheatsheets/Server_Side_Request_Forgery_Prevention_Cheat_Sheet.html"},{"type":"resource","content":"OWASP : aide-mémoire sur la prévention des entités externes XML (XXE) (en anglais)","url":"https://cheatsheetseries.owasp.org/cheatsheets/XML_External_Entity_Prevention_Cheat_Sheet.html"},{"type":"resource","content":"OWASP : aide-mémoire sur la désérialisation (en anglais)","url":"https://cheatsheetseries.owasp.org/cheatsheets/Deserialization_Cheat_Sheet.html"},{"type":"resource","content":"OWASP : la falsification de requête côté serveur (SSRF) (en anglais)","url":"https://owasp.org/www-community/attacks/Server_Side_Request_Forgery"},{"type":"resource","content":"CWE-918 : falsification de requête côté serveur (SSRF) (en anglais)","url":"https://cwe.mitre.org/data/definitions/918.html"},{"type":"resource","content":"CWE-611 : référence à une entité externe XML (XXE) (en anglais)","url":"https://cwe.mitre.org/data/definitions/611.html"},{"type":"resource","content":"CWE-502 : désérialisation de données non fiables (en anglais)","url":"https://cwe.mitre.org/data/definitions/502.html"},{"type":"resource","content":"AWS : configurer le service de métadonnées d’instance (IMDS) (en anglais)","url":"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/configuring-instance-metadata-service.html"},{"type":"resource","content":"Node.js : le module url (en anglais)","url":"https://nodejs.org/api/url.html"}]}'::jsonb, 24, 30, 2),
  ('37711f84-b8de-65ba-adc2-9d279d71af38', '40abe0c4-0341-1c25-adee-8292a16408cf', '9680e491-932b-894b-5261-defeb80e8019', 'Sécuriser une API : autorisation par objet, limitation de débit et OWASP API Top 10', 'Tu apprends à lire l’API Top 10 2023 avec des exemples concrets, puis à combiner autorisation par objet, limitation de débit, validation de schéma et journalisation sobre pour une API réellement défensive.', '{"blocks":[{"type":"callout","content":"Objectifs : citer les familles de l’OWASP API Top 10 2023, distinguer autorisation par objet, fonction et propriété, mettre en place un limiteur de débit simple, relire une réponse d’API trop bavarde, et calculer un rythme de requêtes par jeton sur un journal JSON inventé."},{"type":"callout","content":"Prérequis : avoir suivi les leçons sur le contrôle d’accès et les jetons, et savoir lire un objet JSON simple."},{"type":"callout","content":"Mise en situation : Kwame publie une API de commandes pour trois applications mobiles. Les pages HTML ont disparu, mais les mêmes questions reviennent : qui peut lire quel objet, qui peut appeler quelle fonction, et combien de fois par minute. En plus, l’équipe découvre une vieille version « /v1 » oubliée et des réponses qui renvoient plus de champs que nécessaire. Kwame doit donc sécuriser l’API comme un produit à part entière, pas comme un simple détail derrière le front."},{"type":"callout","content":"Vidéo à venir : Passer d’une API qui marche à une API qui résiste"},{"type":"text","content":"Une API change la forme de l’application, pas les fondamentaux de sécurité. Au lieu de pages HTML, tu exposes surtout des objets, des fonctions et des propriétés. L’OWASP API Top 10 2023 aide à ne pas oublier les angles majeurs : API1 Broken Object Level Authorization, API2 Broken Authentication, API3 Broken Object Property Level Authorization, API4 Unrestricted Resource Consumption, API5 Broken Function Level Authorization, API6 Unrestricted Access to Sensitive Business Flows, API7 Server Side Request Forgery, API8 Security Misconfiguration, API9 Improper Inventory Management et API10 Unsafe Consumption of APIs."},{"type":"schema","content":"{\"v\":1,\"kind\":\"cards\",\"title\":\"Raccourci utile pour relire une API\",\"items\":[{\"term\":\"API1\",\"text\":\"objet d’un autre utilisateur\",\"tone\":\"red\",\"icon\":\"user-x\"},{\"term\":\"API3\",\"text\":\"trop de propriétés lues ou modifiées\",\"tone\":\"amber\",\"icon\":\"list\"},{\"term\":\"API5\",\"text\":\"fonction d’administration appelée sans droit\",\"tone\":\"red\",\"icon\":\"briefcase\"},{\"term\":\"API4\",\"text\":\"consommation de ressources sans garde-fou\",\"tone\":\"amber\",\"icon\":\"gauge\"},{\"term\":\"API9\",\"text\":\"version ou point d’entrée oublié\",\"tone\":\"violet\",\"icon\":\"bookmark\"},{\"term\":\"API10\",\"text\":\"réponse tierce acceptée sans assez de contrôle\",\"tone\":\"blue\",\"icon\":\"share\"}],\"columns\":3}"},{"type":"text","content":"L’autorisation par objet répond à « puis-je lire ou modifier CET enregistrement ? ». L’autorisation par fonction répond à « puis-je appeler CETTE action ? ». L’autorisation par propriété répond à « quels champs ai-je le droit de lire ou d’écrire ? ». Une API saine retourne donc le minimum utile, refuse les champs inattendus dans les requêtes, limite la taille des corps, borne la pagination et renvoie « 429 Too Many Requests » avec « Retry-After » quand un client consomme trop vite."},{"type":"text","content":"N’oublie pas l’inventaire. Une API oubliée en « /v1 », un sous-domaine resté public, un schéma OpenAPI plus maintenu ou une documentation périmée deviennent vite des angles morts. La journalisation doit aider sans divulguer de secrets : identifiant de requête, jeton ou compte pseudonymisé, objet ciblé, résultat, temps de réponse, mais jamais le mot de passe ni le jeton brut. Pour GraphQL, ajoute une limite de profondeur et de complexité : une seule requête peut sinon coûter beaucoup trop cher."},{"type":"text","content":"Démonstration guidée : vérifie d’abord « node --version ». Ce script Node.js simule un limiteur de débit à fenêtre fixe de trois requêtes par minute et calcule aussi le nombre de requêtes par jeton sur un petit journal JSON inventé. Le but n’est pas de te vendre cet algorithme comme solution parfaite, mais de te faire voir ce qu’il compte vraiment et ce qu’il renvoie quand le seuil est dépassé. Si ta version de Node.js est trop ancienne pour lancer le script, mets Node.js à jour puis rejoue la démonstration."},{"type":"code","content":"# fichier demo-api.cjs\nconst fenetreMs = 60000;\nconst limite = 3;\nconst compteurs = new Map();\n\nfunction autoriser(token, horodatageMs) {\n  const entree = compteurs.get(token);\n  if (!entree || horodatageMs - entree.debut >= fenetreMs) {\n    compteurs.set(token, { debut: horodatageMs, total: 1 });\n    return { allowed: true, remaining: limite - 1 };\n  }\n  entree.total += 1;\n  return { allowed: entree.total <= limite, remaining: Math.max(0, limite - entree.total) };\n}\n\nfor (const t of [0, 10000, 20000, 30000, 61000]) {\n  console.log(t, autoriser(\"tok-a\", t));\n}\n\nconst journal = [\n  { token: \"tok-a\", route: \"/api/commandes\", status: 200 },\n  { token: \"tok-a\", route: \"/api/commandes\", status: 200 },\n  { token: \"tok-b\", route: \"/api/admin/export\", status: 403 },\n  { token: \"tok-a\", route: \"/api/commandes\", status: 429 },\n  { token: \"tok-b\", route: \"/api/admin/export\", status: 403 },\n];\nconst parToken = {};\nfor (const ligne of journal) parToken[ligne.token] = (parToken[ligne.token] || 0) + 1;\nconsole.log(parToken);","language":"javascript"},{"type":"code","content":"# lancer la démonstration\nnode demo-api.cjs\n# exemple de sortie (valeurs fictives)\n# 0 { allowed: true, remaining: 2 }\n# 10000 { allowed: true, remaining: 1 }\n# 20000 { allowed: true, remaining: 0 }\n# 30000 { allowed: false, remaining: 0 }\n# 61000 { allowed: true, remaining: 2 }\n# { tok-a: 3, tok-b: 2 }","language":"bash"},{"type":"schema","content":"{\"v\":1,\"kind\":\"compare\",\"title\":\"Réponse trop bavarde à corriger\",\"sides\":[{\"title\":\"Champs utiles\",\"tone\":\"green\",\"icon\":\"check\",\"items\":[\"`\\\"id\\\": 102`\",\"`\\\"client\\\": \\\"Awa\\\"`\",\"`\\\"total\\\": 9500`\"]},{\"title\":\"Champs internes\",\"tone\":\"red\",\"icon\":\"close\",\"items\":[\"`\\\"margeInterne\\\": 4300`\",\"`\\\"role\\\": \\\"admin\\\"`\"]}],\"verdict\":\"Une API grand public ne renvoie pas tout.\"}"},{"type":"example","content":"Exemple corrigé : si une réponse publique renvoie « margeInterne » et « role », tu n’as pas seulement un problème de style JSON. Tu as un défaut d’autorisation par propriété : des champs internes sortent sans nécessité métier. La bonne correction consiste à définir explicitement le schéma de sortie utile pour ce rôle, puis à tester que les autres propriétés ne quittent plus l’API, même si elles existent encore dans la base ou dans l’objet métier interne."},{"type":"callout","content":"Erreurs fréquentes : traiter l’API comme un simple miroir de la base de données ; limiter le débit globalement sans distinguer jeton, compte ou adresse ; oublier les versions anciennes et les points d’entrée peu documentés ; journaliser les jetons complets ou des charges JSON sensibles pour « aider le débogage »."},{"type":"callout","content":"Sécurité : teste les limites de débit et les contrôles d’autorisation seulement sur ton API de démonstration, ton environnement de test ou un périmètre autorisé. Une campagne agressive sur une production peut devenir un déni de service. Les journaux d’API contiennent souvent des identifiants métier : garde-les en interne."},{"type":"callout","content":"À retenir : une API sûre décide qui peut lire quel objet, appeler quelle fonction et voir quels champs. Elle borne aussi ce qu’un client peut consommer, inventorie ses versions et journalise assez pour comprendre sans divulguer de secrets."},{"type":"callout","content":"Pour pratiquer : Travaille dans « TP 5 : contrôle d’accès, API et SSRF dans les journaux » : repère les appels à des fonctions interdites, relie-les aux objets visés et compte le rythme des requêtes par jeton avant de terminer par le quiz."},{"type":"resource","content":"OWASP : le Top 10 de la sécurité des API (2023) (en anglais)","url":"https://owasp.org/API-Security/editions/2023/en/0x11-t10/"},{"type":"resource","content":"OWASP : aide-mémoire sur la sécurité des API REST (en anglais)","url":"https://cheatsheetseries.owasp.org/cheatsheets/REST_Security_Cheat_Sheet.html"},{"type":"resource","content":"MDN : le code de statut 429 Too Many Requests","url":"https://developer.mozilla.org/fr/docs/Web/HTTP/Reference/Status/429"},{"type":"resource","content":"OWASP : l’Application Security Verification Standard (ASVS) (en anglais)","url":"https://owasp.org/www-project-application-security-verification-standard/"},{"type":"resource","content":"OWASP : aide-mémoire sur la sécurité de GraphQL (en anglais)","url":"https://cheatsheetseries.owasp.org/cheatsheets/GraphQL_Cheat_Sheet.html"}]}'::jsonb, 26, 30, 3),
  ('375df27a-a6f0-4ece-a112-6c3fa81228fd', '40abe0c4-0341-1c25-adee-8292a16408cf', '014933f4-4c0b-c7cd-bff2-02fa5109ba11', 'Configuration, secrets et erreurs : durcir sans rien laisser traîner', 'Apprends à reconnaître une mauvaise configuration, à protéger les secrets hors du code, et à faire échouer une application sans divulguer d’informations utiles à un attaquant.', '{"blocks":[{"type":"callout","content":"Objectifs : repérer les erreurs de configuration les plus fréquentes, séparer un secret du code, distinguer journal serveur et message client, organiser la rotation d’un secret, et vérifier qu’une application échoue fermée plutôt qu’ouverte."},{"type":"callout","content":"Prérequis : avoir compris le fonctionnement général de HTTP, des en-têtes et du contrôle d’accès."},{"type":"callout","content":"Mise en situation : Kwame reprend une petite application de réservation pour la boutique Soleil. L’équipe a laissé un fichier « .env » dans une archive, une page d’erreur montre la trace complète, et le mode débogage est resté actif en préproduction. Kwame doit durcir l’ensemble sans casser le service ni publier par erreur des secrets dans le dépôt."},{"type":"callout","content":"Vidéo à venir : Durcir une application web sans exposer ses secrets ni ses erreurs"},{"type":"text","content":"L’OWASP Top 10:2025 place la mauvaise configuration de sécurité en A02. En pratique, cela recouvre moins une seule faille qu’une famille d’oublis : mot de passe par défaut, liste de répertoires ouverte, port d’administration accessible depuis Internet, stockage public, méthodes HTTP inutiles, CORS trop large, traces d’erreur complètes, mode débogage actif, fichier « .git » ou « .env » laissé dans la racine publiée. Le point commun est simple : l’application en dit trop, accepte trop, ou expose un composant qui n’aurait pas dû l’être."},{"type":"schema","content":"{\"v\":1,\"kind\":\"table\",\"title\":\"Liste de contrôle de durcissement\",\"columns\":[\"Zone\",\"Attendu\"],\"rows\":[[\"Configuration\",\"pas de valeur par défaut, pas de mode debug en production\"],[\"Publication\",\"pas de « .env », « .bak », « .git », « phpinfo » ni archive oubliée\"],[\"Réseau\",\"ports d’administration fermés ou restreints\"],[\"Application\",\"erreurs sobres côté client, détails côté journal serveur\"],[\"Secrets\",\"hors code et hors dépôt, rotation prévue, accès minimal\"],[\"Environnements\",\"dev, test et production séparés\"]]}"},{"type":"text","content":"Un secret n’est pas seulement un mot de passe. C’est aussi une clé API, un secret de session, un jeton d’accès, un mot de passe SMTP, un identifiant de base de données ou une clé privée. Il ne vit ni dans le code, ni dans le dépôt Git, ni dans une image copiée partout. Il vit dans une variable d’environnement, un coffre-fort, ou un mécanisme équivalent contrôlé. Si un secret fuit, la bonne réaction n’est pas « on le cachera mieux la prochaine fois ». Il faut considérer ce secret comme compromis, le remplacer, révoquer l’ancien, relire les journaux, et vérifier quelles fonctions dépendaient de lui."},{"type":"text","content":"Démonstration guidée : le script ci-dessous crée un petit dossier d’essai, y dépose quelques fichiers dangereux, puis cherche deux familles de problèmes. La première : des noms qui n’ont rien à faire dans un dossier publié, comme « .env » ou « sauvegarde.bak ». La seconde : des motifs de secrets fictifs commençant par « CLE_EXEMPLE_ ». L’objectif n’est pas de remplacer un outil spécialisé, mais d’apprendre à regarder avant de livrer."},{"type":"text","content":"Prérequis de démonstration : ouvre un terminal et vérifie d’abord ta version avec « node --version ». Cet extrait n’utilise que des modules cœur stables de Node.js et « console.table ». Si la commande échoue ou si l’extrait ne se lance pas, mets Node.js à jour avant de continuer."},{"type":"code","content":"const fs = require(\"node:fs\");\nconst os = require(\"node:os\");\nconst path = require(\"node:path\");\n\nconst racine = fs.mkdtempSync(path.join(os.tmpdir(), \"swb-config-\"));\nfs.mkdirSync(path.join(racine, \"public\"));\nfs.mkdirSync(path.join(racine, \"archives\"));\nfs.writeFileSync(path.join(racine, \"public\", \".env\"), \"SESSION_SECRET=CLE_EXEMPLE_ABC123\\n\", \"utf8\");\nfs.writeFileSync(path.join(racine, \"public\", \"app.js\"), \"console.log(''ok'');\\n\", \"utf8\");\nfs.writeFileSync(path.join(racine, \"archives\", \"sauvegarde.bak\"), \"ancienne configuration\\n\", \"utf8\");\nfs.writeFileSync(path.join(racine, \"README.txt\"), \"aucun secret ici\\n\", \"utf8\");\n\nconst motifsFichiers = [/^\\.env$/i, /\\.bak$/i, /^\\.git$/i];\nconst motifSecret = /CLE_EXEMPLE_[A-Z0-9_]+/g;\nconst trouvailles = [];\n\nfunction parcourir(dossier) {\n  for (const nom of fs.readdirSync(dossier)) {\n    const complet = path.join(dossier, nom);\n    const stat = fs.statSync(complet);\n    if (stat.isDirectory()) {\n      parcourir(complet);\n      continue;\n    }\n    if (motifsFichiers.some((re) => re.test(nom))) {\n      trouvailles.push({ type: \"fichier\", chemin: path.relative(racine, complet) });\n    }\n    const contenu = fs.readFileSync(complet, \"utf8\");\n    if (motifSecret.test(contenu)) {\n      trouvailles.push({ type: \"secret\", chemin: path.relative(racine, complet) });\n      motifSecret.lastIndex = 0;\n    }\n  }\n}\n\nparcourir(racine);\nconsole.table(trouvailles);\n# exemple de sortie (valeurs fictives)\n# ┌─────────┬───────────┬──────────────────────────┐\n# │ (index) │ type      │ chemin                   │\n# ├─────────┼───────────┼──────────────────────────┤\n# │ 0       │ ''fichier'' │ ''archives\\\\sauvegarde.bak'' │\n# │ 1       │ ''fichier'' │ ''public\\\\.env''            │\n# │ 2       │ ''secret''  │ ''public\\\\.env''            │\n# └─────────┴───────────┴──────────────────────────┘","language":"javascript"},{"type":"schema","content":"{\"v\":1,\"kind\":\"steps\",\"title\":\"Après une fuite de secret\",\"numbered\":true,\"items\":[{\"title\":\"Confirmer\",\"text\":\"le secret concerné et le système touché\",\"icon\":\"search\",\"tone\":\"blue\"},{\"title\":\"Révoquer ou remplacer\",\"text\":\"puis redémarrer proprement si nécessaire\",\"icon\":\"refresh\",\"tone\":\"red\"},{\"title\":\"Relire les journaux\",\"text\":\"pour voir si le secret a été utilisé\",\"icon\":\"file-search\",\"tone\":\"amber\"},{\"title\":\"Corriger la cause\",\"text\":\"dépôt, archive, image, variable partagée, capture ou ticket\",\"icon\":\"wrench\",\"tone\":\"green\"}]}"},{"type":"text","content":"La gestion des erreurs mérite la même discipline. Côté client, tu renvoies un message compréhensible mais sobre : « opération impossible pour le moment » ou « accès refusé ». Côté serveur, tu conserves la trace détaillée avec l’identifiant de corrélation, le chemin, le code HTTP, le compte concerné et la pile technique si elle est utile. L’OWASP Top 10:2025 ajoute d’ailleurs la mauvaise gestion des conditions exceptionnelles en A10 : un test d’erreur mal géré peut transformer une panne en exposition d’information, ou une vérification ratée en accès accordé par défaut. Une défense sérieuse échoue donc fermée, pas ouverte."},{"type":"example","content":"Exemple corrigé : mauvaise réponse côté client, « stack trace: TypeError in paiement.js ligne 143, mot de passe DB=motdepasse ». Bonne réponse, « paiement indisponible, réessaie plus tard » avec un code de suivi. Côté serveur, le journal garde l’heure, le compte, la route, l’identifiant de corrélation et la trace technique complète. Si la clé de session a fuité dans un ancien export, on la remplace immédiatement, on invalide les sessions qui en dépendent et on vérifie les accès réalisés depuis la fuite."},{"type":"callout","content":"Erreurs fréquentes : laisser un mode débogage actif en production ; croire qu’un fichier « .env » hors du code est automatiquement protégé ; réutiliser le même secret dans plusieurs environnements ; renvoyer la pile d’erreur complète au navigateur ; corriger le symptôme sans révoquer le secret compromis."},{"type":"callout","content":"Sécurité : analyse et corrige uniquement ta propre application ou un environnement pour lequel tu as une autorisation écrite. Les journaux et exports peuvent contenir des données personnelles et des secrets : ne les publie pas, ne les colle pas dans un service tiers, et utilise des valeurs fictives pour tes démonstrations."},{"type":"callout","content":"À retenir : une mauvaise configuration expose souvent plus d’informations qu’une faille de code isolée. Les secrets vivent hors du dépôt, se remplacent quand ils fuient, et les erreurs détaillées restent côté serveur. En production, une défense robuste échoue fermée et sépare clairement dev, test et production."},{"type":"callout","content":"Pour pratiquer : Travaille dans « TP 6 : configuration, dépendances et notation CVSS » : repère les fichiers oubliés, les erreurs trop bavardes et les secrets mal placés, puis propose une correction vérifiable avant de finir par le quiz."},{"type":"resource","content":"OWASP Top 10:2025 : A02, mauvaise configuration de sécurité (en anglais)","url":"https://top10.owasp.org/2025/A02_2025-Security_Misconfiguration/"},{"type":"resource","content":"OWASP Top 10:2025 : A10, mauvaise gestion des conditions exceptionnelles (en anglais)","url":"https://top10.owasp.org/2025/A10_2025-Mishandling_of_Exceptional_Conditions/"},{"type":"resource","content":"OWASP : aide-mémoire sur la gestion des secrets (en anglais)","url":"https://cheatsheetseries.owasp.org/cheatsheets/Secrets_Management_Cheat_Sheet.html"},{"type":"resource","content":"OWASP : aide-mémoire sur la gestion des erreurs (en anglais)","url":"https://cheatsheetseries.owasp.org/cheatsheets/Error_Handling_Cheat_Sheet.html"},{"type":"resource","content":"CNIL : guide de la sécurité des données personnelles","url":"https://www.cnil.fr/fr/guide-de-la-securite-des-donnees-personnelles-nouvelle-edition-2024"},{"type":"resource","content":"Node.js : le module fs (en anglais)","url":"https://nodejs.org/api/fs.html"}]}'::jsonb, 24, 30, 1),
  ('17bec502-56de-aa79-db09-0e1b03b9d2e5', '40abe0c4-0341-1c25-adee-8292a16408cf', '014933f4-4c0b-c7cd-bff2-02fa5109ba11', 'Dépendances et chaîne d’approvisionnement : analyse, verrouillage et mises à jour', 'Comprends pourquoi ton application embarque surtout du code tiers, comment verrouiller les versions, lire un avis de sécurité et prioriser une mise à jour sans casser la production.', '{"blocks":[{"type":"callout","content":"Objectifs : lire un avis de sécurité de dépendance, expliquer l’intérêt d’un fichier de verrouillage, distinguer « npm install » et « npm ci », repérer un risque de typosquatting, et classer des mises à jour selon leur exposition réelle."},{"type":"callout","content":"Prérequis : avoir déjà vu ce qu’est une application web côté serveur et compris la notion de correctif."},{"type":"callout","content":"Mise en situation : Awa hérite d’un petit service Node.js de Baobab Tech. Le dépôt contient cinquante dépendances directes et beaucoup plus de dépendances transitives. Une alerte parle d’une bibliothèque vulnérable, une autre d’un paquet au nom presque identique à un paquet connu. Awa doit décider quoi corriger d’abord et comment rendre les installations plus prévisibles."},{"type":"callout","content":"Vidéo à venir : Lire une alerte de dépendance et verrouiller sa chaîne d’approvisionnement"},{"type":"text","content":"Une application moderne exécute rarement seulement ton code. Elle exécute aussi le code des dépendances directes et transitives, leurs scripts d’installation, parfois leurs outils de construction, et les dépendances de ces dépendances. L’OWASP Top 10:2025 place ce sujet en A03, défaillances de la chaîne d’approvisionnement logicielle. Le risque ne vient pas seulement d’un CVE connu. Il vient aussi d’un paquet mal nommé, d’un mainteneur compromis, d’un script post-installation trop permissif, ou d’une installation impossible à rejouer exactement."},{"type":"schema","content":"{\"v\":1,\"kind\":\"cards\",\"title\":\"Ce qu’il faut suivre\",\"columns\":2,\"items\":[{\"term\":\"package.json\",\"text\":\"ce que tu demandes\",\"icon\":\"document\",\"tone\":\"cyan\"},{\"term\":\"package-lock.json\",\"text\":\"ce qui sera réellement installé\",\"icon\":\"lock\",\"tone\":\"blue\"},{\"term\":\"npm ci\",\"text\":\"installation propre depuis le verrouillage\",\"icon\":\"refresh\",\"tone\":\"green\"},{\"term\":\"SBOM\",\"text\":\"inventaire des composants livrés\",\"icon\":\"boxes\",\"tone\":\"violet\"},{\"term\":\"Avis de sécurité\",\"text\":\"versions touchées, corrigées, gravité, contexte\",\"icon\":\"alert\",\"tone\":\"amber\"}]}"},{"type":"text","content":"Le verrouillage des versions est une défense simple et souvent sous-estimée. Sans fichier de verrouillage, deux installations du même projet peuvent récupérer des versions différentes à quelques jours d’écart. Avec « npm ci », tu demandes une installation reproductible à partir de « package-lock.json », utile en intégration continue et en production. Cela ne supprime pas les vulnérabilités, mais cela supprime une partie du hasard. L’inventaire logiciel, souvent sous la forme d’une SBOM CycloneDX ou SPDX, sert ensuite à savoir ce que tu livres réellement et à retrouver vite où se cache un composant touché."},{"type":"text","content":"Les incidents réels rappellent que le risque n’est pas théorique. Log4Shell, CVE-2021-44228, révélé en décembre 2021, a montré l’impact massif d’une bibliothèque de journalisation très répandue. La porte dérobée dans xz/liblzma, CVE-2024-3094, révélée en mars 2024, a rappelé qu’un composant profond de la chaîne peut contaminer d’autres logiciels qui l’embarquent. L’affaire « event-stream » en 2018 a illustré un autre mécanisme : reprise de maintenance, ajout d’une dépendance malveillante « flatmap-stream », puis ciblage d’un portefeuille précis. Tu n’as pas besoin de retenir chaque date pour agir, mais tu dois retenir la leçon commune : connaître, verrouiller, vérifier et mettre à jour."},{"type":"text","content":"Démonstration guidée : le script ci-dessous compare une petite liste de dépendances inventées à des avis inventés. Chaque avis indique une version corrigée minimale. Le script repère les paquets vulnérables, puis montre aussi ce qu’acceptent deux intervalles SemVer usuels. Ici, « ^1.2.3 » accepte les mises à jour mineures et correctives compatibles de la branche majeure 1, alors que « ~1.2.3 » reste dans la branche « 1.2.x »."},{"type":"text","content":"Prérequis de démonstration : vérifie d’abord « node --version ». Cet extrait n’utilise que JavaScript de base et « console.table ». Si Node.js manque ou si la commande échoue, mets Node.js à jour avant de continuer."},{"type":"code","content":"function parse(version) {\n  return version.split(\".\").map((v) => Number(v));\n}\n\nfunction compare(a, b) {\n  const va = parse(a);\n  const vb = parse(b);\n  for (let i = 0; i < 3; i += 1) {\n    if (va[i] !== vb[i]) return va[i] - vb[i];\n  }\n  return 0;\n}\n\nfunction semverRange(range, candidate) {\n  const base = range.slice(1);\n  const [maj, min, patch] = parse(base);\n  const [cMaj, cMin, cPatch] = parse(candidate);\n  if (range.startsWith(\"^\")) {\n    return cMaj === maj && compare(candidate, base) >= 0;\n  }\n  if (range.startsWith(\"~\")) {\n    return cMaj === maj && cMin === min && compare(candidate, base) >= 0;\n  }\n  return candidate === range;\n}\n\nconst dependances = [\n  { nom: \"lib-http\", version: \"1.4.2\" },\n  { nom: \"flatmap-stream\", version: \"0.1.0\" },\n  { nom: \"templater\", version: \"2.0.3\" },\n];\nconst avis = [\n  { nom: \"lib-http\", corrigeA: \"1.4.4\" },\n  { nom: \"templater\", corrigeA: \"2.1.0\" },\n];\n\nconst vulnerables = dependances.filter((dep) => {\n  const alerte = avis.find((item) => item.nom === dep.nom);\n  return alerte && compare(dep.version, alerte.corrigeA) < 0;\n});\n\nconsole.table(vulnerables);\nconsole.log(\"^1.2.3 accepte 1.5.0 :\", semverRange(\"^1.2.3\", \"1.5.0\"));\nconsole.log(\"^1.2.3 accepte 2.0.0 :\", semverRange(\"^1.2.3\", \"2.0.0\"));\nconsole.log(\"~1.2.3 accepte 1.2.9 :\", semverRange(\"~1.2.3\", \"1.2.9\"));\nconsole.log(\"~1.2.3 accepte 1.3.0 :\", semverRange(\"~1.2.3\", \"1.3.0\"));\n# exemple de sortie (valeurs fictives)\n# ┌─────────┬─────────────┬─────────┐\n# │ (index) │ nom         │ version │\n# ├─────────┼─────────────┼─────────┤\n# │ 0       │ ''lib-http''  │ ''1.4.2'' │\n# │ 1       │ ''templater'' │ ''2.0.3'' │\n# └─────────┴─────────────┴─────────┘\n# ^1.2.3 accepte 1.5.0 : true\n# ^1.2.3 accepte 2.0.0 : false\n# ~1.2.3 accepte 1.2.9 : true\n# ~1.2.3 accepte 1.3.0 : false","language":"javascript"},{"type":"schema","content":"{\"v\":1,\"kind\":\"steps\",\"title\":\"Pour lire un avis de dépendance\",\"numbered\":true,\"items\":[{\"title\":\"Versions touchées\",\"text\":\"quels paquets et quelles versions sont touchés ?\",\"icon\":\"package\",\"tone\":\"cyan\"},{\"title\":\"Version corrigée\",\"text\":\"quelle version corrige ?\",\"icon\":\"wrench\",\"tone\":\"green\"},{\"title\":\"Contexte d’usage\",\"text\":\"la dépendance est-elle dans le code livré ou seulement dans l’outillage ?\",\"icon\":\"layers\",\"tone\":\"blue\"},{\"title\":\"Atteignabilité\",\"text\":\"le composant vulnérable est-il réellement atteignable ?\",\"icon\":\"target\",\"tone\":\"amber\"},{\"title\":\"Stratégie\",\"text\":\"mise à jour, retrait, contournement temporaire, surveillance\",\"icon\":\"workflow\",\"tone\":\"violet\"}]}"},{"type":"text","content":"Une mise à jour ne se priorise pas seulement avec une gravité. Tu regardes aussi si la dépendance tourne en production, si la fonctionnalité vulnérable est atteignable, si un contournement crédible existe, et si la correction casse l’application. Un paquet de développement vulnérable dans une chaîne de construction ne s’ignore pas, mais il ne se traite pas forcément avant une bibliothèque exposée sur le chemin d’authentification en production. Le même raisonnement vaut pour le typosquatting : un nom presque bon peut coûter très cher s’il entre dans ton dépôt ou dans ton pipeline."},{"type":"example","content":"Exemple corrigé : « lib-http » tourne dans le service public d’authentification et sa version « 1.4.2 » reste sous la version corrigée « 1.4.4 ». « templater » est vulnérable lui aussi, mais n’est utilisé que pour générer un export interne lancé à la demande. La priorité va d’abord à « lib-http ». En parallèle, on garde un verrouillage propre, on exécute « npm ci » dans l’intégration continue, et on génère une SBOM pour savoir rapidement si la même bibliothèque se cache ailleurs."},{"type":"callout","content":"Erreurs fréquentes : installer en production sans fichier de verrouillage ; croire qu’une seule gravité suffit à décider ; négliger les dépendances transitives ; ajouter un paquet au nom presque familier sans vérifier son origine ; mettre à jour en urgence sans test minimal ni plan de retour arrière."},{"type":"callout","content":"Sécurité : tu analyses tes propres dépendances ou celles d’un projet pour lequel tu as l’autorisation d’agir. Ne téléverse ni archive privée, ni code source sensible vers un service tiers sans nécessité. Quand tu partages un exemple pédagogique, garde des noms de paquets ou d’applications fictifs si le contexte réel est confidentiel."},{"type":"callout","content":"À retenir : la chaîne d’approvisionnement se défend par l’inventaire, le verrouillage, la veille et la mise à jour testée. Un avis utile se lit avec son contexte réel d’exposition. Un paquet non verrouillé ou mal identifié peut devenir une faille aussi sérieuse qu’un bug dans ton propre code."},{"type":"callout","content":"Pour pratiquer : Travaille dans « TP 6 : configuration, dépendances et notation CVSS » : lis des avis fictifs, retrouve les versions touchées, classe les correctifs par exposition réelle, puis termine par le quiz."},{"type":"resource","content":"OWASP Top 10:2025 : A03, défaillances de la chaîne d’approvisionnement logicielle (en anglais)","url":"https://top10.owasp.org/2025/A03_2025-Software_Supply_Chain_Failures/"},{"type":"resource","content":"OWASP : aide-mémoire sur la gestion des dépendances vulnérables (en anglais)","url":"https://cheatsheetseries.owasp.org/cheatsheets/Vulnerable_Dependency_Management_Cheat_Sheet.html"},{"type":"resource","content":"OWASP : aide-mémoire sur la sécurité de la chaîne d’approvisionnement logicielle (en anglais)","url":"https://cheatsheetseries.owasp.org/cheatsheets/Software_Supply_Chain_Security_Cheat_Sheet.html"},{"type":"resource","content":"OWASP : aide-mémoire sur la sécurité npm (en anglais)","url":"https://cheatsheetseries.owasp.org/cheatsheets/NPM_Security_Cheat_Sheet.html"},{"type":"resource","content":"GitHub Advisory Database : les avis de sécurité des dépendances (en anglais)","url":"https://github.com/advisories"},{"type":"resource","content":"CycloneDX : un format de nomenclature logicielle (SBOM) (en anglais)","url":"https://cyclonedx.org/"},{"type":"resource","content":"npm : la commande npm ci (en anglais)","url":"https://docs.npmjs.com/cli/v10/commands/npm-ci"},{"type":"resource","content":"npm : le versionnage sémantique (en anglais)","url":"https://docs.npmjs.com/about-semantic-versioning"},{"type":"resource","content":"npm : l’incident event-stream (en anglais)","url":"https://blog.npmjs.org/post/180565383195/details-about-the-event-stream-incident.html"},{"type":"resource","content":"NVD : CVE-2021-44228 (Log4Shell) (en anglais)","url":"https://nvd.nist.gov/vuln/detail/CVE-2021-44228"},{"type":"resource","content":"NVD : CVE-2024-3094 (porte dérobée xz/liblzma) (en anglais)","url":"https://nvd.nist.gov/vuln/detail/CVE-2024-3094"},{"type":"resource","content":"SPDX : un format de nomenclature logicielle (SBOM) (en anglais)","url":"https://spdx.dev/"}]}'::jsonb, 24, 30, 2),
  ('54ee745a-1c3d-2c4a-2837-8ed0b10ba2fb', '40abe0c4-0341-1c25-adee-8292a16408cf', '014933f4-4c0b-c7cd-bff2-02fa5109ba11', 'Développer sans reproduire les failles : revue de code, tests de sécurité et intégration continue', 'Intègre la sécurité au cycle de développement : exigences, revue de code, détection de secrets, tests automatisés et pipeline qui bloque avant la production.', '{"blocks":[{"type":"callout","content":"Objectifs : relier une exigence ASVS à un contrôle concret, préparer une petite revue de code sécurité, distinguer SAST, DAST et SCA, détecter un secret avant le commit, et expliquer le rôle d’un « security.txt » dans une divulgation coordonnée."},{"type":"callout","content":"Prérequis : avoir déjà vu les principales familles de failles web, notamment injection, XSS, contrôle d’accès et secrets."},{"type":"callout","content":"Mise en situation : Moussa travaille sur une nouvelle API de dons pour l’association Teranga. Le code fonctionne, mais la première revue révèle une concaténation SQL, un « innerHTML », un secret codé en dur et une route d’administration sans contrôle d’accès clair. Moussa doit transformer cette revue en habitudes durables plutôt qu’en correction de dernière minute."},{"type":"callout","content":"Vidéo à venir : Faire entrer la sécurité dans la routine de développement"},{"type":"text","content":"Développer de façon sûre ne veut pas dire ajouter un contrôle final à la veille de la mise en production. Cela veut dire décider tôt ce qui doit être vrai, puis vérifier ces exigences tout au long du cycle. L’ASVS d’OWASP sert justement de catalogue d’exigences de vérification. Un projet simple exposé à Internet peut viser d’abord les contrôles de base. Une application plus sensible monte ensuite en exigence. La modélisation des menaces, par exemple avec STRIDE, sert à choisir où investir l’effort avant même d’écrire tout le code."},{"type":"schema","content":"{\"v\":1,\"kind\":\"cycle\",\"title\":\"Chaîne de développement sûre\",\"center\":\"sécurité intégrée\",\"nodes\":[{\"label\":\"Exigences\",\"text\":\"ASVS, périmètre, données sensibles, rôles\",\"icon\":\"list\",\"tone\":\"cyan\"},{\"label\":\"Conception\",\"text\":\"menaces, surfaces d’attaque, choix d’architecture\",\"icon\":\"puzzle\",\"tone\":\"blue\"},{\"label\":\"Code\",\"text\":\"revues, normes, tests unitaires de sécurité\",\"icon\":\"code\",\"tone\":\"violet\"},{\"label\":\"Pipeline\",\"text\":\"SAST, SCA, secrets, tests bloquants\",\"icon\":\"workflow\",\"tone\":\"amber\"},{\"label\":\"Déploiement\",\"text\":\"secrets séparés, rollback, vérifications finales\",\"icon\":\"upload\",\"tone\":\"green\"},{\"label\":\"Retour\",\"text\":\"rapports, incidents, correction et re-test\",\"icon\":\"refresh\",\"tone\":\"red\"}]}"},{"type":"text","content":"La revue de code sécurité cherche des motifs concrets. Quatre exemples reviennent sans cesse : une requête SQL concaténée avec une entrée utilisateur, un « innerHTML » alimenté par une donnée non fiable, un secret codé en dur, et une route sensible qui ne vérifie pas clairement le rôle autorisé. La revue ne se contente pas d’écrire « à revoir ». Elle note la preuve, le risque et la correction attendue. Une règle utile pour débuter : si la revue ne dit pas quoi corriger et comment vérifier la correction, elle n’est pas finie."},{"type":"schema","content":"{\"v\":1,\"kind\":\"table\",\"title\":\"Extrait de revue à relire\",\"columns\":[\"Extrait\",\"Défaut à repérer\"],\"rows\":[[\"const sql = \\\"SELECT * FROM dons WHERE email = ''\\\" + email + \\\"''\\\";\",\"injection\"],[\"zone.innerHTML = commentaire;\",\"XSS\"],[\"const apiKey = \\\"CLE_EXEMPLE_SERVICE\\\";\",\"secret codé en dur\"],[\"app.post(\\\"/admin/export\\\", exportCsv);\",\"contrôle d’accès absent\"]],\"mono\":[0]}"},{"type":"text","content":"SAST, DAST et SCA ne couvrent pas la même chose. Le SAST lit le code ou l’arbre compilé sans exécuter l’application. Le DAST observe l’application en fonctionnement depuis l’extérieur. Le SCA analyse les dépendances et leurs avis de sécurité. Aucun ne remplace la revue humaine. Ensemble, ils réduisent l’oubli. La détection de secrets dans le pipeline répond à un besoin encore plus simple : empêcher qu’une clé ou un jeton entre dans le dépôt principal."},{"type":"text","content":"Démonstration guidée : le petit contrôle ci-dessous crée un fichier d’essai, puis refuse trois motifs faciles à repérer avant le commit. Le premier signale un secret fictif « CLE_EXEMPLE_ ». Le deuxième signale « innerHTML = ». Le troisième signale une concaténation SQL très naïve. Dans la vraie vie, tu utiliseras aussi des outils spécialisés. L’exercice t’apprend surtout à penser en garde-fou automatique."},{"type":"text","content":"Prérequis de démonstration : vérifie d’abord « node --version ». Cet extrait n’emploie que des API Node.js stables de longue date. Si Node.js manque ou si l’extrait échoue sur ta machine, mets-le à jour avant de continuer."},{"type":"code","content":"const fs = require(\"node:fs\");\nconst os = require(\"node:os\");\nconst path = require(\"node:path\");\n\nconst fichier = path.join(os.tmpdir(), \"swb-hook-demo.js\");\nfs.writeFileSync(\n  fichier,\n  [\n    ''const apiKey = \"CLE_EXEMPLE_SERVICE\";'',\n    ''zone.innerHTML = commentaire;'',\n    ''const sql = \"SELECT * FROM dons WHERE email = \\\"\" + email + \"\\\"\";'',\n  ].join(\"\\n\"),\n  \"utf8\",\n);\n\nconst contenu = fs.readFileSync(fichier, \"utf8\");\nconst regles = [\n  { nom: \"secret fictif\", motif: /CLE_EXEMPLE_[A-Z0-9_]+/ },\n  { nom: \"innerHTML\", motif: /\\.innerHTML\\s*=/ },\n  { nom: \"concat SQL naïve\", motif: /SELECT \\* FROM .*\\+\\s*[a-zA-Z_][a-zA-Z0-9_]*/ },\n];\n\nconst trouves = regles.filter((regle) => regle.motif.test(contenu)).map((regle) => regle.nom);\nif (trouves.length > 0) {\n  console.log(\"commit refusé :\", trouves.join(\", \"));\n} else {\n  console.log(\"aucun motif bloquant détecté\");\n}\n# exemple de sortie (valeurs fictives)\n# commit refusé : secret fictif, innerHTML, concat SQL naïve","language":"javascript"},{"type":"schema","content":"{\"v\":1,\"kind\":\"steps\",\"title\":\"Avant de fusionner\",\"numbered\":true,\"items\":[{\"title\":\"Revue\",\"text\":\"la revue de code note-t-elle les défauts concrets ?\",\"icon\":\"search\",\"tone\":\"blue\"},{\"title\":\"Tests bloquants\",\"text\":\"un test automatisé casse-t-il la fusion en cas de secret ou dépendance critique ?\",\"icon\":\"shield-alert\",\"tone\":\"red\"},{\"title\":\"Re-test\",\"text\":\"la correction a-t-elle été re-testée ?\",\"icon\":\"refresh\",\"tone\":\"green\"},{\"title\":\"Divulgation\",\"text\":\"un « security.txt » existe-t-il pour la divulgation coordonnée ?\",\"icon\":\"mail\",\"tone\":\"violet\"}]}"},{"type":"text","content":"La divulgation coordonnée fait aussi partie d’un développement responsable. Le fichier « security.txt », défini par la RFC 9116, donne un point de contact et une politique minimale pour signaler une vulnérabilité. Il ne remplace ni un bug bounty, ni une équipe sécurité, mais il évite à un chercheur de ne pas savoir à qui écrire. Côté équipe produit, cela complète le cycle : exigences, construction, revue, test, réception d’un signal externe, correction, re-test."},{"type":"example","content":"Exemple corrigé : sur l’extrait de revue, la correction attendue n’est pas « mieux coder ». Elle est précise. La requête SQL devient paramétrée. « innerHTML » est remplacé par « textContent » ou par un assainissement contrôlé si du HTML riche est réellement nécessaire. La clé sort du code et passe dans un mécanisme de secret dédié. La route « /admin/export » vérifie un rôle explicite côté serveur avant l’action. Chaque correction reçoit ensuite un test ou un contrôle de pipeline correspondant."},{"type":"callout","content":"Erreurs fréquentes : traiter la sécurité comme une étape finale ; croire qu’un seul outil remplace la revue humaine ; accepter un secret en disant qu’il sera changé plus tard ; fermer une alerte de scanner sans expliquer pourquoi ; fusionner une correction sans re-test ciblé."},{"type":"callout","content":"Sécurité : travaille uniquement sur ton dépôt ou un dépôt pour lequel tu as l’autorisation d’agir. Ne publie pas un secret réel dans un exemple, même pour « montrer le problème ». Les démonstrations gardent donc des motifs fictifs et des chemins d’essai."},{"type":"callout","content":"À retenir : un développement sûr repose sur des exigences claires, des revues concrètes et des garde-fous automatiques. SAST, DAST, SCA et détection de secrets se complètent, mais ne remplacent pas l’analyse humaine. Une bonne correction se termine par un re-test et un moyen clair de recevoir un signal externe."},{"type":"callout","content":"Pour pratiquer : Travaille dans « Projet final : auditer l’application de réservation et rédiger le rapport » : utilise cette leçon pour repérer les contrôles qui devraient déjà exister dans le cycle de développement, puis note honnêtement que le projet final prépare l’audit plus qu’il ne met en place toute la chaîne CI. Termine par le quiz."},{"type":"resource","content":"OWASP : l’Application Security Verification Standard (ASVS) (en anglais)","url":"https://owasp.org/www-project-application-security-verification-standard/"},{"type":"resource","content":"OWASP SAMM : mesurer la maturité du développement sécurisé (en anglais)","url":"https://owasp.org/www-project-samm/"},{"type":"resource","content":"OWASP : aide-mémoire sur la modélisation des menaces (en anglais)","url":"https://cheatsheetseries.owasp.org/cheatsheets/Threat_Modeling_Cheat_Sheet.html"},{"type":"resource","content":"RFC 9116 : le fichier security.txt (en anglais)","url":"https://www.rfc-editor.org/rfc/rfc9116"},{"type":"resource","content":"Node.js : le module fs (en anglais)","url":"https://nodejs.org/api/fs.html"}]}'::jsonb, 24, 30, 3),
  ('5e3fa110-5967-6ae6-81c2-46ec51d36e07', '40abe0c4-0341-1c25-adee-8292a16408cf', '014933f4-4c0b-c7cd-bff2-02fa5109ba11', 'Se défendre en profondeur : pare-feu applicatif, limitation de débit, journaux et détection', 'Découvre comment ralentir, voir et qualifier une attaque web avec un WAF, une limitation de débit et des journaux utiles, sans confondre défense en profondeur et correction définitive.', '{"blocks":[{"type":"callout","content":"Objectifs : expliquer le rôle d’un WAF, distinguer limitation de débit et contrôle d’accès, choisir quoi journaliser sans fuite de secret, repérer un motif d’abus dans un journal, et décrire une réponse à incident web en cinq étapes."},{"type":"callout","content":"Prérequis : avoir déjà étudié les injections, les accès refusés et la journalisation côté application."},{"type":"callout","content":"Mise en situation : Ama administre une petite application de dons. Une route reçoit beaucoup de 404 et de 401 depuis quelques adresses, le WAF bloque déjà quelques signatures, mais certaines requêtes passent encore. Ama doit comprendre ce que la couche défensive voit, ce qu’elle ne voit pas, et comment alerter sans noyer l’équipe."},{"type":"callout","content":"Vidéo à venir : Voir et ralentir une attaque web sans se raconter d’histoire"},{"type":"text","content":"La défense en profondeur ajoute des couches qui rendent l’attaque plus difficile, plus visible ou plus coûteuse, sans prétendre qu’une seule d’entre elles suffit. Un WAF filtre certaines requêtes connues ou anormales avant l’application, par exemple avec un moteur comme ModSecurity et un jeu de règles comme OWASP CRS. Une limitation de débit ralentit les abus répétitifs. La journalisation garde une trace utile de ce qui a été tenté, autorisé ou refusé. Aucune de ces couches ne corrige une injection SQL ou un XSS dans le code. Elles gagnent du temps et réduisent l’impact, mais la vraie correction reste dans l’application."},{"type":"schema","content":"{\"v\":1,\"kind\":\"flow\",\"title\":\"Couches utiles\",\"nodes\":[{\"label\":\"Navigateur\",\"text\":\"point de départ des requêtes\",\"icon\":\"globe\",\"tone\":\"cyan\"},{\"label\":\"CDN ou proxy\",\"text\":\"limitation de débit, renvoie souvent `429`\",\"icon\":\"route\",\"tone\":\"blue\"},{\"label\":\"WAF\",\"text\":\"filtre quelques motifs connus, pas la logique métier\",\"icon\":\"shield\",\"tone\":\"amber\"},{\"label\":\"Application\",\"text\":\"journaux visibles et réanalysables\",\"icon\":\"code\",\"tone\":\"violet\"},{\"label\":\"Base de données\",\"text\":\"le correctif code supprime la cause profonde\",\"icon\":\"database\",\"tone\":\"green\"}],\"caption\":\"La chaîne défensive ralentit et voit l’abus, mais seule l’application corrigée supprime la cause.\"}"},{"type":"text","content":"Un journal de sécurité applicative répond à une règle simple : qui, quoi, quand, où, résultat, identifiant de corrélation. Tu y gardes par exemple l’adresse ou l’identifiant réseau utile, le compte s’il existe, la route appelée, la méthode, le code HTTP, la décision de sécurité, et l’identifiant qui relie la requête à d’autres traces. Tu n’y gardes jamais un mot de passe, un jeton de session, un secret d’API ou un numéro de carte. La CNIL recommande d’ailleurs de journaliser les actions, anomalies et interventions techniques utiles, sans dupliquer inutilement des données personnelles. Si tu dois journaliser un corps de requête pour une raison précise, tu le fais de façon minimale et contrôlée."},{"type":"text","content":"Démonstration guidée : le script lit un petit journal d’accès JSON inventé, puis lève une alerte lorsqu’une même adresse dépasse trois réponses 404 ou 401 dans une fenêtre glissante de cinq minutes. Il ne bloque rien lui-même. Il produit seulement un signal défendable. Dans une équipe réelle, ce type de logique complète le WAF : une requête peut être autorisée par le WAF et rester pourtant suspecte par sa fréquence ou par sa cible."},{"type":"text","content":"Prérequis de démonstration : vérifie d’abord « node --version ». Cet extrait utilise seulement des tableaux, des dates ISO et « console.table ». Si Node.js n’est pas installé ou si la commande échoue, mets-le à jour avant de continuer."},{"type":"code","content":"const evenements = [\n  { ts: \"2026-03-10T09:00:00Z\", ip: \"192.0.2.44\", status: 404, path: \"/.env\" },\n  { ts: \"2026-03-10T09:01:10Z\", ip: \"192.0.2.44\", status: 404, path: \"/wp-login.php\" },\n  { ts: \"2026-03-10T09:02:05Z\", ip: \"192.0.2.44\", status: 401, path: \"/admin\" },\n  { ts: \"2026-03-10T09:03:12Z\", ip: \"192.0.2.55\", status: 200, path: \"/catalogue\" },\n  { ts: \"2026-03-10T09:04:01Z\", ip: \"192.0.2.44\", status: 404, path: \"/phpmyadmin/\" },\n];\n\nconst seuil = 3;\nconst fenetreMs = 5 * 60 * 1000;\nconst alertes = [];\n\nfor (let i = 0; i < evenements.length; i += 1) {\n  const courant = evenements[i];\n  if (![401, 404].includes(courant.status)) continue;\n  const debut = new Date(courant.ts).getTime() - fenetreMs;\n  const total = evenements.filter((evt) => evt.ip === courant.ip && [401, 404].includes(evt.status) && new Date(evt.ts).getTime() >= debut && new Date(evt.ts).getTime() <= new Date(courant.ts).getTime()).length;\n  if (total >= seuil) {\n    alertes.push({ ip: courant.ip, ts: courant.ts, total });\n  }\n}\n\nconsole.table(alertes);\n# exemple de sortie (valeurs fictives)\n# ┌─────────┬──────────────┬────────────────────────┬───────┐\n# │ (index) │ ip           │ ts                     │ total │\n# ├─────────┼──────────────┼────────────────────────┼───────┤\n# │ 0       │ ''192.0.2.44'' │ ''2026-03-10T09:02:05Z'' │ 3     │\n# │ 1       │ ''192.0.2.44'' │ ''2026-03-10T09:04:01Z'' │ 4     │\n# └─────────┴──────────────┴────────────────────────┴───────┘","language":"javascript"},{"type":"schema","content":"{\"v\":1,\"kind\":\"steps\",\"title\":\"Réponse à incident web en cinq étapes\",\"numbered\":true,\"items\":[{\"title\":\"Isoler\",\"text\":\"ce qui doit l’être sans détruire les preuves\",\"icon\":\"ban\",\"tone\":\"amber\"},{\"title\":\"Préserver\",\"text\":\"les journaux et la configuration utile\",\"icon\":\"archive\",\"tone\":\"blue\"},{\"title\":\"Comprendre\",\"text\":\"le chemin d’attaque ou d’abus\",\"icon\":\"file-search\",\"tone\":\"violet\"},{\"title\":\"Corriger\",\"text\":\"la cause et pas seulement le symptôme\",\"icon\":\"wrench\",\"tone\":\"red\"},{\"title\":\"Vérifier\",\"text\":\"le correctif et renforcer la détection\",\"icon\":\"check\",\"tone\":\"green\"}]}"},{"type":"text","content":"Le WAF et la limitation de débit ont des limites claires. Un WAF produit des faux positifs, peut gêner une fonctionnalité légitime, et se contourne parfois. Une limitation de débit doit distinguer un abus automatisé d’un pic normal d’activité, sinon elle pénalise les utilisateurs. Les réponses 429 avec un « Retry-After » cohérent aident le client légitime à se comporter correctement, mais elles ne valent pas contrôle d’accès. Enfin, une alerte utile reste une hypothèse à confirmer : elle doit être relue avec le contexte, les journaux applicatifs et, si besoin, le parcours complet de la requête."},{"type":"example","content":"Exemple corrigé : si le WAF bloque déjà quelques signatures sur « /.env », mais que le journal applicatif montre encore quatre 404 et 401 en cinq minutes sur « /admin », « /wp-login.php » et « /phpmyadmin/ », la conclusion raisonnable est « tentative de repérage persistante, pas correction suffisante ». On peut relever le signal, durcir la route d’administration, vérifier la limitation de débit, puis corriger le code ou la configuration qui laisserait passer une vraie faille si elle existait."},{"type":"callout","content":"Erreurs fréquentes : présenter le WAF comme un correctif ; journaliser un jeton ou un mot de passe pour « aider le debug » ; alerter sur tout sans fenêtre ni seuil ; bloquer définitivement une adresse partagée sans procédure ; oublier l’identifiant de corrélation qui permettra de relier plusieurs journaux."},{"type":"callout","content":"Sécurité : n’analyse et ne modifie que ton application ou un système pour lequel tu as une autorisation écrite. Les journaux web peuvent contenir des données personnelles : protège-les, minimise-les et évite tout envoi à un service tiers. Toute mesure de blocage qui peut toucher des utilisateurs légitimes suit la procédure de l’organisation."},{"type":"callout","content":"À retenir : un WAF, une limitation de débit et de bons journaux renforcent une application, mais ne corrigent pas le code à ta place. Une alerte utile décrit un motif, pas une certitude finale. La défense en profondeur sert à ralentir, voir, corriger, puis vérifier."},{"type":"callout","content":"Pour pratiquer : Travaille dans « Projet final : auditer l’application de réservation et rédiger le rapport » : utilise cette leçon pour noter les défenses attendues et les limites d’un WAF ou d’une limitation de débit, en disant honnêtement que le projet final prépare surtout leur évaluation, pas leur déploiement complet. Termine par le quiz."},{"type":"resource","content":"OWASP : aide-mémoire sur le déni de service (en anglais)","url":"https://cheatsheetseries.owasp.org/cheatsheets/Denial_of_Service_Cheat_Sheet.html"},{"type":"resource","content":"MDN : le code de statut 429 Too Many Requests","url":"https://developer.mozilla.org/fr/docs/Web/HTTP/Reference/Status/429"},{"type":"resource","content":"CNIL : sécurité, tracer les opérations","url":"https://www.cnil.fr/fr/securite-tracer-les-operations"},{"type":"resource","content":"CNIL : guide de la sécurité des données personnelles","url":"https://www.cnil.fr/fr/guide-de-la-securite-des-donnees-personnelles-nouvelle-edition-2024"},{"type":"resource","content":"ModSecurity : le moteur de pare-feu applicatif open source (en anglais)","url":"https://modsecurity.org/"},{"type":"resource","content":"OWASP CRS : le jeu de règles génériques de détection (en anglais)","url":"https://coreruleset.org/"}]}'::jsonb, 24, 30, 4),
  ('b55726cc-ba7c-7c46-f5ed-73fd200f1d19', '40abe0c4-0341-1c25-adee-8292a16408cf', '0ffba43d-617c-5139-0143-06e458dfc382', 'Cadre d’un audit web : autorisation, périmètre et règles d’engagement', 'Pose le cadre légal et opérationnel d’un audit web : qui autorise, quoi tester, quand s’arrêter, comment traiter les données et comment s’entraîner légalement.', '{"blocks":[{"type":"callout","content":"Objectifs : distinguer audit, évaluation de vulnérabilités, revue de code et test d’intrusion, définir un périmètre, lire une règle d’engagement, repérer ce qui est hors champ, et choisir une plateforme d’entraînement légale."},{"type":"callout","content":"Prérequis : connaître les principales familles de failles web et leur impact possible."},{"type":"callout","content":"Mise en situation : Fatou reçoit un message pressé : « peux-tu tester le portail de réservation cet après-midi ? ». Elle sait déjà que la bonne réponse n’est pas « oui » tout de suite. Sans autorisation écrite, sans périmètre, sans contact d’urgence et sans règle d’arrêt, une bonne intention peut devenir une faute grave pour l’organisation comme pour elle."},{"type":"callout","content":"Vidéo à venir : Poser le cadre d’un audit avant le premier test"},{"type":"text","content":"Un audit web n’est pas toujours un test d’intrusion complet. Tu peux mener une revue de configuration, une revue de code, une évaluation de vulnérabilités, un contrôle d’exigences, ou un test d’intrusion autorisé. Le mot compte moins que le cadre. Ce cadre tient sur quelques questions simples : qui t’autorise, quels environnements sont inclus, quels comptes de test sont fournis, quelles techniques sont autorisées ou interdites, à quelles heures, à quel volume, avec quel contact d’urgence, et dans quelles conditions tu dois t’arrêter."},{"type":"schema","content":"{\"v\":1,\"kind\":\"table\",\"title\":\"Lettre de mission minimale\",\"columns\":[\"Champ\",\"À préciser\"],\"rows\":[[\"Cible\",\"URL, API, sous-domaines, environnement\"],[\"Comptes\",\"jeux d’essai fournis, rôles, MFA éventuelle\"],[\"Techniques\",\"lecture seule, scans passifs, tests actifs autorisés ou non\"],[\"Horaires\",\"plage de test, jours exclus, période sensible\"],[\"Volumétrie\",\"limites de requêtes, pas de déni de service\"],[\"Contacts\",\"responsable métier, exploitant, urgence\"],[\"Arrêt\",\"conditions d’arrêt et escalade\"]]}"},{"type":"text","content":"Le périmètre protège autant l’organisation que l’auditeur. Un CDN, un prestataire de paiement, un fournisseur d’e-mails transactionnels ou un hébergeur externe ne sont pas automatiquement dans le champ. Un sous-domaine de test ne l’est pas non plus si personne ne l’a écrit. Un environnement de production mérite encore plus de prudence : on y évite les tests destructifs et les rafales non négociées. La confidentialité compte aussi : pendant un audit, tu peux voir des journaux, des données personnelles, des noms internes ou des secrets. Tu minimises, tu protèges, et tu limites la copie ou la diffusion à ce qui est nécessaire à la mission."},{"type":"text","content":"Démonstration guidée : le petit script ci-dessous formalise une partie du périmètre. Il reçoit une liste d’hôtes autorisés et quelques exclusions. Ensuite, il répond à une question simple : « cette cible est-elle dans le champ convenu ? ». Cela ne remplace pas une vraie lettre de mission, mais cela montre qu’un périmètre se vérifie explicitement, pas à l’intuition."},{"type":"text","content":"Prérequis de démonstration : vérifie d’abord « node --version ». Cet extrait n’utilise que JavaScript de base. Si Node.js manque ou si la commande échoue, mets-le à jour avant de continuer."},{"type":"code","content":"const scope = {\n  hotesAutorises: [\"app.example.org\", \"api.example.org\"],\n  exclus: [\"paiement.example.org\", \"status.example.org\"],\n};\n\nfunction estDansLePerimetre(hote) {\n  return scope.hotesAutorises.includes(hote) && !scope.exclus.includes(hote);\n}\n\nfor (const hote of [\"app.example.org\", \"status.example.org\", \"cdn.example.org\"]) {\n  console.log(hote, estDansLePerimetre(hote));\n}\n# exemple de sortie (valeurs fictives)\n# app.example.org true\n# status.example.org false\n# cdn.example.org false","language":"javascript"},{"type":"schema","content":"{\"v\":1,\"kind\":\"steps\",\"title\":\"Divulgation responsable trouvée par hasard\",\"items\":[{\"title\":\"S’arrêter\",\"text\":\"ne pas insister ni télécharger des données inutiles\",\"icon\":\"ban\",\"tone\":\"red\"},{\"title\":\"Prouver juste assez\",\"text\":\"prendre juste assez de preuve pour expliquer le problème\",\"icon\":\"file-search\",\"tone\":\"amber\"},{\"title\":\"Chercher le contact\",\"text\":\"« /.well-known/security.txt » ou un contact officiel\",\"icon\":\"mail\",\"tone\":\"blue\"},{\"title\":\"Prévenir\",\"text\":\"sans publier la faille avant accord\",\"icon\":\"bell\",\"tone\":\"green\"}]}"},{"type":"text","content":"Le cadre légal se résume alors en une règle claire : tu testes seulement ce que tu as le droit de tester, de la façon autorisée. Si tu trouves une faille par hasard en dehors d’une mission, tu ne l’exploites pas davantage. Tu cherches un contact de divulgation, souvent via « security.txt » ou un canal officiel, puis tu fournis une preuve minimale et défendable. Pour t’entraîner, tu restes sur des plateformes prévues pour cela, comme la Web Security Academy de PortSwigger, OWASP Juice Shop, WebGoat ou DVWA en local sur ta propre machine."},{"type":"example","content":"Exemple corrigé : une lettre de mission inventée autorise « app.example.org » et « api.example.org », en préproduction, de 09:00 à 17:00, avec comptes de test fournis, scans passifs autorisés et tests actifs sans déni de service. « paiement.example.org » reste hors champ car géré par un prestataire tiers. Si tu trouves un formulaire vulnérable sur ce sous-domaine tiers, tu le notes comme hors périmètre et tu passes par le contact prévu, tu ne continues pas l’exploration."},{"type":"callout","content":"Erreurs fréquentes : croire qu’un accord oral suffit ; traiter tous les sous-domaines comme inclus ; oublier le prestataire tiers ; lancer un test actif sur la production sans volume négocié ; conserver des données de test plus longtemps que nécessaire."},{"type":"callout","content":"Sécurité : un audit web sans cadre écrit peut devenir une infraction ou un incident opérationnel. Protège les données rencontrées, respecte le besoin d’en connaître, et entraîne-toi uniquement sur des plateformes légales ou sur ton propre environnement de test."},{"type":"callout","content":"À retenir : avant le premier test, tu dois savoir quoi, où, quand, comment et jusqu’où. Le périmètre n’est jamais supposé : il est écrit. La confidentialité et la minimisation des données font partie du travail d’audit. Pour apprendre, tu restes sur des cibles prévues pour cela."},{"type":"callout","content":"Pour pratiquer : Travaille dans « Projet final : auditer l’application de réservation et rédiger le rapport » : commence par relire le périmètre, les exclusions et les règles d’engagement du dossier, puis termine par le quiz."},{"type":"resource","content":"OWASP : le guide de test de sécurité web (WSTG) (en anglais)","url":"https://owasp.org/www-project-web-security-testing-guide/"},{"type":"resource","content":"OWASP Juice Shop : une application volontairement vulnérable pour s’entraîner (en anglais)","url":"https://owasp.org/www-project-juice-shop/"},{"type":"resource","content":"OWASP WebGoat : un parcours d’exercices de sécurité web (en anglais)","url":"https://owasp.org/www-project-webgoat/"},{"type":"resource","content":"RFC 9116 : le fichier security.txt (en anglais)","url":"https://www.rfc-editor.org/rfc/rfc9116"},{"type":"resource","content":"CNIL : comprendre le RGPD","url":"https://www.cnil.fr/fr/comprendre-le-rgpd"}]}'::jsonb, 22, 30, 1),
  ('a8bca3fe-de26-477d-224d-ec1aa4f0d58f', '40abe0c4-0341-1c25-adee-8292a16408cf', '0ffba43d-617c-5139-0143-06e458dfc382', 'Mener un audit web par étapes : cartographier, vérifier, consigner', 'Suis une méthode d’audit web progressive : lecture seule d’abord, cartographie, configuration, sessions, accès, entrées, puis consignation rigoureuse des preuves.', '{"blocks":[{"type":"callout","content":"Objectifs : dérouler les grandes étapes du WSTG, distinguer lecture seule et test actif, cartographier des routes et des rôles, consigner une preuve utile, vérifier un faux positif, et résumer des en-têtes manquants à partir d’un jeu de réponses local."},{"type":"callout","content":"Prérequis : avoir compris le cadre d’un audit, les principales familles de failles web et l’importance du périmètre."},{"type":"callout","content":"Mise en situation : Awa prépare l’audit de l’application de réservation de Baobab Tech. Elle a l’autorisation, les comptes de test et la fenêtre de tir. Son risque principal n’est plus juridique : c’est de partir dans tous les sens. Elle doit donc suivre une méthode, commencer en lecture seule, consigner proprement ses observations et ne lancer un test actif que lorsqu’elle sait pourquoi."},{"type":"callout","content":"Vidéo à venir : Mener un audit web avec une méthode reproductible"},{"type":"text","content":"Le WSTG d’OWASP sert de guide de test, pas de scénario rigide à cocher sans réfléchir. Sa logique reste pourtant très utile : cadrage, cartographie, configuration, identités, authentification, autorisation, sessions, injection et autres entrées non fiables, erreurs, cryptographie, logique métier, client et API. Le bon ordre n’est pas « tout tester tout de suite ». Le bon ordre est « comprendre d’abord, tester ensuite ». Une lecture seule des en-têtes, des cookies, de la configuration TLS, de « robots.txt », de « security.txt » et du plan du site donne souvent déjà beaucoup d’informations."},{"type":"schema","content":"{\"v\":1,\"kind\":\"steps\",\"title\":\"Audit web par étapes\",\"numbered\":true,\"items\":[{\"title\":\"Cartographier\",\"text\":\"pages, routes, rôles, versions, API\",\"icon\":\"route\",\"tone\":\"cyan\"},{\"title\":\"Lire\",\"text\":\"TLS, cookies, en-têtes, méthodes, réponses\",\"icon\":\"book\",\"tone\":\"blue\"},{\"title\":\"Vérifier\",\"text\":\"sessions, accès, entrées, erreurs\",\"icon\":\"shield-check\",\"tone\":\"violet\"},{\"title\":\"Approfondir\",\"text\":\"logique métier, API, client riche\",\"icon\":\"microscope\",\"tone\":\"amber\"},{\"title\":\"Consigner\",\"text\":\"requête, réponse, conclusion, preuve, référence\",\"icon\":\"document\",\"tone\":\"green\"}]}"},{"type":"text","content":"La différence entre analyse passive et active est simple mais importante. Passive : tu observes ce que l’application renvoie sans chercher à la faire sortir de son comportement normal. Active : tu modifies les paramètres, les comptes, les rôles, le volume ou les entrées pour vérifier une hypothèse. Même sur une cible autorisée, l’actif mérite une intention claire. Un scanner comme ZAP en mode « baseline » convient bien pour commencer sur son propre site : il signale quelques points de configuration sans lancer toute la boîte à outils offensive. Ensuite, chaque signal doit être vérifié manuellement, car un scanner produit toujours des faux positifs."},{"type":"text","content":"Démonstration guidée : le script ci-dessous lit un petit fichier local contenant des réponses HTTP inventées. Il ne fait aucune requête réseau réelle. Il résume pour chaque URL le statut, puis les en-têtes attendus qui manquent. C’est un bon exercice de méthode : collecter, lire, résumer, puis seulement décider quoi vérifier plus loin à la main."},{"type":"text","content":"Prérequis de démonstration : vérifie d’abord « node --version ». Cet extrait n’utilise que « node:fs », « node:os », « node:path » et « console.table ». Si Node.js manque ou si l’extrait échoue, mets-le à jour avant de continuer."},{"type":"code","content":"const fs = require(\"node:fs\");\nconst os = require(\"node:os\");\nconst path = require(\"node:path\");\n\nconst fichier = path.join(os.tmpdir(), \"swb-audit-reponses.json\");\nconst reponses = [\n  { url: \"https://app.example.org/\", status: 200, headers: { \"strict-transport-security\": \"max-age=31536000\", \"x-content-type-options\": \"nosniff\" } },\n  { url: \"https://app.example.org/login\", status: 200, headers: { \"content-security-policy\": \"default-src ''self''\", \"referrer-policy\": \"strict-origin-when-cross-origin\" } },\n  { url: \"https://app.example.org/admin\", status: 403, headers: { \"x-content-type-options\": \"nosniff\" } },\n];\nfs.writeFileSync(fichier, JSON.stringify(reponses, null, 2), \"utf8\");\n\nconst attentes = [\"strict-transport-security\", \"content-security-policy\", \"x-content-type-options\"];\nconst charges = JSON.parse(fs.readFileSync(fichier, \"utf8\"));\nconst resume = charges.map((item) => ({\n  url: item.url,\n  status: item.status,\n  manquants: attentes.filter((nom) => !(nom in item.headers)),\n}));\nconsole.table(resume);\n# exemple de sortie (valeurs fictives)\n# ┌─────────┬────────────────────────────────┬────────┬──────────────────────────────────────────────┐\n# │ (index) │ url                            │ status │ manquants                                    │\n# ├─────────┼────────────────────────────────┼────────┼──────────────────────────────────────────────┤\n# │ 0       │ ''https://app.example.org/''     │ 200    │ [ ''content-security-policy'' ]                │\n# │ 1       │ ''https://app.example.org/login''│ 200    │ [ ''strict-transport-security'', ''x-content-type-options'' ] │\n# │ 2       │ ''https://app.example.org/admin''│ 403    │ [ ''strict-transport-security'', ''content-security-policy'' ] │\n# └─────────┴────────────────────────────────┴────────┴──────────────────────────────────────────────┘","language":"javascript"},{"type":"schema","content":"{\"v\":1,\"kind\":\"table\",\"title\":\"Fiche de test à tenir à jour\",\"columns\":[\"Champ\",\"Contenu attendu\"],\"rows\":[[\"Date UTC\",\"quand le test a été lancé\"],[\"Cible\",\"URL, rôle et compte de test\"],[\"Requête\",\"méthode, chemin, en-têtes utiles, corps si nécessaire\"],[\"Réponse\",\"code, en-têtes, extrait utile\"],[\"Conclusion\",\"fait, hypothèse ou faux positif\"],[\"Suite\",\"re-test, correction attendue, référence WSTG ou ASVS\"]]}"},{"type":"text","content":"Consigner proprement une preuve aide autant que trouver une faille. Une bonne note permet à un collègue de rejouer le test, à un développeur de reproduire le problème, et à un responsable de comprendre la priorité. Tu notes donc la date, le rôle utilisé, la requête exacte, la réponse, puis la conclusion. Tu évites les phrases vagues comme « ça a l’air risqué ». Tu écris plutôt « la route « /admin/export » répond 200 au compte standard Ama, ce qui contredit la matrice de droits fournie »."},{"type":"example","content":"Exemple corrigé : mauvaise consigne, « l’appli semble manquer d’en-têtes, à vérifier ». Bonne consigne, « le 2026-03-10 à 09:42Z, la réponse 200 de « https://app.example.org/ » contient « Strict-Transport-Security » et « X-Content-Type-Options », mais pas de « Content-Security-Policy ». Signal de configuration à confirmer sur les autres routes avant recommandation globale. Référence : configuration et en-têtes du WSTG ». La deuxième version se rejoue et se relit, la première non."},{"type":"callout","content":"Erreurs fréquentes : attaquer avant d’avoir cartographié ; confondre lecture seule et test actif ; recopier le résultat d’un scanner sans vérification manuelle ; oublier le rôle ou le compte de test utilisé ; écrire une conclusion sans requête ni réponse attachées."},{"type":"callout","content":"Sécurité : respecte le périmètre, les horaires et la volumétrie convenus. En production, évite les tests destructifs et les rafales non négociées. Toute preuve collectée peut contenir des données sensibles : limite la diffusion, protège les captures et détruis les copies non nécessaires selon la mission."},{"type":"callout","content":"À retenir : un audit web sérieux commence par comprendre avant de forcer. Lecture seule, cartographie, test ciblé, preuve reproductible : voilà la séquence saine. Un scanner aide à voir, pas à conclure. La preuve consignée vaut autant que le test lui-même."},{"type":"callout","content":"Pour pratiquer : Travaille dans « Projet final : auditer l’application de réservation et rédiger le rapport » : reprends les étapes du WSTG, commence par les observations en lecture seule, puis complète tes fiches de test avant le quiz."},{"type":"resource","content":"OWASP : le guide de test de sécurité web (WSTG) (en anglais)","url":"https://owasp.org/www-project-web-security-testing-guide/"},{"type":"resource","content":"ZAP : la documentation du scanner de sécurité web OWASP ZAP (en anglais)","url":"https://www.zaproxy.org/docs/"},{"type":"resource","content":"OWASP : l’Application Security Verification Standard (ASVS) (en anglais)","url":"https://owasp.org/www-project-application-security-verification-standard/"},{"type":"resource","content":"OWASP WSTG : les catégories de tests de la version actuelle (en anglais)","url":"https://wstg.owasp.org/latest/4-Web_Application_Security_Testing/"},{"type":"resource","content":"Node.js : le module fs (en anglais)","url":"https://nodejs.org/api/fs.html"}]}'::jsonb, 26, 30, 2),
  ('ddbc0f5c-b92f-3348-fdb7-14d0852a58ed', '40abe0c4-0341-1c25-adee-8292a16408cf', '0ffba43d-617c-5139-0143-06e458dfc382', 'Rédiger le rapport : sévérité, preuve, correctif et vérification', 'Transforme une observation brute en constat exploitable : preuve reproductible, catégorie OWASP et CWE, score CVSS, recommandation actionnable et plan de re-test.', '{"blocks":[{"type":"callout","content":"Objectifs : structurer un constat d’audit, distinguer observation et conclusion, calculer une note CVSS v3.1, relier un constat à OWASP et à une CWE, écrire une recommandation actionnable, et préparer un re-test clair."},{"type":"callout","content":"Prérequis : avoir déjà étudié la méthode d’audit, la logique CVSS et les principales catégories de failles du parcours."},{"type":"callout","content":"Mise en situation : Koffi a terminé ses vérifications techniques sur l’application de réservation. Il a plusieurs observations valides, mais son responsable ne veut ni slogans vagues ni liste brute de captures. Koffi doit rédiger un rapport que la direction comprenne, que les développeurs puissent corriger, et qu’un re-test puisse confirmer."},{"type":"callout","content":"Vidéo à venir : Écrire un constat utile du point de vue technique comme métier"},{"type":"text","content":"Un rapport d’audit utile relie trois publics. La direction veut comprendre le niveau de risque, les biens touchés et l’ordre des priorités. Les développeurs veulent une preuve reproductible, une cause plausible et une correction testable. L’équipe sécurité veut un dossier qui se rejoue au re-test. La structure classique répond à ces trois besoins : résumé exécutif, périmètre et méthode, synthèse par gravité, constats détaillés, plan de correction, plan de re-test, puis annexes de preuve."},{"type":"schema","content":"{\"v\":1,\"kind\":\"cards\",\"title\":\"Fiche d’un constat\",\"columns\":2,\"items\":[{\"term\":\"Titre\",\"text\":\"court et spécifique\",\"icon\":\"bookmark\",\"tone\":\"cyan\"},{\"term\":\"Catégorie\",\"text\":\"OWASP 2025, CWE, éventuellement référence interne\",\"icon\":\"bookmark\",\"tone\":\"blue\"},{\"term\":\"Emplacement\",\"text\":\"route, fonction, rôle, composant ou dépendance\",\"icon\":\"pin\",\"tone\":\"violet\"},{\"term\":\"Preuve\",\"text\":\"requête, réponse, extrait ou capture minimale\",\"icon\":\"file-search\",\"tone\":\"amber\"},{\"term\":\"Impact\",\"text\":\"ce que cela permet ou expose\",\"icon\":\"alert\",\"tone\":\"red\"},{\"term\":\"Note CVSS\",\"text\":\"score, vecteur et limites de la note\",\"icon\":\"gauge\",\"tone\":\"green\"},{\"term\":\"Recommandation\",\"text\":\"action technique vérifiable\",\"icon\":\"wrench\",\"tone\":\"cyan\"},{\"term\":\"Re-test\",\"text\":\"comment confirmer la correction\",\"icon\":\"refresh\",\"tone\":\"blue\"}]}"},{"type":"text","content":"Un constat ne commence pas par « l’application est peu sûre ». Il commence par un fait. Exemple : « le compte standard Ama obtient 200 sur « /admin/export » ». Ensuite viennent l’interprétation et l’impact : contrôle d’accès défaillant, exposition potentielle de données, risque d’export non autorisé. La recommandation reste actionnable : vérifier le rôle côté serveur sur cette route et ajouter un test automatisé de refus. Une bonne recommandation se vérifie ensuite au re-test. Une mauvaise recommandation reste un slogan, par exemple « sécuriser l’application »."},{"type":"text","content":"Démonstration guidée : le script ci-dessous recalcule une note CVSS v3.1 pour un constat web simple. Il reprend les métriques de base, applique la formule de la spécification, puis sort la note arrondie vers le haut à une décimale avec une implémentation conforme à l’appendice de la spécification et la qualification associée. Ici, le vecteur complet de l’exemple aboutit à 9,8, ce qui permet de documenter proprement le rapport au lieu d’inventer une gravité « au feeling »."},{"type":"text","content":"Prérequis de démonstration : vérifie d’abord « node --version ». Cet extrait n’utilise que JavaScript de base. Si Node.js manque ou si la commande échoue, mets-le à jour avant de continuer."},{"type":"code","content":"function roundUp1(decimal) {\n  const entier = Math.round(decimal * 100000);\n  if (entier % 10000 === 0) {\n    return entier / 100000;\n  }\n  return (Math.floor(entier / 10000) + 1) / 10;\n}\n\nfunction cvss31(vector) {\n  const AV = { N: 0.85, A: 0.62, L: 0.55, P: 0.2 };\n  const AC = { L: 0.77, H: 0.44 };\n  const UI = { N: 0.85, R: 0.62 };\n  const C = { H: 0.56, L: 0.22, N: 0 };\n  const I = { H: 0.56, L: 0.22, N: 0 };\n  const A = { H: 0.56, L: 0.22, N: 0 };\n  const S = vector.S;\n  const PR = S === \"U\" ? { N: 0.85, L: 0.62, H: 0.27 } : { N: 0.85, L: 0.68, H: 0.5 };\n  const iss = 1 - (1 - C[vector.C]) * (1 - I[vector.I]) * (1 - A[vector.A]);\n  const impact = S === \"U\" ? 6.42 * iss : 7.52 * (iss - 0.029) - 3.25 * Math.pow(iss - 0.02, 15);\n  const exploit = 8.22 * AV[vector.AV] * AC[vector.AC] * PR[vector.PR] * UI[vector.UI];\n  const base = impact <= 0 ? 0 : (S === \"U\" ? roundUp1(Math.min(impact + exploit, 10)) : roundUp1(Math.min(1.08 * (impact + exploit), 10)));\n  const niveau = base === 0 ? \"aucune\" : base < 4 ? \"faible\" : base < 7 ? \"moyenne\" : base < 9 ? \"élevée\" : \"critique\";\n  return { score: base, niveau };\n}\n\nconst resultat = cvss31({ AV: \"N\", AC: \"L\", PR: \"N\", UI: \"N\", S: \"U\", C: \"H\", I: \"H\", A: \"H\" });\nconsole.log(resultat);\n# exemple de sortie (valeurs fictives)\n# { score: 9.8, niveau: ''critique'' }","language":"javascript"},{"type":"schema","content":"{\"v\":1,\"kind\":\"cards\",\"title\":\"Prioriser sans se limiter à CVSS\",\"columns\":2,\"items\":[{\"term\":\"Gravité technique\",\"text\":\"score et vecteur\",\"icon\":\"gauge\",\"tone\":\"cyan\"},{\"term\":\"Exposition\",\"text\":\"Internet, interne, rôle nécessaire, fréquence\",\"icon\":\"globe\",\"tone\":\"red\"},{\"term\":\"Actif concerné\",\"text\":\"paiement, comptes, données, back-office\",\"icon\":\"database\",\"tone\":\"violet\"},{\"term\":\"Exploitabilité\",\"text\":\"simple ou non, automatisable ou non\",\"icon\":\"zap\",\"tone\":\"amber\"},{\"term\":\"Correctif\",\"text\":\"disponible, testé, contournement provisoire ou non\",\"icon\":\"wrench\",\"tone\":\"green\"}]}"},{"type":"text","content":"Le CVSS aide à exprimer une gravité technique commune, mais il ne résume pas ton risque métier. Le rapport doit donc préciser la portée réelle : Internet ou intranet, compte standard ou compte d’administration, données sensibles ou fonction secondaire, exploitation simple ou non, correctif disponible ou pas. Il doit aussi séparer le fait, l’hypothèse et le faux positif éventuel. Un faux positif documenté ne disparaît pas du rapport d’équipe interne : il nourrit le réglage des outils et évite de refaire la même erreur au prochain audit."},{"type":"example","content":"Exemple corrigé : observation brute, « Ama voit un bouton d’export et reçoit un CSV ». Constat complet, « Contrôle d’accès défaillant sur « /admin/export » : le compte standard Ama obtient 200 sur la route d’export et reçoit un fichier CSV alors que la matrice de rôles limite cette fonction à l’administrateur. Catégorie : OWASP Top 10:2025 A01, CWE-862. Impact : export non autorisé de données. Preuve : requête GET, réponse 200, extrait d’en-tête et taille du fichier. Recommandation : vérification de rôle côté serveur et test automatisé de refus. Re-test : le compte standard doit recevoir 403, le compte administrateur 200. »"},{"type":"callout","content":"Erreurs fréquentes : remplir un rapport avec des slogans ; oublier la preuve reproductible ; publier des données sensibles dans le résumé exécutif ; donner une note CVSS sans vecteur ; annoncer un correctif sans dire comment le vérifier ensuite."},{"type":"callout","content":"Sécurité : un rapport d’audit peut circuler loin. Sépare donc les détails sensibles du résumé large, applique le besoin d’en connaître, et évite de recopier des secrets, jetons ou données personnelles dans les parties qui n’en ont pas besoin."},{"type":"callout","content":"À retenir : un bon rapport transforme une observation en décision de correction. Il doit être compris par la direction, rejoué par les développeurs et vérifié au re-test. CVSS structure la gravité technique, mais le contexte d’exposition et l’action de correction restent essentiels."},{"type":"callout","content":"Pour pratiquer : Travaille dans « Projet final : auditer l’application de réservation et rédiger le rapport » : transforme chaque observation en constat complet, calcule la note utile, prépare le re-test, puis termine par le quiz."},{"type":"resource","content":"FIRST : spécification CVSS v3.1 (en anglais)","url":"https://www.first.org/cvss/v3.1/specification-document"},{"type":"resource","content":"FIRST : calculateur CVSS v3.1 (en anglais)","url":"https://www.first.org/cvss/calculator/3.1"},{"type":"resource","content":"OWASP Top 10:2025 : A01, contrôle d’accès défaillant (en anglais)","url":"https://top10.owasp.org/2025/A01_2025-Broken_Access_Control/"},{"type":"resource","content":"OWASP : le guide de test de sécurité web (WSTG) (en anglais)","url":"https://owasp.org/www-project-web-security-testing-guide/"},{"type":"resource","content":"CWE : la liste des faiblesses logicielles (en anglais)","url":"https://cwe.mitre.org/"}]}'::jsonb, 26, 30, 3)
