  ('3405e549-1d40-bc17-2efa-4a89d3d9e751', '40abe0c4-0341-1c25-adee-8292a16408cf', '014933f4-4c0b-c7cd-bff2-02fa5109ba11', '375df27a-a6f0-4ece-a112-6c3fa81228fd', 'Quiz : configuration, secrets et erreurs', 70, 1),
