  ('63a55706-59ca-c57d-af3e-1d07cf4e09b4', '492b4d0d-2ca1-4aaf-d37f-51fb6161d9ff', 1, 'Le certificat a une date d’expiration explicite à surveiller', true),
  ('f63a2546-8e8c-f03c-cda3-588abad323ed', '492b4d0d-2ca1-4aaf-d37f-51fb6161d9ff', 2, 'HSTS demande au navigateur de rester en HTTPS après une première visite réussie en HTTPS', true),
