  ('17e00927-db9b-4b0a-f81c-96e002ddc4bb', 'd727b8a3-fddc-65fa-9207-02d02b01d943', 1, 'Parce qu’un navigateur refuse toute requête vers un autre site', false),
  ('329623f7-ce30-f070-b70c-2fe63e77a758', 'd727b8a3-fddc-65fa-9207-02d02b01d943', 2, 'Parce qu’un navigateur peut encore envoyer certaines requêtes inter-origines, mais pas laisser le script lire librement la réponse', true),
  ('1158117d-1d1e-e0e8-87e5-21d2cd1af513', 'd727b8a3-fddc-65fa-9207-02d02b01d943', 3, 'Parce qu’un site tiers ne peut jamais charger d’image', false),
  ('3a9564c1-5cf4-a9f2-233e-78a06facaedf', 'd727b8a3-fddc-65fa-9207-02d02b01d943', 4, 'Parce qu’elle chiffre les cookies côté client', false),
  ('0ee110f5-9d25-bfdc-25e1-3847fbf344f4', '3e17a1b0-b19f-a0cd-bae3-fa097aad8c8a', 1, 'Le port différent suffit à changer l’origine', true),
  ('9fccfbd6-74dc-3a13-529e-fbe4bb49d287', '3e17a1b0-b19f-a0cd-bae3-fa097aad8c8a', 2, 'Elles restent de même origine car le nom d’hôte est identique', false),
  ('9b288f61-9b8b-7932-c0f0-57e771d8c1fe', '3e17a1b0-b19f-a0cd-bae3-fa097aad8c8a', 3, 'Le schéma est identique dans les deux cas', true),
