  ('fcac2e7e-0ddc-f330-8ea2-b37f5edc9384', '4c269e47-1aa2-50c7-2137-96f7a508aa42', 2, 'Commencer par la lecture seule et la cartographie', true),
  ('ac378ee5-3810-f885-3553-5f29aa0ed5d8', '4c269e47-1aa2-50c7-2137-96f7a508aa42', 3, 'Désactiver les journaux pour aller plus vite', false),
  ('2c1c26a3-f0fd-e6dd-3c43-5e7284c929e1', '4c269e47-1aa2-50c7-2137-96f7a508aa42', 4, 'Créer d’abord de nouveaux comptes administrateurs', false),
  ('128e2c9b-cb03-f5fb-0890-6d8ae9c61b6f', 'ae9a4c31-2be5-bad6-4edf-ef73ea9b27e4', 1, 'Parce qu’un scanner ne produit jamais aucun résultat utile', false),
  ('703960aa-4389-f6ae-c9f0-449c4d36ce59', 'ae9a4c31-2be5-bad6-4edf-ef73ea9b27e4', 2, 'Parce qu’il peut produire des faux positifs ou manquer le contexte', true),
