  ('794f48fc-d095-c6ea-0f59-d4b94cfb9943', 'ae9a4c31-2be5-bad6-4edf-ef73ea9b27e4', 4, 'Parce qu’il supprime les journaux', false),
  ('c59c5fa1-355f-6979-0e87-e50faa3b7032', 'd2be0384-3979-b13a-3489-1bff320ac15e', 1, 'La note contient un horaire et un compte de test utiles', true),
  ('095b769e-3adb-1776-c875-00299d567432', 'd2be0384-3979-b13a-3489-1bff320ac15e', 2, 'Elle relie une requête, une réponse et une matrice métier', true),
  ('3bcb6c7d-341b-dfe6-d627-d66c9ad01b18', 'd2be0384-3979-b13a-3489-1bff320ac15e', 3, 'La route est forcément protégée correctement', false),
  ('85de08ef-efba-6714-fb92-1c24a36ec31b', 'd2be0384-3979-b13a-3489-1bff320ac15e', 4, 'La note est plus rejouable qu’un simple “ça semble risqué”', true),
