  ('3406a59b-36dd-b93a-2da2-9f0028adb7f2', '6c4b44c3-832e-61e1-fa88-104665ef07ab', 4, 'Un nom de machine plus court', false),
  ('42df3614-1460-5914-463b-ec7c9d8ae4e3', 'e230bd37-65f2-6bde-3e48-5133ff6476c4', 1, 'Parce que le score seul ne montre pas comment il a été obtenu', true),
  ('dd3059c4-19d9-7c6f-abfa-c0875182aab0', 'e230bd37-65f2-6bde-3e48-5133ff6476c4', 2, 'Parce qu’un score sans vecteur devient automatiquement faux', false),
  ('d55c716a-3ba3-da5f-3df2-b445df30329a', 'e230bd37-65f2-6bde-3e48-5133ff6476c4', 3, 'Parce que le vecteur remplace la preuve technique', false),
  ('40a7a39e-756a-8f23-1f20-105e1b0bcee5', 'e230bd37-65f2-6bde-3e48-5133ff6476c4', 4, 'Parce qu’il supprime le besoin de recommandation', false),
  ('16c3df0d-e7e3-1a18-0287-62831870c7cb', 'a7a45831-530f-a129-76b6-e2cceb888e74', 1, 'La preuve reproductible de la requête et de la réponse', true),
  ('427f7810-77c8-f3ed-52fe-8cb4d017947f', 'a7a45831-530f-a129-76b6-e2cceb888e74', 2, 'La catégorie OWASP ou CWE pertinente', true),
  ('ab1f6b30-e7bb-fe2f-9fe9-e6fc097c966a', 'a7a45831-530f-a129-76b6-e2cceb888e74', 3, 'Une recommandation de correction testable', true),
  ('90ca02b3-a41a-b581-2600-81d04c5eac86', 'a7a45831-530f-a129-76b6-e2cceb888e74', 4, 'L’accusation d’un développeur nommé', false),
  ('9dab36dc-9a00-5ebf-1574-e4b8ed33f34a', '3e154cec-3ce5-9f9f-f69a-4e840c1e6168', 1, 'Vrai', false),
