insert into public.labs (id, slug, title, description, category, difficulty, xp_reward, objectives, hints, terminal_lines, position, course_id, format, briefing, constraints, tools, requires_computer, is_assessment, estimated_minutes) values
  ('4db9f43c-9fb5-ee9e-df35-22051e0dddc3', 'tp-web-http', 'TP 1 : lire HTTP, cookies et en-têtes de sécurité', 'Tu lis des échanges HTTP, des cookies, des en-têtes de réponse et un certificat pour reconnaître les réglages utiles, repérer les écarts évidents et vérifier ce qui reste exposé.', 'securite', 'debutant', 130, array['Lire une requête et une réponse HTTP/1.1 sans perdre le contexte', 'Juger des attributs d’un cookie et convertir un Max-Age en minutes ou en jours', 'Comparer les noms d’hôtes vus dans les échanges avec les SAN d’un certificat', 'Reconnaître les en-têtes de sécurité utiles et ceux qui divulguent trop d’information']::text[], array['Commence par séparer les fichiers selon leur rôle : échanges, cookies, certificat, en-têtes.', 'Pour les cookies, lis toujours la ligne entière avant de conclure qu’un attribut manque.', 'Pour le certificat, compare les SAN au nom d’hôte exact utilisé par la requête, pas au chemin.', 'Pour un maximum ou un comptage, vérifie qu’il n’y a pas d’égalité avant de répondre.']::text[], '{}'::text[], 800, '40abe0c4-0341-1c25-adee-8292a16408cf', 'logs', 'Le lundi 4 mai 2026, Kader Sow a capturé plusieurs échanges de l’application de réservation de l’Hôtel Palmier d’Or avec un client HTTP en mode verbeux. Il a aussi exporté une liste de cookies observés, quelques en-têtes de réponse et un extrait de certificat TLS. Tu joues l’apprenti analyste qui doit lire ces preuves sans outil spécialisé, compter ce qui est correct, noter ce qui manque et vérifier qu’un nom d’hôte est bien couvert par le certificat. Les données sont fictives, mais leur forme imite des sorties réelles. Pour le calcul des jours restants du certificat principal, considère que la date du jour est le 4 mai 2026.', array['Tu analyses uniquement des fichiers fournis ; ne teste jamais un système réel sans autorisation écrite.', 'Les réponses doivent venir des fichiers du labo et du guide, pas d’une supposition sur ce que ferait un vrai navigateur.']::text[], array['Visionneuse du site', 'Git Bash, WSL ou Termux pour grep, cut, sort et awk', 'PowerShell 5.1 si tu travailles sur Windows']::text[], false, false, 45),
  ('943b8b9a-2d4b-1792-a3eb-b891d4ddf5a0', 'tp-web-injection', 'TP 2 : injections : reconnaître, comprendre et corriger', 'Tu relies un journal d’accès web, un journal SQL et un extrait de code Express pour distinguer une recherche légitime d’une injection, retrouver la route fautive et choisir une correction défendable.', 'securite', 'intermediaire', 140, array['Reconnaître un motif d’injection une fois la chaîne de requête décodée', 'Relier une ligne d’accès web à son appel SQL par identifiant de suivi', 'Lire du code Express pour distinguer concaténation, paramétrage et appel shell', 'Choisir une correction qui traite la cause et pas seulement le symptôme']::text[], array['Le guide donne la liste exacte des motifs à compter ; n’invente pas une définition plus large.', 'Une apostrophe légitime dans un nom propre ne suffit pas à classer une ligne comme injection.', 'Le journal SQL montre soit des paramètres liés, soit le SQL tel qu’il arrive à la base.', 'Pour un maximum, vérifie qu’il n’y a pas d’ex æquo avant de conclure.']::text[], '{}'::text[], 810, '40abe0c4-0341-1c25-adee-8292a16408cf', 'logs', 'Le mardi 5 mai 2026, Kader Sow voit passer un trafic inhabituel sur l’application de réservation de l’Hôtel Palmier d’Or. Il exporte le journal d’accès nginx, le journal SQL de l’application et un extrait du code des routes Express. Ton rôle est de distinguer le bruit normal, les recherches légitimes et les vraies tentatives d’injection, puis de juger ce que le code permet encore. Les horodatages des fichiers sont en UTC. Tu analyses uniquement ces fichiers fournis ; ne teste jamais un vrai site sans autorisation écrite.', array['Tu travailles uniquement sur des fichiers fournis et fictifs.', 'Les exemples d’injection visibles dans les journaux sont des cas d’école défensifs ; ne les réutilise jamais contre un site réel.', 'Tous les horodatages des fichiers sont en UTC : ne change pas de fuseau avant de comparer.']::text[], array['Visionneuse du site', 'Git Bash, WSL ou Termux pour grep, sort et uniq', 'PowerShell 5.1 avec Get-Content -Encoding UTF8 sur Windows']::text[], false, false, 55),
  ('1903f4c5-e240-9c3a-8042-ca88944a5ac9', 'tp-web-xss-csp', 'TP 3 : XSS, CSP et en-têtes : évaluer une politique', 'Tu relis des gabarits, des politiques CSP, des rapports de violation et un tableau d’en-têtes pour repérer des sorties fragiles, juger des politiques de défense en profondeur et noter des pages de l’application de réservation.', 'securite', 'intermediaire', 145, array['Distinguer une sortie échappée d’une sortie brute selon le contexte HTML', 'Lire une CSP et comprendre le repli de default-src', 'Trier des rapports de violation par directive, origine et fichier source', 'Évaluer rapidement la couverture des en-têtes de protection']::text[], array['Commence par classer chaque extrait de gabarit par contexte avant de compter.', 'Quand une directive manque, vérifie si default-src la remplace avant de conclure.', 'Pour un maximum, groupe puis vérifie qu’il n’y a pas d’ex æquo.', 'La meilleure politique est celle qui couvre les besoins révélés par les rapports sans rouvrir inutilement les scripts en ligne.']::text[], '{}'::text[], 820, '40abe0c4-0341-1c25-adee-8292a16408cf', 'logs', 'Le mercredi 6 mai 2026, l’Hôtel Palmier d’Or veut publier une politique CSP sur « reservation.palmier-or.example ». Kader Sow exporte douze extraits de gabarits, six politiques candidates, un lot de rapports de violation collectés en mode essai, un tableau d’en-têtes HTTP et le texte exact d’un script en ligne encore présent sur une page. Ton rôle est de séparer les sorties dangereuses des sorties correctement encadrées, puis de choisir une politique qui couvre les besoins réels sans ouvrir trop large. Tu dois aussi noter les en-têtes en place sur dix pages et vérifier l’empreinte du script encore autorisé. Tu analyses uniquement des fichiers fournis ; ne teste jamais un site réel sans autorisation écrite.', array['Tu travailles uniquement sur les fichiers fournis.', 'Les politiques et rapports du TP 3 sont fictifs, mais leurs directives et champs gardent une forme réaliste.']::text[], array['Visionneuse du site', 'Git Bash, WSL ou Termux pour grep, awk, sort, uniq et openssl', 'PowerShell 5.1 pour lire UTF-8, filtrer un CSV et calculer une empreinte']::text[], false, false, 55),
  ('37a116c2-ddeb-94a9-9e00-58920074fbff', 'tp-web-sessions-jwt', 'TP 4 : sessions, jetons JWT et mots de passe', 'Tu contrôles des jetons JWT, un journal de sessions et un export d’empreintes de mots de passe pour vérifier si l’API partenaire et le portail de réservation appliquent bien la politique de l’Hôtel Palmier d’Or.', 'securite', 'intermediaire', 145, array['Relire la structure d’un JWT et contrôler ses champs utiles avant d’en tirer une conclusion', 'Détecter une mauvaise gestion de session dans un journal chronologique', 'Comparer des formats d’empreintes de mots de passe à une politique écrite', 'Proposer un correctif qui réduit vraiment le risque au lieu de déplacer le problème']::text[], array['Pour un JWT, relis séparément l’algorithme annoncé, la charge utile, la durée de validité et l’audience.', 'Pour une session, groupe d’abord les lignes par identifiant, puis regarde l’ordre connexion, requêtes, déconnexion et expiration.', 'Pour les empreintes, un préfixe ou un paramètre numérique change complètement le verdict de conformité.', 'Quand la politique définit un ordre de faiblesse, applique-le avant de chercher un seul compte gagnant.']::text[], '{}'::text[], 830, '40abe0c4-0341-1c25-adee-8292a16408cf', 'logs', 'Le jeudi 7 mai 2026, juste avant d’ouvrir une API aux partenaires, Kader Sow demande un contrôle ciblé des jetons émis, des sessions web et du stockage des mots de passe. Tu travailles sur cinq fichiers exportés en lecture seule : des jetons JWT, un journal de cycle de vie de session, un export d’empreintes stockées, la politique interne et un guide de méthode. Pour ce TP, la référence temporelle pour la validité des jetons est le jeudi 7 mai 2026 à 09:00:00 UTC. Le secret d’essai « secret-d-exemple » sert uniquement à vérifier les signatures de cet exercice. Tout est fictif ; tu analyses seulement les fichiers fournis.', array['Tu analyses uniquement des fichiers fournis ; ne teste jamais un système réel sans autorisation écrite.', 'Quand une question parle de validité, utilise seulement la référence temporelle donnée dans le briefing et la politique du fichier fourni.']::text[], array['Visionneuse du site', 'Git Bash, WSL ou Termux pour couper, compter et trier', 'PowerShell 5.1 pour filtrer et relire les fichiers UTF-8 sous Windows', 'OpenSSL ou l’HMAC de PowerShell pour vérifier une signature d’exemple']::text[], false, false, 55),
  ('25dfbe51-b6c9-2393-8e07-477a4e2beece', 'tp-web-acces-api', 'TP 5 : contrôle d’accès, API et SSRF dans les journaux', 'Tu relies un journal d’API, une matrice de droits et un journal de sorties réseau pour repérer des lectures d’objets d’un autre compte, des appels de fonctions interdites, un jeton trop bavard et des aperçus qui partent vers l’intérieur du réseau.', 'securite', 'intermediaire', 145, array['Comparer une requête réelle à la route logique définie dans une matrice de droits', 'Distinguer un contrôle de propriété absent d’un simple problème d’identifiant prévisible', 'Mesurer un débit par minute pour repérer un jeton qui martèle l’API', 'Reconnaître dans un journal sortant les adresses privées, locales et de lien local utiles au SSRF']::text[], array['Commence par ramener chaque chemin à sa route logique, sinon tu mélangeras les objets et la règle générale.', 'Quand la matrice dit « propriétaire requis », compare toujours l’utilisateur du jeton au propriétaire de l’objet avant de conclure.', 'Pour une série séquentielle, trie les identifiants et vérifie d’abord s’ils se suivent sans trou.', 'Pour le SSRF, lis la destination demandée, pas seulement la route appelante de l’aperçu.']::text[], '{}'::text[], 840, '40abe0c4-0341-1c25-adee-8292a16408cf', 'logs', 'Le vendredi 8 mai 2026, l’Hôtel Palmier d’Or vient d’ouvrir son API de réservation à une application mobile. Kader Sow veut vérifier que la passerelle applique bien les droits prévus avant l’audit de la semaine suivante. Il t’envoie le journal JSON de l’API, la matrice des droits et le journal des requêtes sortantes déclenchées par la fonction d’aperçu d’URL. Ton rôle est de comparer ce que la matrice autorise avec ce qui a réellement réussi, puis de repérer si la fonction d’aperçu ouvre la voie à du SSRF. Tout se résout sur les fichiers fournis : tu n’attaques aucun système réel.', array['Tu analyses uniquement des fichiers fournis ; ne teste jamais un système réel sans autorisation écrite.', 'Les horodatages sont déjà en UTC et les réponses attendues se déduisent des fichiers, pas d’une connaissance externe.']::text[], array['Visionneuse du site', 'Git Bash, WSL ou Termux pour grep, awk, sort, uniq et wc', 'PowerShell 5.1 avec Get-Content -Encoding UTF8, Import-Csv, Group-Object et Measure-Object']::text[], false, false, 55),
  ('df8d5da2-9664-8b97-bc8c-23e99fe7966f', 'tp-web-config-cvss', 'TP 6 : configuration, dépendances et notation CVSS', 'Tu audites la configuration nginx, tu repères ce qui est publiquement exposé à la racine du site, tu compares les versions de dépendances et tu classes les avis avec CVSS 3.1 avant l’audit final.', 'securite', 'intermediaire', 150, array['Relire une configuration nginx comme une liste de contrôles simples', 'Distinguer un fichier public normal d’un artefact qui ne doit jamais être exposé', 'Comparer une version installée à une plage SemVer touchée puis à une version corrigée', 'Calculer une note CVSS 3.1 et en déduire la qualification utile à la priorisation']::text[], array['Compte les défauts en suivant la liste de contrôle du guide, sans inventer d’autres critères.', 'Dans la racine du site, le statut HTTP compte autant que le nom du fichier.', 'Pour les dépendances, commence par relier chaque avis au paquet installé avant de trier quoi que ce soit.', 'Pour CVSS 3.1, remplace d’abord chaque métrique par sa valeur numérique, puis arrondis au dixième supérieur.']::text[], '{}'::text[], 850, '40abe0c4-0341-1c25-adee-8292a16408cf', 'logs', 'Nous sommes le lundi 11 mai 2026. Kader Sow veut un dernier contrôle rapide avant l’audit final de l’application de réservation de l’Hôtel Palmier d’Or. Il te remet la configuration nginx actuelle, la liste de ce qui répond encore à la racine du site, la liste des dépendances Node.js installées et un export d’avis de sécurité fictifs. Ton rôle est de compter les défauts visibles, de voir ce qui ne devrait jamais être public, puis d’identifier les composants vulnérables. Tu termines en calculant et en classant les gravités avec CVSS 3.1, sans toucher un système réel.', array['Tu analyses uniquement des fichiers fournis ; ne teste jamais un système réel sans autorisation écrite.', 'Les horodatages et les versions de ce TP sont figés au 11 mai 2026.', 'Les réponses sur CVSS 3.1 se calculent avec la formule donnée dans le guide, sans outil externe.']::text[], array['Visionneuse du site', 'Git Bash, WSL ou Termux pour grep, sort -V et awk', 'PowerShell 5.1 pour Select-String, Import-Csv et les comparaisons de versions', 'Papier, crayon ou tableur pour poser un calcul CVSS']::text[], false, false, 55),
  ('1b051777-0a06-51bc-de49-0ccc97a055f3', 'projet-web-audit', 'Projet final : auditer l’application de réservation et rédiger le rapport', 'Tu relies les exports d’un audit web, qualifies les constats, recalcules les notes CVSS et justifies une priorisation défendable sans toucher à un système réel.', 'securite', 'avance', 200, array['Rattacher un constat à la bonne famille OWASP 2025 à partir des preuves', 'Recalculer des notes CVSS 3.1 et une priorité numérique sans approximation', 'Distinguer un faux positif scanner d’un risque confirmé par le code, TLS ou le journal', 'Préparer une recommandation immédiate et un début de rapport qui restent strictement factuels']::text[], array['Commence par la lettre de mission et la grille avant d’ouvrir les constats.', 'Pour les notes et priorités, recopie d’abord toutes les valeurs intermédiaires au brouillon.', 'Un signal scanner peut être contredit par un en-tête ou une version déjà corrigée.', 'Le journal d’accès sert à dater un fait observé, pas à deviner une hypothèse absente des traces.']::text[], '{}'::text[], 860, '40abe0c4-0341-1c25-adee-8292a16408cf', 'logs', 'Le mardi 12 mai 2026, l’Hôtel Palmier d’Or te demande une relecture finale de l’application de réservation avant l’ouverture de la haute saison. Kader Sow a déjà exporté la lettre de mission, les en-têtes de plusieurs pages, un extrait du code Express, la liste des dépendances, un extrait d’avis de sécurité, une synthèse TLS et un journal d’accès. Il a aussi préparé une grille interne pour la qualification, le calcul CVSS 3.1 et la priorité des corrections. Ton rôle est de distinguer les constats confirmés des faux positifs, de noter proprement ce qui doit être corrigé et de préparer les premiers éléments du rapport. Tu analyses uniquement des fichiers fournis ; ne teste jamais un système réel sans autorisation écrite.', array['Tu travailles seulement sur les exports fournis et tu ne lances aucun scan ni aucune requête vers un service réel.', 'Quand tu annonces une priorité, tu appliques seulement la formule et les valeurs de la grille d’évaluation.']::text[], array['Visionneuse CyberPingo pour lire les réponses HTTP, le code et les journaux', 'Git Bash, WSL ou Termux pour filtrer des lignes avec grep, cut, awk ou sort', 'Windows PowerShell 5.1 avec Get-Content -Encoding UTF8, Select-String et Import-Csv']::text[], false, true, 95)
insert into public.lab_tasks (id, lab_id, position, prompt, hint, answer_format) values
  ('154aff05-6e92-a37c-f5f4-2470e72f5f80', '4db9f43c-9fb5-ee9e-df35-22051e0dddc3', 1, 'Dans « swb-tp1-echanges.http », combien de réponses HTTP sont de la famille 3xx ?', 'Lis la ligne d’état de chaque réponse et compte seulement celles qui commencent par un code 3.', 'Un nombre entier'),
  ('3d507a7a-56b0-15ab-8907-e5c8951a913c', '4db9f43c-9fb5-ee9e-df35-22051e0dddc3', 2, 'Après la connexion dans « swb-tp1-echanges.http », quel chemin exact la réponse renvoie-t-elle dans l’en-tête « Location » ?', 'Repère la requête POST de connexion, puis lis l’en-tête « Location » de sa réponse.', 'Un chemin web exact, commençant par /'),
  ('77ad9890-36cf-2b2c-282e-10d6666d8a06', '4db9f43c-9fb5-ee9e-df35-22051e0dddc3', 3, 'Combien de requêtes de « swb-tp1-echanges.http » sont encore envoyées en clair sur HTTP et non sur HTTPS ?', 'Appuie-toi sur la ligne « URL: » de chaque échange et compte celles qui commencent par « http:// ».', 'Un nombre entier'),
  ('5751bd29-27c7-0c7d-6615-83d37c76b156', '4db9f43c-9fb5-ee9e-df35-22051e0dddc3', 4, 'Parmi les cookies de « swb-tp1-cookies.txt » qui n’ont pas l’attribut « HttpOnly », quel nom de cookie a la valeur « Max-Age » la plus grande, sans ex æquo ?', 'Écarte d’abord les cookies dont la ligne contient « HttpOnly », puis compare les « Max-Age » des cookies restants : ce sont des nombres de secondes.', 'Un nom de cookie exact, en minuscules'),
  ('171b8f29-08d3-4c9a-b4ff-a007d4ab98c2', '4db9f43c-9fb5-ee9e-df35-22051e0dddc3', 5, 'Combien de cookies de « swb-tp1-cookies.txt » n’ont pas l’attribut « Secure » ?', 'Lis chaque ligne « Set-Cookie » et compte celles qui ne contiennent pas le mot « Secure ».', 'Un nombre entier'),
  ('3e3774f0-f9b2-068f-ce02-20afd615ceea', '4db9f43c-9fb5-ee9e-df35-22051e0dddc3', 6, 'Quel cookie de « swb-tp1-cookies.txt » est invalide parce qu’il annonce « SameSite=None » sans « Secure » ?', 'Cherche d’abord « SameSite=None », puis vérifie que la même ligne ne contient pas « Secure ».', 'Un nom de cookie exact, en minuscules'),
  ('a3d656f2-532b-a873-dcf1-73e37698e361', '4db9f43c-9fb5-ee9e-df35-22051e0dddc3', 7, 'Quelle est, en minutes, la durée de vie du cookie de session dans « swb-tp1-cookies.txt » ?', 'Repère le cookie de session, lis son « Max-Age » en secondes puis convertis-le en minutes.', 'Un nombre entier de minutes'),
  ('7c236219-a089-55f6-194e-0edfc6d95454', '4db9f43c-9fb5-ee9e-df35-22051e0dddc3', 8, 'Dans « swb-tp1-certificat.txt », combien de jours restent-ils avant la date « notAfter » du certificat principal si l’on se place au 4 mai 2026 ?', 'Utilise le bloc du certificat principal seulement, lis « notAfter » puis calcule un nombre entier de jours en UTC.', 'Un nombre entier de jours'),
  ('aa7e86f8-c5a4-0cf9-f201-9d058e50b1b1', '4db9f43c-9fb5-ee9e-df35-22051e0dddc3', 9, 'Quel nom d’hôte est utilisé dans « swb-tp1-echanges.http » mais n’apparaît pas dans les SAN du certificat principal de « swb-tp1-certificat.txt » ?', 'Liste les valeurs du champ « Host » vues dans les échanges, puis compare-les exactement à la liste des SAN du certificat principal.', 'Un nom d’hôte exact'),
  ('499df9fa-b224-da18-48aa-6aca18804c5b', '4db9f43c-9fb5-ee9e-df35-22051e0dddc3', 10, 'Dans « swb-tp1-en-tetes.txt », combien de jours représente la valeur « max-age » de l’en-tête HSTS ?', 'Lis la valeur « max-age » en secondes, puis convertis-la en jours avec un diviseur de 86400.', 'Un nombre entier de jours'),
  ('cd99495f-73e6-ac6b-b3e9-46f3fbf69da3', '4db9f43c-9fb5-ee9e-df35-22051e0dddc3', 11, 'Toujours dans « swb-tp1-en-tetes.txt », l’en-tête HSTS inclut-il l’option « includeSubDomains » ? Réponds par « oui » ou « non ».', 'Reste sur la même ligne HSTS et réponds seulement sur la présence ou l’absence littérale de l’option.', 'Réponds par oui ou non'),
  ('acf7af3e-c625-1b94-0367-0df690a8251e', '4db9f43c-9fb5-ee9e-df35-22051e0dddc3', 12, 'Combien de pages de « swb-tp1-en-tetes.txt » n’ont pas d’en-tête « Content-Security-Policy » ?', 'Considère chaque bloc de page comme une unité, puis compte ceux où aucune ligne ne commence par « Content-Security-Policy: ».', 'Un nombre entier'),
  ('4ef97427-a571-bb62-7e2c-10bfe5ce27f6', '4db9f43c-9fb5-ee9e-df35-22051e0dddc3', 13, 'Quelle page de « swb-tp1-en-tetes.txt » divulgue une version précise dans l’en-tête « Server » ?', 'Repère la seule ligne « Server » qui contient un slash suivi de chiffres, puis relève la page du même bloc.', 'Un chemin web exact, commençant par /'),
  ('5b4ad48d-b375-6e9d-9aa5-01ef17fe8f72', '4db9f43c-9fb5-ee9e-df35-22051e0dddc3', 14, 'Quel en-tête sert le mieux à empêcher l’intégration d’une page dans un cadre ? Réponds par une lettre. a) Referrer-Policy b) X-Content-Type-Options c) X-Frame-Options d) Server', 'Cherche l’en-tête dont le rôle concerne les cadres et l’intégration de page, pas le type MIME ni le référent.', 'Une seule lettre'),
  ('12eba43f-1f5e-2971-d99c-3c869c38f5f7', '4db9f43c-9fb5-ee9e-df35-22051e0dddc3', 15, 'Quelle affirmation sur le cookie de session est exacte ? Réponds par une lettre. a) il est stocké sans Max-Age et dépend donc de la fermeture du navigateur b) il porte HttpOnly, Secure et SameSite=Lax c) il utilise SameSite=None sans Secure d) il n’a ni Path ni Max-Age', 'Relis uniquement la ligne du cookie de session et compare-la mot à mot aux quatre propositions.', 'Une seule lettre'),
  ('48c38e37-9307-b50e-fb91-b4b40d41c886', '943b8b9a-2d4b-1792-a3eb-b891d4ddf5a0', 1, 'Dans « swb-tp2-appli.js », quel est le chemin exact de la route de recherche de chambres qui construit son SQL par concaténation ?', 'Cherche la route GET qui lit un paramètre de recherche puis fabrique une chaîne SQL avec des guillemets autour de la donnée.', 'Un chemin web exact qui commence par /'),
  ('7c0c5ada-273d-dd30-208a-a7482a8a4561', '943b8b9a-2d4b-1792-a3eb-b891d4ddf5a0', 2, 'Dans « swb-tp2-acces.log », combien d’appels ont une chaîne de requête décodée (la partie de l’URL après le « ? », sur toutes les routes) qui contient l’un des motifs d’injection listés par le guide ?', 'Extrais d’abord l’URL, décode la chaîne de requête (pourcentages et signes « + »), passe en minuscules puis teste seulement la liste de motifs donnée par le guide.', 'Un nombre entier'),
  ('a960a22e-7b45-fed4-9d4e-e32a06655865', '943b8b9a-2d4b-1792-a3eb-b891d4ddf5a0', 3, 'Quelle adresse IP envoie le plus d’appels classés comme tentative d’injection dans « swb-tp2-acces.log », sans ex æquo ?', 'Une fois les tentatives isolées, groupe-les par colonne source du journal nginx puis garde le seul maximum.', 'Une adresse IPv4'),
  ('29d6c7b7-5683-c3b3-3b15-8cc55a33d141', '943b8b9a-2d4b-1792-a3eb-b891d4ddf5a0', 4, 'Quelle est l’heure UTC la plus ancienne d’une tentative d’injection dans « swb-tp2-acces.log » ?', 'Trie mentalement ou avec un outil les tentatives par horodatage nginx, puis garde celle qui arrive le plus tôt à la seconde près.', 'Une heure UTC au format HH:MM:SS'),
  ('5dff7b7b-3050-bf22-587c-c86c2b6aecd9', '943b8b9a-2d4b-1792-a3eb-b891d4ddf5a0', 5, 'Parmi ces tentatives d’injection, combien reçoivent un code HTTP 500 dans « swb-tp2-acces.log » ?', 'Reste sur le sous-ensemble isolé à la question précédente, puis lis seulement la zone du code HTTP.', 'Un nombre entier'),
  ('5e2f3975-487a-fc04-6df4-a089b0b7df3f', '943b8b9a-2d4b-1792-a3eb-b891d4ddf5a0', 6, 'Quelle est la taille en octets du plus gros retour parmi les tentatives d’injection de « swb-tp2-acces.log » ?', 'Isole les tentatives, puis compare la taille envoyée en fin de ligne. Vérifie qu’un seul retour occupe le maximum.', 'Un nombre entier d’octets'),
  ('f555c837-5a77-79de-4d50-4f5171017d9d', '943b8b9a-2d4b-1792-a3eb-b891d4ddf5a0', 7, 'Quelle adresse IP a reçu ce plus gros retour d’injection dans « swb-tp2-acces.log » ?', 'Pars de la ligne qui porte la taille maximale, puis relis seulement la colonne source de cette ligne.', 'Une adresse IPv4'),
  ('53ef8f4f-7051-3b31-acb3-ad42cea85d0d', '943b8b9a-2d4b-1792-a3eb-b891d4ddf5a0', 8, 'En reliant cette ligne à « swb-tp2-requetes-sql.log » par l’identifiant de suivi, combien de lignes la base renvoie-t-elle ?', 'Recopie l’identifiant de suivi de la ligne d’accès retenue, retrouve-le dans le journal SQL puis lis le champ « rows ».', 'Un nombre entier'),
  ('5d1b64e4-6c1f-43ce-23bb-d631375a67ee', '943b8b9a-2d4b-1792-a3eb-b891d4ddf5a0', 9, 'Dans « swb-tp2-requetes-sql.log », quel nom de table apparaît dans la tentative qui emploie « UNION SELECT » ?', 'Repère la tentative « UNION SELECT », puis lis le nom de table juste derrière le mot « FROM » dans la partie injectée.', 'Un nom de table en minuscules'),
  ('36df6b42-9c04-e672-d726-37f4a87a65f9', '943b8b9a-2d4b-1792-a3eb-b891d4ddf5a0', 10, 'Dans « swb-tp2-appli.js », quel est le chemin exact de la route qui appelle un shell avec une valeur reçue concaténée ?', 'Cherche l’appel à « exec », puis remonte à la déclaration de route qui lui passe une valeur issue de l’appel HTTP.', 'Un chemin web exact qui commence par /'),
  ('efeac50c-977b-f34f-94c8-5946a198d5e9', '943b8b9a-2d4b-1792-a3eb-b891d4ddf5a0', 11, 'Dans « swb-tp2-requetes-sql.log », combien d’appels de la route « /connexion » montrent un contournement d’authentification, c’est-à-dire un SQL journalisé qui contient la condition toujours vraie « OR ''1''=''1'' » ou « OR 1=1 » (majuscules ou minuscules) ?', 'Garde seulement les lignes de la route « /connexion », puis compte celles dont le SQL contient « OR ''1''=''1'' » ou « OR 1=1 ».', 'Un nombre entier'),
  ('49600a74-a6de-b09d-a91d-3cf1dea6a93c', '943b8b9a-2d4b-1792-a3eb-b891d4ddf5a0', 12, 'Quel compte est ainsi ouvert par ces contournements de connexion dans « swb-tp2-requetes-sql.log » ?', 'Sur ces lignes de connexion, lis le champ qui indique quel utilisateur est renvoyé par l’appel SQL.', 'Un identifiant de compte en minuscules'),
  ('41ab155f-0453-db10-b5b9-26484877902a', '943b8b9a-2d4b-1792-a3eb-b891d4ddf5a0', 13, 'Dans « swb-tp2-appli.js » et « swb-tp2-requetes-sql.log », quel utilisateur de base SQL emploie l’application ?', 'Le nom apparaît dans la configuration du code et il est confirmé par chaque ligne du journal SQL.', 'Un identifiant SQL en minuscules'),
  ('3551ee89-490d-51f6-49e3-330134b9f397', '943b8b9a-2d4b-1792-a3eb-b891d4ddf5a0', 14, 'Pourquoi ce compte SQL n’est-il pas un bon exemple de moindre privilège ? Réponds par une lettre. a) Parce qu’un compte de lecture seule ne doit jamais apparaître dans les journaux. b) Parce qu’un compte trop large peut lire ou modifier plus d’infos qu’une route vulnérable ne devrait atteindre. c) Parce que le moindre privilège impose de changer d’utilisateur SQL à chaque appel. d) Parce qu’un compte SQL ne doit jamais se trouver dans le code.', 'Le principe du moindre privilège parle de droits minimaux nécessaires, pas d’invisibilité, ni de rotation à chaque requête.', 'Une seule lettre'),
  ('46237853-652e-92d4-9eb7-abd00942d46a', '943b8b9a-2d4b-1792-a3eb-b891d4ddf5a0', 15, 'Quelle correction traite correctement la recherche vulnérable ? Réponds par une lettre. a) Supprimer toutes les apostrophes des saisies. b) Refuser tout appel qui contient le mot « select ». c) Utiliser une instruction SQL paramétrée et valider les valeurs non paramétrables par liste autorisée. d) Garder la concaténation mais placer un WAF devant l’application.', 'Cherche la mesure qui sépare vraiment code et infos au lieu de seulement filtrer quelques signes ou mots.', 'Une seule lettre'),
  ('1ef68b78-419d-eae1-4951-2548d0bf4231', '1903f4c5-e240-9c3a-8042-ca88944a5ac9', 1, 'Dans « swb-tp3-gabarits.txt », combien d’extraits utilisent une sortie brute « <%- ... %> » ?', 'Compte seulement les extraits qui affichent une sortie brute, quel que soit leur contexte.', 'Un nombre entier'),
  ('595ec25e-7ba2-0e28-1874-dd22606469d9', '1903f4c5-e240-9c3a-8042-ca88944a5ac9', 2, 'Quel identifiant de gabarit montre une donnée brute dans un attribut HTML sans guillemets ?', 'Cherche l’unique ligne dans laquelle une valeur brute arrive dans un attribut non entouré de guillemets.', 'Un identifiant de gabarit, par exemple G01'),
  ('d1c42aef-a846-a19e-6e7a-b7de49307c13', '1903f4c5-e240-9c3a-8042-ca88944a5ac9', 3, 'Quel identifiant de gabarit insère directement une donnée dans un bloc « <script> » classique ?', 'Ne retiens que l’extrait dans lequel la valeur arrive dans du JavaScript brut au sein d’un bloc script.', 'Un identifiant de gabarit, par exemple G01'),
  ('a604549e-9369-33ae-8eee-6db330ab418c', '1903f4c5-e240-9c3a-8042-ca88944a5ac9', 4, 'Dans « swb-tp3-politiques.txt », quelle politique laisse encore passer les scripts en ligne car elle contient « unsafe-inline », y compris si cette permission vient du repli sur « default-src » ?', 'Cherche « unsafe-inline », puis vérifie si la permission vise bien les scripts, même quand script-src manque.', 'Un identifiant de politique, par exemple P2'),
  ('83ea2ba3-e813-7d9c-97bb-2b79500a8034', '1903f4c5-e240-9c3a-8042-ca88944a5ac9', 5, 'Quelle politique candidate utilise un nonce pour autoriser des scripts en ligne choisis ?', 'Repère la seule politique qui contient une source de la forme « nonce-... » dans sa directive de scripts.', 'Un identifiant de politique, par exemple P2'),
  ('5ff79ab3-752d-5488-ef50-9c09553157ac', '1903f4c5-e240-9c3a-8042-ca88944a5ac9', 6, 'Quelle politique ne contient ni « object-src » ni « base-uri » ?', 'Relis les six politiques ligne par ligne et cherche celle qui omet ces deux directives en même temps.', 'Un identifiant de politique, par exemple P2'),
  ('4c900732-27be-8ad0-2d80-05844cf59598', '1903f4c5-e240-9c3a-8042-ca88944a5ac9', 7, 'Dans « swb-tp3-rapports.jsonl », quelle « violated-directive » revient le plus souvent, sans ex æquo ?', 'Groupe les rapports par valeur exacte de « violated-directive », puis trie les totaux.', 'Le nom exact d’une directive'),
  ('24f94c29-823a-519f-a98c-1d9fef52e8a6', '1903f4c5-e240-9c3a-8042-ca88944a5ac9', 8, 'Quelle origine bloquée revient le plus souvent dans « swb-tp3-rapports.jsonl », sans ex æquo ?', 'Lis le champ « blocked-uri », puis compte les origines identiques avant de trier.', 'Une origine ou une URL d’origine exacte'),
  ('5842e320-1db7-609a-ca09-d97d26519531', '1903f4c5-e240-9c3a-8042-ca88944a5ac9', 9, 'Dans « swb-tp3-rapports.jsonl », une violation de script en ligne est un rapport dont « blocked-uri » vaut « inline » et dont « violated-directive » commence par « script-src ». Combien de valeurs distinctes de « source-file » apparaissent dans ces violations ?', 'Garde les rapports qui remplissent les deux conditions (« blocked-uri » égal à « inline » et nom de directive violée qui commence par « script-src », quel que soit le suffixe), puis compte les valeurs distinctes de « source-file ».', 'Un nombre entier'),
  ('02c95f21-59ad-7210-2833-f531a7715fa9', '1903f4c5-e240-9c3a-8042-ca88944a5ac9', 10, 'En appliquant la grille du guide sur « swb-tp3-en-tetes.csv », quel est le total de points cumulés par les dix pages ?', 'Calcule d’abord le score page par page, puis additionne les dix scores sans oublier HSTS et Permissions-Policy.', 'Un nombre entier de points'),
  ('3e57f29a-3676-8b67-4b3b-568f6e8956c3', '1903f4c5-e240-9c3a-8042-ca88944a5ac9', 11, 'Quelle page est la moins bien notée dans « swb-tp3-en-tetes.csv », sans ex æquo ?', 'Applique la même grille que pour la question précédente et garde la page au score le plus faible.', 'Un chemin de page exact'),
  ('81fc8d2d-98ca-70bc-e450-7279062aa63c', '1903f4c5-e240-9c3a-8042-ca88944a5ac9', 12, 'Combien de pages du tableau « swb-tp3-en-tetes.csv » n’ont pas « X-Content-Type-Options: nosniff » ?', 'Parcours seulement la colonne « x_content_type_options », puis compte les cellules vides ou différentes de « nosniff ».', 'Un nombre entier'),
  ('01d44a2d-b202-3472-517a-c955e78f4083', '1903f4c5-e240-9c3a-8042-ca88944a5ac9', 13, 'Quelle est l’empreinte SHA-256, encodée en Base64, du contenu de « swb-tp3-script-en-ligne.txt » ? Ce fichier contient exactement le texte du script en ligne, retour à la ligne final compris.', 'Calcule l’empreinte du fichier tel quel, sans rien ajouter ni retirer, puis fournis la valeur Base64 avec ou sans le préfixe « sha256- » attendu par la CSP.', 'Une empreinte Base64, avec ou sans le préfixe sha256-'),
  ('49ade3dd-099f-f1fc-fb46-ecb73669d1fb', '1903f4c5-e240-9c3a-8042-ca88944a5ac9', 14, 'Le script en ligne de « swb-tp3-script-en-ligne.txt » doit continuer à fonctionner sur la page. Quelle politique de « swb-tp3-politiques.txt » prévoit un moyen précis d’autoriser ce script en ligne sans « unsafe-inline », tout en gardant « object-src », « base-uri » et « frame-ancestors » ? Réponds par une lettre. a) P2 b) P3 c) P4 d) P6', 'Écarte d’abord la politique qui contient « unsafe-inline », puis cherche celle qui prévoit un moyen précis d’autoriser un script en ligne (le nonce doit alors être repris dans la balise du script), et vérifie enfin qu’elle garde les trois directives demandées.', 'Une seule lettre'),
  ('d33f89ad-d533-74ea-4807-1d531c342d57', '1903f4c5-e240-9c3a-8042-ca88944a5ac9', 15, 'Quelle première phase de déploiement est la plus sûre pour une nouvelle CSP sur cette application ? Réponds par une lettre. a) activer tout de suite le blocage sur toutes les pages b) commencer en mode Report-Only puis vérifier les rapports c) supprimer d’abord tous les en-têtes existants d) autoriser temporairement toutes les sources externes', 'Choisis l’étape qui permet de mesurer les effets réels sans casser l’application au premier essai.', 'Une seule lettre'),
  ('a0b890b1-6082-3efc-5b4b-4761c9a73b46', '37a116c2-ddeb-94a9-9e00-58920074fbff', 1, 'Dans « swb-tp4-jetons.txt », quel est le champ « sub » du jeton J07 ?', 'Découpe le JWT en trois parties, décode seulement la charge utile en base64url et lis le champ demandé.', 'Un identifiant exact en minuscules'),
  ('bf582ada-9538-6a72-de3e-7b68d6e934ed', '37a116c2-ddeb-94a9-9e00-58920074fbff', 2, 'Dans « swb-tp4-jetons.txt », quel jeton annonce l’algorithme « none » ? Écris seulement son identifiant, par exemple « J01 ».', 'Lis l’en-tête de chaque JWT ; l’algorithme annoncé est dans le champ « alg ».', 'Un identifiant de jeton au format JNN'),
  ('b92068aa-f403-167c-7782-5ec80ae867b5', '37a116c2-ddeb-94a9-9e00-58920074fbff', 3, 'En prenant comme « maintenant » le 2026-05-07T09:00:00Z, combien de jetons de « swb-tp4-jetons.txt » sont expirés ? Un jeton est expiré dès que son « exp » est antérieur ou égal à cet instant.', 'Compare la valeur « exp » de chaque charge utile à l’instant de référence : « exp » est un nombre de secondes depuis le 1er janvier 1970 UTC, et un jeton expiré ne doit plus être accepté.', 'Un nombre entier'),
  ('703c75b8-31cd-9e6a-7c6e-ba143f7199d8', '37a116c2-ddeb-94a9-9e00-58920074fbff', 4, 'Dans « swb-tp4-jetons.txt », quel jeton porte le rôle « admin » ? Écris seulement son identifiant.', 'Le rôle est dans la charge utile ; groupe d’abord les champs importants de chaque jeton avant de conclure.', 'Un identifiant de jeton au format JNN'),
  ('c0bab6f6-5a05-92e2-202a-be686f46fc73', '37a116c2-ddeb-94a9-9e00-58920074fbff', 5, 'Combien de jetons de « swb-tp4-jetons.txt » n’ont pas pour audience attendue « partenaire-resa-api » ?', 'L’audience se lit dans le champ « aud » ; compare-la exactement à celle annoncée par la politique.', 'Un nombre entier'),
  ('e85f9bf7-9318-1e9e-64a7-f94ea2ca7e08', '37a116c2-ddeb-94a9-9e00-58920074fbff', 6, 'Selon la politique interne, combien de jetons de « swb-tp4-jetons.txt » dépassent la durée maximale autorisée ?', 'Calcule la durée de chaque jeton avec « exp - iat », puis compare-la à la limite écrite dans la politique.', 'Un nombre entier'),
  ('e9c7b26f-66f9-7cc0-f02b-edbee70b3ef9', '37a116c2-ddeb-94a9-9e00-58920074fbff', 7, 'Combien de jetons HS256 de « swb-tp4-jetons.txt » ne valident pas leur signature HMAC avec le secret d’essai du TP ?', 'Recalcule la signature sur « en-tête.charge » seulement pour les jetons annoncés en HS256, puis compare-la à la troisième partie.', 'Un nombre entier'),
  ('a75b1c2f-07ac-a5a3-4d51-4f53a4c85444', '37a116c2-ddeb-94a9-9e00-58920074fbff', 8, 'Dans « swb-tp4-sessions.log », combien de sessions distinctes servent encore une requête acceptée après un événement « logout » ?', 'Groupe les lignes par identifiant de session, repère « logout », puis cherche s’il existe une requête « accepted » plus tard sur le même identifiant.', 'Un nombre entier'),
  ('23e3fe39-975e-1805-9e40-3dc79fba3d1c', '37a116c2-ddeb-94a9-9e00-58920074fbff', 9, 'Dans « swb-tp4-sessions.log », combien de connexions gardent le même identifiant de session avant et après « login » ?', 'Lis les événements « login » et compare « session_id » à « rotated_to » ; la politique dit que l’identifiant doit changer.', 'Un nombre entier'),
  ('8d7b651a-9add-5003-c5f6-26d80cfc105b', '37a116c2-ddeb-94a9-9e00-58920074fbff', 10, 'Selon la politique interne, combien de requêtes acceptées de « swb-tp4-sessions.log » arrivent après une inactivité strictement supérieure à la limite autorisée ?', 'Trie les événements par session puis mesure l’écart entre deux lignes successives d’un même identifiant avant de regarder la décision.', 'Un nombre entier'),
  ('6edaeb84-2318-8ac6-f47f-0aaf0ca1933a', '37a116c2-ddeb-94a9-9e00-58920074fbff', 11, 'Dans « swb-tp4-empreintes.csv », quel algorithme protège le compte « msylla » ?', 'Repère le préfixe de l’empreinte du compte demandé avant de lire le reste de la ligne.', 'L’un des formats attendus par la politique, en minuscules'),
  ('cba9f4c8-bdc0-7920-3543-31f533ac348a', '37a116c2-ddeb-94a9-9e00-58920074fbff', 12, 'Selon la politique interne, combien de comptes de « swb-tp4-empreintes.csv » ont un stockage de mot de passe non conforme ?', 'Commence par classer chaque ligne en « conforme » ou « non conforme » selon le format et ses paramètres, puis compte seulement les non conformes.', 'Un nombre entier'),
  ('eb40ce0f-e9b5-706f-23a5-e9bbf695c770', '37a116c2-ddeb-94a9-9e00-58920074fbff', 13, 'Selon l’ordre de faiblesse écrit dans la politique interne, quel compte de « swb-tp4-empreintes.csv » a le stockage le plus faible, sans ex æquo ?', 'Applique l’ordre du plus faible au plus robuste de la politique avant de chercher un seul gagnant.', 'Un identifiant de compte en minuscules'),
  ('ae5bc9fc-e3cd-f1fe-6e69-54e004fb631c', '37a116c2-ddeb-94a9-9e00-58920074fbff', 14, 'Quel correctif réduit le mieux la fixation de session ? Réponds par une lettre. a) allonger la durée du cookie de session b) recopier l’identifiant de session dans l’URL c) régénérer l’identifiant de session après la connexion et lors d’un changement de privilège d) garder le même identifiant si l’adresse source ne change pas', 'Cherche la mesure qui casse le lien entre la session anonyme reçue avant connexion et la session authentifiée.', 'Une seule lettre'),
  ('dbab840c-6bac-e4a5-c706-a6ec2ff2c7a1', '37a116c2-ddeb-94a9-9e00-58920074fbff', 15, 'Quel choix limite le mieux l’impact d’un JWT volé avant sa date d’expiration ? Réponds par une lettre. a) prolonger encore sa durée de validité b) utiliser des jetons courts avec une révocation ou une version de session côté serveur c) supprimer le champ « exp » pour éviter les rejets d’horloge d) stocker le jeton dans un paramètre d’URL', 'Cherche la mesure qui réduit la fenêtre d’abus et qui permet de couper un jeton compromis avant son échéance naturelle.', 'Une seule lettre'),
  ('e627a09e-b5b9-04fb-b111-eb1534713483', '25dfbe51-b6c9-2393-8e07-477a4e2beece', 1, 'Dans « swb-tp5-api.jsonl », combien de requêtes ont réussi avec le code 200 alors que la matrice de « swb-tp5-droits.csv » exige le propriétaire de l’objet et que l’utilisateur du jeton n’est pas ce propriétaire ?', 'Applique d’abord la matrice par route logique, puis compare seulement les lignes où « propriétaire requis » vaut oui.', 'Un nombre entier'),
  ('323d7b76-1a4c-64cb-4a15-4d1c4c62cbb3', '25dfbe51-b6c9-2393-8e07-477a4e2beece', 2, 'Quel utilisateur cumule le plus de succès 200 sur des objets qui ne lui appartiennent pas, parmi les routes où la matrice exige le propriétaire ?', 'Compte les violations de propriété par utilisateur après avoir appliqué la matrice, puis vérifie qu’il n’y a pas d’ex æquo.', 'Un identifiant utilisateur'),
  ('96ab8d18-61bd-c7a3-3e72-e75e8b23126c', '25dfbe51-b6c9-2393-8e07-477a4e2beece', 3, 'Pour l’utilisateur trouvé à la question 2, combien d’identifiants de réservation distincts lit-il avec succès dans la série « GET /api/reservations/{id} » qui ne lui appartient pas ?', 'Reste sur les lectures de réservations de cet utilisateur, garde seulement les succès 200 hors propriété, puis compte les identifiants distincts.', 'Un nombre entier'),
  ('4e8a8ca5-9649-f464-aa95-62d8541e3805', '25dfbe51-b6c9-2393-8e07-477a4e2beece', 4, 'Pour cette même série de réservations lues avec succès hors propriété, quel est le premier identifiant de réservation de la séquence croissante ?', 'Trie les identifiants de réservation de la série, puis lis la borne basse après avoir vérifié qu’ils se suivent.', 'Un identifiant numérique'),
  ('43ca4250-6cb9-f839-af73-63274554a93a', '25dfbe51-b6c9-2393-8e07-477a4e2beece', 5, 'Pour cette même série de réservations lues avec succès hors propriété, quel est le dernier identifiant de réservation de la séquence croissante ?', 'Utilise exactement le même ensemble que pour la question précédente, puis lis cette fois la borne haute.', 'Un identifiant numérique'),
  ('35e12d4a-a9e9-0f99-91f3-efe3176e8d3e', '25dfbe51-b6c9-2393-8e07-477a4e2beece', 6, 'Combien de requêtes avec le rôle « client » atteignent pourtant un code 200 sur des routes réservées au personnel dans « swb-tp5-api.jsonl » selon « swb-tp5-droits.csv » ?', 'Cherche les lignes où le rôle réel vaut « client », où la matrice n’autorise que le personnel, puis recompte seulement les succès 200.', 'Un nombre entier'),
  ('1c1e9218-29e1-4670-cb8e-c5096dd558ac', '25dfbe51-b6c9-2393-8e07-477a4e2beece', 7, 'Toutes causes confondues, combien de requêtes interdites par la matrice ont pourtant réussi avec le code 200 dans « swb-tp5-api.jsonl » ?', 'Additionne les succès 200 interdits par le rôle et ceux interdits par la propriété, mais compte chaque requête une seule fois.', 'Un nombre entier'),
  ('22ffd705-dda9-e2da-74b2-793ea83b99c1', '25dfbe51-b6c9-2393-8e07-477a4e2beece', 8, 'Dans « swb-tp5-sortant.log », combien de requêtes sortantes visent une adresse privée, locale ou de lien local ?', 'Repère la destination réelle demandée par l’aperçu, puis applique les plages privées ou locales rappelées dans le guide.', 'Un nombre entier'),
  ('51869e1c-2c53-265d-0d6f-46389e8a0e97', '25dfbe51-b6c9-2393-8e07-477a4e2beece', 9, 'Quel couple correspond à la première destination privée, locale ou de lien local appelée par la fonction d’aperçu dans « swb-tp5-sortant.log » ? Écris la réponse au format utilisateur,hôte, sans espace, avec l’adresse ou le nom d’hôte de la destination (sans schéma ni chemin).', 'Trie les lignes par heure, trouve la première destination sensible, puis relève ensemble l’identifiant de l’utilisateur à l’origine et l’hôte de cette destination.', 'Un identifiant utilisateur, une virgule, puis l’adresse ou le nom d’hôte de la destination, sans espace'),
  ('1b825ae0-0f6f-2745-f84a-d14a4a550aa1', '25dfbe51-b6c9-2393-8e07-477a4e2beece', 10, 'Combien de requêtes sortantes vers le service de métadonnées « 169.254.169.254 » reçoivent le code 200 dans « swb-tp5-sortant.log » ?', 'Filtre d’abord sur l’adresse du service de métadonnées, puis garde seulement les réponses 200.', 'Un nombre entier'),
  ('8d81d3b4-a5aa-fd96-e07e-fb57eeab9960', '25dfbe51-b6c9-2393-8e07-477a4e2beece', 11, 'Combien d’octets reviennent au total des réponses 200 du service de métadonnées dans « swb-tp5-sortant.log » ?', 'Reste sur le même sous-ensemble que pour la question précédente, puis additionne la colonne des octets.', 'Un nombre entier d’octets'),
  ('adb35785-434e-35fc-c546-ae996bf38a75', '25dfbe51-b6c9-2393-8e07-477a4e2beece', 12, 'Quel est le débit maximal observé pour un même jeton dans « swb-tp5-api.jsonl », en requêtes par minute ?', 'Coupe l’horodatage à la minute UTC, groupe par jeton et par minute, puis compare les totaux.', 'Un nombre entier'),
  ('bb9f657e-8de0-bf23-4609-3e5df7f6c613', '25dfbe51-b6c9-2393-8e07-477a4e2beece', 13, 'À quelle minute UTC ce débit maximal est-il atteint ? Réponds au format HH:MM.', 'Garde exactement le même regroupement que pour la question précédente, puis lis la minute associée au maximum unique.', 'Une heure UTC au format HH:MM'),
  ('f1bd3312-a02c-f576-b330-28605a60aeca', '25dfbe51-b6c9-2393-8e07-477a4e2beece', 14, 'Quelle correction traite correctement l’accès à l’objet d’un autre ? Réponds par une lettre. a) cacher l’identifiant dans le code JavaScript du client b) vérifier côté serveur que l’objet appartient à l’utilisateur avant de répondre c) remplacer les identifiants numériques par des UUID sans autre contrôle d) limiter l’affichage à l’application mobile', 'La bonne réponse renforce le contrôle d’accès côté serveur sur chaque requête, pas seulement la forme de l’identifiant.', 'Une seule lettre'),
  ('e0e62442-2b32-9017-5a6f-ba6de49b192b', '25dfbe51-b6c9-2393-8e07-477a4e2beece', 15, 'Quelle correction traite correctement le SSRF observé dans la fonction d’aperçu ? Réponds par une lettre. a) imposer une liste autorisée de destinations et refuser les adresses privées ou locales après résolution b) encoder l’URL en Base64 avant de l’appeler c) valider l’URL seulement dans le navigateur d) bloquer uniquement le mot « localhost » dans la chaîne', 'La bonne réponse contrôle la destination réelle côté serveur après résolution, pas seulement l’apparence du texte envoyé.', 'Une seule lettre'),
  ('e2357fc6-f5fd-2855-ee74-449d1b24eb7a', 'df8d5da2-9664-8b97-bc8c-23e99fe7966f', 1, 'Dans « swb-tp6-nginx.conf », combien de règles de la liste de contrôle du guide la configuration viole-t-elle ? Compte une règle une seule fois, même si plusieurs lignes la concernent, et ignore la règle sur les fichiers servis, qui ne concerne pas ce fichier.', 'Passe la liste de contrôle du guide règle par règle, et cherche pour chacune la ligne qui la viole ou l’en-tête qui manque.', 'Un nombre entier'),
  ('d07e5a64-4d91-842d-ef5f-fa256c3379e8', 'df8d5da2-9664-8b97-bc8c-23e99fe7966f', 2, 'Dans « swb-tp6-nginx.conf », quel est le numéro de ligne de la directive qui active le listage de répertoires ?', 'Cherche la directive exacte qui ouvre un index de dossier au lieu de renvoyer une erreur ou un fichier précis.', 'Un numéro de ligne entier'),
  ('ae916649-c666-1b72-44f2-9d44cbfdfd65', 'df8d5da2-9664-8b97-bc8c-23e99fe7966f', 3, 'Dans « swb-tp6-nginx.conf », quel est le numéro de ligne de la directive qui autorise encore TLS 1.0 et TLS 1.1 ?', 'Les anciennes versions de protocole sont déclarées sur la même ligne que les versions modernes.', 'Un numéro de ligne entier'),
  ('08c1b8db-7a8f-5baa-8912-cc80bbb137a5', 'df8d5da2-9664-8b97-bc8c-23e99fe7966f', 4, 'En comparant « swb-tp6-dependances.csv » et « swb-tp6-avis.csv », combien de paquets installés sont réellement touchés par au moins un avis ?', 'Compte les paquets distincts touchés, pas le nombre total d’avis ni le nombre de versions corrigées.', 'Un nombre entier'),
  ('4e48b2cf-6b19-c276-de37-a5adbcc67a12', 'df8d5da2-9664-8b97-bc8c-23e99fe7966f', 5, 'Dans « swb-tp6-avis.csv », quel est l’identifiant de l’avis qui touche l’application et dont la note de base CVSS 3.1 est la plus élevée, sans ex æquo ?', 'Écarte d’abord les avis qui ne touchent pas la version installée, puis calcule ou relis la note de chaque avis restant.', 'Un identifiant d’avis en minuscules'),
  ('5c31d8dc-81f9-d79d-322c-62b22975e82e', 'df8d5da2-9664-8b97-bc8c-23e99fe7966f', 6, 'Calcule la note de base CVSS 3.1 de l’avis « swb-adv-2026-006 » à partir du vecteur présent dans « swb-tp6-avis.csv ».', 'Remplace chaque métrique par sa valeur, calcule Impact et Exploitabilité, puis applique l’arrondi supérieur au dixième.', 'Une note CVSS 3.1 avec une décimale, avec virgule ou point'),
  ('80e05e54-8962-7f5f-a501-214abfeee0fe', 'df8d5da2-9664-8b97-bc8c-23e99fe7966f', 7, 'Quelle qualification correspond à la note de base CVSS 3.1 de l’avis « swb-adv-2026-009 », calculée d’après son vecteur dans « swb-tp6-avis.csv » ? Réponds par une lettre. a) faible b) moyenne c) élevée d) critique', 'Calcule la note à partir du vecteur de l’avis, sans te soucier de la version installée, puis place-la dans la bonne tranche de qualification du guide.', 'Une seule lettre'),
  ('4c848369-cd87-6030-3560-52ff5f15114a', 'df8d5da2-9664-8b97-bc8c-23e99fe7966f', 8, 'Combien d’avis critiques qui touchent réellement l’application vois-tu dans « swb-tp6-avis.csv » ?', 'Un avis critique a une note comprise entre 9,0 et 10,0, mais il doit aussi toucher une version installée.', 'Un nombre entier'),
  ('9e7b31b7-5414-a06c-cf15-862fb3709789', 'df8d5da2-9664-8b97-bc8c-23e99fe7966f', 9, 'Quel paquet installé impose un changement de version majeure pour atteindre la première version corrigée, d’après « swb-tp6-dependances.csv » et « swb-tp6-avis.csv » ?', 'Compare le premier nombre de la version installée à celui de la version corrigée pour chaque paquet touché.', 'Un nom de paquet en minuscules'),
  ('5ed70356-0113-f77d-5f3c-434f35188d68', 'df8d5da2-9664-8b97-bc8c-23e99fe7966f', 10, 'Pour le paquet « resafetch », quelle est la version minimale sûre à installer si tu veux couvrir tous les avis qui le touchent dans « swb-tp6-avis.csv » ?', 'Quand un même paquet a plusieurs avis, garde la version corrigée la plus haute qui couvre tous les cas.', 'Une version SemVer au format x.y.z'),
  ('6a8dcda5-7a9b-6d9c-5c56-3fa7bbae9641', 'df8d5da2-9664-8b97-bc8c-23e99fe7966f', 11, 'Combien d’avis de « swb-tp6-avis.csv » ne touchent pas l’application parce que la version installée est déjà corrigée dans « swb-tp6-dependances.csv » ?', 'Ne confonds pas « paquet absent » et « paquet présent mais déjà au-delà de la version corrigée ».', 'Un nombre entier'),
  ('e4c8cf43-f227-9fdb-64d1-110e5ccf6ba2', 'df8d5da2-9664-8b97-bc8c-23e99fe7966f', 12, 'Quel fichier de « swb-tp6-racine-site.txt » est le plus critique à exposer publiquement ? Réponds par une lettre. a) /robots.txt b) /assets/app.js c) /.env d) /security.txt', 'Cherche le fichier qui risque de livrer directement des secrets ou des paramètres sensibles, pas seulement un détail de fonctionnement.', 'Une seule lettre'),
  ('42c485d9-917e-df66-6742-07e3835f78cd', 'df8d5da2-9664-8b97-bc8c-23e99fe7966f', 13, 'Dans « swb-tp6-racine-site.txt », combien d’entrées répondent encore en 200 alors qu’elles appartiennent à la liste du guide des artefacts qui ne devraient jamais être publics ?', 'Applique uniquement la liste du guide, puis filtre les lignes qui répondent encore avec un statut 200.', 'Un nombre entier'),
  ('fa38478d-647d-9883-aa83-5e2bf1f568ac', 'df8d5da2-9664-8b97-bc8c-23e99fe7966f', 14, 'Quel ordre de correction est le plus défendable d’après les informations des fichiers ? Réponds par une lettre. a) trier les paquets par ordre alphabétique b) corriger d’abord les avis déjà sans impact local c) traiter d’abord les avis exploités et exposés sur Internet, puis le reste par gravité d) corriger seulement les avis notés exactement 10,0', 'Tiens compte à la fois de l’applicabilité, de l’exposition et de l’exploitation connue, pas d’un seul chiffre isolé.', 'Une seule lettre'),
  ('7d833cc5-0b2a-d2a4-d53a-f49195952397', 'df8d5da2-9664-8b97-bc8c-23e99fe7966f', 15, 'Que faut-il faire du fichier « /.env » encore accessible selon « swb-tp6-racine-site.txt » ? Réponds par une lettre. a) le laisser public mais retirer le lien du menu b) le renommer en « .env.old » c) le compresser dans une nouvelle archive d) retirer l’accès, faire tourner les secrets et vérifier les journaux', 'Un fichier sensible déjà exposé se traite comme une fuite potentielle, pas comme un simple problème d’ergonomie.', 'Une seule lettre'),
  ('bc57d170-f3b8-4bd4-59e2-befe67c97af1', '1b051777-0a06-51bc-de49-0ccc97a055f3', 1, 'Selon la grille d’évaluation, quel code OWASP 2025 convient au constat F01 de « swb-proj-constats.csv » en relisant « swb-proj-code.js » ?', 'Regarde si la donnée fournie par le client est interprétée comme du SQL au lieu d’être liée comme un paramètre.', 'Un code de a01 à a10, par exemple a09'),
  ('8b37b81f-f280-2a64-e83e-8900d76604c8', '1b051777-0a06-51bc-de49-0ccc97a055f3', 2, 'Selon la grille d’évaluation, quel code OWASP 2025 convient au constat F02 de « swb-proj-constats.csv » en relisant « swb-proj-code.js » ?', 'Observe comment le commentaire enregistré est réinjecté dans la page et demande-toi si le navigateur peut l’interpréter.', 'Un code de a01 à a10, par exemple a09'),
  ('984d8a60-1869-489f-f0a3-b887e19e0a9d', '1b051777-0a06-51bc-de49-0ccc97a055f3', 3, 'Selon la grille d’évaluation, quel code OWASP 2025 convient au constat F03 de « swb-proj-constats.csv » en relisant « swb-proj-code.js » ?', 'Vérifie si la route confirme la propriété de la réservation avant de renvoyer son détail.', 'Un code de a01 à a10, par exemple a09'),
  ('43dc7ee4-7270-eeb3-c1f0-0424cb47f867', '1b051777-0a06-51bc-de49-0ccc97a055f3', 4, 'Selon la grille d’évaluation, quel code OWASP 2025 convient au constat F04 de « swb-proj-constats.csv » en relisant « swb-proj-code.js » ?', 'Demande-toi quel pilier de l’authentification tombe si le secret qui signe la session est lisible dans le code.', 'Un code de a01 à a10, par exemple a09'),
  ('776fd52a-0b59-eb8a-a733-8837c97b5a2f', '1b051777-0a06-51bc-de49-0ccc97a055f3', 5, 'Selon la grille d’évaluation, quel code OWASP 2025 convient au constat F05 de « swb-proj-constats.csv » en relisant « swb-proj-code.js » ?', 'La route d’aperçu ouvre une URL choisie par le client : relis dans la grille où l’édition 2025 range ce type de requête émise par le serveur.', 'Un code de a01 à a10, par exemple a09'),
  ('a990f741-8339-50cb-5546-36753c385237', '1b051777-0a06-51bc-de49-0ccc97a055f3', 6, 'Selon la grille d’évaluation, quel code OWASP 2025 convient au constat F07 de « swb-proj-constats.csv » en croisant « swb-proj-dependances.csv » et « swb-proj-avis.csv » ?', 'Ce constat parle d’un composant tiers déjà exposé par un avis, pas d’une erreur de logique métier dans le code de l’hôtel.', 'Un code de a01 à a10, par exemple a09'),
  ('f84c9088-7ff4-e26e-9415-7f2d185b2b6b', '1b051777-0a06-51bc-de49-0ccc97a055f3', 7, 'Calcule la note CVSS 3.1 du constat F01 de « swb-proj-constats.csv » avec la formule de la grille d’évaluation.', 'Relève toutes les métriques du vecteur, calcule impact et exploitabilité, puis applique l’arrondi supérieur officiel.', 'Note à une décimale, avec point ou virgule'),
  ('1975932e-4222-3bd7-6c90-70af9cabad75', '1b051777-0a06-51bc-de49-0ccc97a055f3', 8, 'Calcule la note CVSS 3.1 du constat F05 de « swb-proj-constats.csv » avec la formule de la grille d’évaluation.', 'Fais attention à la portée modifiée : elle change à la fois le poids de PR et l’équation d’impact finale.', 'Note à une décimale, avec point ou virgule'),
  ('695932da-6cf8-e663-c14d-8cd287dbe9d6', '1b051777-0a06-51bc-de49-0ccc97a055f3', 9, 'Calcule la note CVSS 3.1 du constat F07 de « swb-proj-constats.csv » avec la formule de la grille d’évaluation.', 'Le vecteur vient de l’avis associé au paquet ; la note reste une note technique, pas encore la priorité métier.', 'Note à une décimale, avec point ou virgule'),
  ('91aab013-d90c-1dc7-97b6-3d4537aec02e', '1b051777-0a06-51bc-de49-0ccc97a055f3', 10, 'Calcule la priorité numérique du constat F01 de « swb-proj-constats.csv » avec la formule et l’échelle de certitude de la grille d’évaluation.', 'Multiplie la note de base par la criticité de l’actif, puis par la valeur de certitude associée à « démontrée ».', 'Nombre à une décimale, avec point ou virgule'),
  ('4ae7aebe-af45-5cef-2f6d-375011d1c98c', '1b051777-0a06-51bc-de49-0ccc97a055f3', 11, 'Calcule la priorité numérique du constat F05 de « swb-proj-constats.csv » avec la formule et l’échelle de certitude de la grille d’évaluation.', 'Ne saute pas la valeur de certitude : le même score CVSS peut produire une priorité différente selon le niveau de preuve.', 'Nombre à une décimale, avec point ou virgule'),
  ('c56285ca-37c4-abb3-02e2-06cc6e7e7046', '1b051777-0a06-51bc-de49-0ccc97a055f3', 12, 'Calcule la priorité numérique du constat F07 de « swb-proj-constats.csv » avec la formule et l’échelle de certitude de la grille d’évaluation.', 'Croise la note issue de l’avis, la criticité de l’actif et la valeur de « confirmée ».', 'Nombre à une décimale, avec point ou virgule'),
  ('78660fed-370a-8b44-f65f-de2badb794b3', '1b051777-0a06-51bc-de49-0ccc97a055f3', 13, 'Quel numéro de constat dois-tu traiter en premier d’après la priorité numérique (note de base × criticité × certitude) de chaque constat de « swb-proj-constats.csv » qui a un vecteur CVSS, selon la grille d’évaluation ?', 'Repère la priorité strictement la plus haute une fois tous les calculs terminés.', 'Numéro à deux chiffres, par exemple 03'),
  ('185074e6-9b5c-7ea1-6cac-ba334ff4e90d', '1b051777-0a06-51bc-de49-0ccc97a055f3', 14, 'Quel numéro de constat de « swb-proj-constats.csv » est un faux positif scanner quand tu recoupes avec « swb-proj-en-tetes.txt » ?', 'Lis la ligne du scanner, puis retourne vérifier l’en-tête précise sur la page concernée avant de conclure.', 'Numéro à deux chiffres, par exemple 08'),
  ('110b9171-4d63-3709-976e-25b9cd21640f', '1b051777-0a06-51bc-de49-0ccc97a055f3', 15, 'Quel numéro de constat de « swb-proj-constats.csv » a déjà été exploité avec succès d’après « swb-proj-journaux.log » ? Une simple tentative ne suffit pas : cherche des requêtes dont les réponses prouvent que l’attaque a réussi.', 'Une tentative bloquée ou en erreur n’est pas un succès : cherche un fait dans le journal qui transforme une faiblesse du code en action observée et réussie sur l’application.', 'Numéro à deux chiffres, par exemple 06'),
  ('3b935b0d-56ec-bc02-c2cb-3c9eaa2821f3', '1b051777-0a06-51bc-de49-0ccc97a055f3', 16, 'Dans « swb-proj-journaux.log », recopie l’heure UTC de la première requête qui exploite le constat trouvé à la question 15, et l’adresse IPv4 source de cette requête, séparées par une virgule.', 'Cherche dans le journal la toute première requête réussie qui met en place la faiblesse de ce constat, avant les appels qui s’en servent ensuite pour vérifier qu’elle fonctionne. Les autres attaques du journal ne concernent pas ce constat.', 'HH:MM:SS, IPv4'),
  ('49df8a3d-3933-e888-affa-f00e3cbcc4ce', '1b051777-0a06-51bc-de49-0ccc97a055f3', 17, 'Quelle faiblesse TLS est la plus grave dans « swb-proj-tls.txt » ? Réponds par la lettre. a) le certificat finit dans moins de trois mois b) le serveur accepte encore TLS 1.0 et TLS 1.1 c) la redirection HTTP vers HTTPS est permanente d) une suite moderne en TLS 1.3 est visible', 'Choisis l’option qui maintient une exposition technique réelle, pas une bonne pratique déjà respectée.', 'Une seule lettre'),
  ('ca7bc0d1-9aa8-507b-9a00-98b4e2ea640d', '1b051777-0a06-51bc-de49-0ccc97a055f3', 18, 'Quelle recommandation est la plus adaptée au constat F01 ? Réponds par la lettre. a) retirer les apostrophes des recherches b) cacher les messages d’erreur SQL sans toucher à la requête c) remplacer la concaténation par une requête paramétrée et limiter les droits du compte SQL d) conserver la route et compter sur le WAF', 'La bonne réponse traite la cause et diminue aussi l’impact si une autre injection restait possible.', 'Une seule lettre'),
  ('d64378d4-0896-521f-d4b7-de6f0f594b64', '1b051777-0a06-51bc-de49-0ccc97a055f3', 19, 'Dans « swb-proj-code.js », quel est le numéro de ligne du secret de signature codé en dur mentionné par le constat F04 ?', 'Cherche la constante qui contient une valeur de démonstration lisible et relève son numéro exact dans l’extrait.', 'Nombre entier')
insert into private.lab_task_keys (task_id, accepted, explanation) values
  ('154aff05-6e92-a37c-f5f4-2470e72f5f80', array['4']::text[], 'La famille 3xx regroupe les redirections. En parcourant les lignes d’état du fichier, on trouve 4 réponse(s) qui commencent par 3. Cette lecture doit se faire sur la ligne d’état entière, pas seulement sur le champ Location qui n’existe pas dans toutes les réponses.'),
  ('3d507a7a-56b0-15ab-8907-e5c8951a913c', array['/espace-client/tableau-de-bord']::text[], 'La redirection utile se lit dans la réponse au POST de connexion. L’en-tête « Location » renvoie ici vers /espace-client/tableau-de-bord. Relever ce chemin est une compétence de base pour suivre une navigation ou documenter un flux d’authentification.'),
  ('77ad9890-36cf-2b2c-282e-10d6666d8a06', array['3']::text[], 'Le fichier indique l’URL complète de chaque échange. En comptant les lignes qui commencent par « http:// », on obtient 3 requête(s) envoyée(s) en clair. Cette mesure sert à voir si des clients ou des ressources passent encore par le port 80 avant redirection.'),
  ('5751bd29-27c7-0c7d-6615-83d37c76b156', array['theme_pref']::text[], 'On garde seulement les lignes de cookie qui ne contiennent pas « HttpOnly », puis on compare leur « Max-Age », exprimé en secondes. Le plus grand est celui de theme_pref, sans ex æquo. Cette lecture croisée de deux attributs montre qu’il faut toujours lire la ligne entière d’un cookie avant de conclure.'),
  ('171b8f29-08d3-4c9a-b4ff-a007d4ab98c2', array['3']::text[], 'L’attribut « Secure » se voit directement dans chaque ligne. En comptant les cookies qui ne l’ont pas, on trouve 3. Ce comptage aide à repérer les valeurs qui pourraient encore être envoyées hors HTTPS si un client retombe sur du HTTP.'),
  ('3e3774f0-f9b2-068f-ce02-20afd615ceea', array['promo_guest']::text[], 'La règle utile est simple : « SameSite=None » exige aussi « Secure ». En relisant les lignes, le seul cookie qui viole cette règle est promo_guest. Il faut bien vérifier les deux attributs sur la même ligne avant de conclure.'),
  ('a3d656f2-532b-a873-dcf1-73e37698e361', array['90']::text[], 'La durée de vie se lit dans « Max-Age », qui s’exprime en secondes. Pour le cookie de session, la conversion donne 90 minute(s). Cette opération revient souvent quand on veut juger si une session est courte, moyenne ou trop longue pour son usage.'),
  ('7c236219-a089-55f6-194e-0edfc6d95454', array['60']::text[], 'Le calcul se fait entre la date de référence donnée par l’énoncé et la date « notAfter » du certificat principal. L’écart est de 60 jour(s). Cette lecture sert à prioriser un renouvellement avant qu’un certificat n’expire en production.'),
  ('aa7e86f8-c5a4-0cf9-f201-9d058e50b1b1', array['assets.palmier-or.example']::text[], 'La bonne méthode consiste à comparer les noms d’hôtes complets des requêtes avec les SAN du certificat principal, sans raccourci. Le nom vu dans les échanges mais absent des SAN est assets.palmier-or.example. Ce contrôle permet de repérer un risque d’erreur TLS même si le reste du certificat paraît correct.'),
  ('499df9fa-b224-da18-48aa-6aca18804c5b', array['365']::text[], 'L’en-tête HSTS exprime « max-age » en secondes. En le convertissant en jours, on obtient 365. Cette conversion évite de juger une durée de validité uniquement à l’œil sur une grande valeur numérique.'),
  ('cd99495f-73e6-ac6b-b3e9-46f3fbf69da3', array['oui']::text[], 'Ici, il ne faut pas interpréter : il suffit de lire la ligne HSTS et de vérifier si « includeSubDomains » y figure. C’est bien le cas, donc la réponse attendue est « oui ». Cette vérification compte, car la présence de cette option change la portée de la politique.'),
  ('acf7af3e-c625-1b94-0367-0df690a8251e', array['3']::text[], 'La question porte sur les pages entières, pas sur le nombre total de lignes d’en-têtes. En comptant les blocs qui ne contiennent aucune ligne « Content-Security-Policy: », on arrive à 3. Cette vue montre rapidement où la politique n’est pas encore appliquée.'),
  ('4ef97427-a571-bb62-7e2c-10bfe5ce27f6', array['/maintenance']::text[], 'Pour cette recherche, il faut viser la ligne « Server » qui révèle une version et non celles qui se contentent du nom du serveur. La page concernée est /maintenance. Repérer ce détail aide à inventorier les fuites d’information techniques sans leur accorder un poids qu’elles n’ont pas seules.'),
  ('5b4ad48d-b375-6e9d-9aa5-01ef17fe8f72', array['c']::text[], 'Parmi ces quatre propositions, l’en-tête qui sert à empêcher l’intégration d’une page dans un cadre est X-Frame-Options. La bonne lettre est donc c. Ce mécanisme historique reste facile à reconnaître, même si des politiques plus modernes peuvent compléter ou remplacer ce contrôle.'),
  ('12eba43f-1f5e-2971-d99c-3c869c38f5f7', array['b']::text[], 'La bonne réponse vient d’une comparaison littérale entre la ligne du cookie de session et les quatre propositions. La seule affirmation exacte est celle de la lettre b. Cette méthode évite d’inventer un comportement navigateur qui n’est pas écrit dans le fichier.'),
  ('48c38e37-9307-b50e-fb91-b4b40d41c886', array['/api/chambres/recherche']::text[], 'La bonne méthode consiste à lire la route de recherche, à repérer les variables issues de l’appel puis à contrôler si elles sont concaténées dans la chaîne SQL. Ici, la route attendue est /api/chambres/recherche car la valeur cherchée est insérée directement dans l’appel SQL au lieu de passer comme paramètre lié.'),
  ('7c0c5ada-273d-dd30-208a-a7482a8a4561', array['13']::text[], 'Le comptage correct commence par le décodage de la chaîne de requête, sinon « %27 » masque les apostrophes et les motifs restent invisibles. En appliquant strictement la liste du guide et rien d’autre, on trouve 13 tentative(s). Cette règle évite de compter les villes ou noms légitimes qui contiennent une apostrophe sans signaler une attaque.'),
  ('a960a22e-7b45-fed4-9d4e-e32a06655865', array['203.0.113.45']::text[], 'Une fois les seules tentatives d’injection isolées, il faut compter les lignes par adresse source. Le maximum unique revient à 203.0.113.45. Ce regroupement permet de séparer un bruit dispersé d’une source qui insiste davantage que les autres.'),
  ('29d6c7b7-5683-c3b3-3b15-8cc55a33d141', array['08:17:04', '8:17:04']::text[], 'Comme les horodatages du journal web sont tous en UTC, il suffit d’ordonner les tentatives retenues et de garder la plus ancienne. L’heure obtenue est 08:17:04. La précision à la seconde compte ici, car plusieurs essais rapprochés n’arrivent pas dans un ordre identique.'),
  ('5dff7b7b-3050-bf22-587c-c86c2b6aecd9', array['5']::text[], 'Le code 500 s’observe directement dans le journal nginx, sans relire le corps du retour. Parmi les tentatives retenues, 5 reçoivent ce code. Cette mesure aide à voir si l’application casse bruyamment ou si elle renvoie parfois un retour exploitable.'),
  ('5e2f3975-487a-fc04-6df4-a089b0b7df3f', array['19421']::text[], 'Le format nginx combined donne la taille du retour dans la colonne numérique qui suit le code HTTP. En comparant ce champ sur les seules tentatives, le plus gros retour vaut 19421 octets. Un volume beaucoup plus grand que les autres signale souvent un contenu anormalement riche ou une fuite d’infos.'),
  ('f555c837-5a77-79de-4d50-4f5171017d9d', array['198.51.100.77']::text[], 'La ligne qui porte la taille maximale garde aussi l’adresse source au commencement de la ligne. Cette adresse est 198.51.100.77. Associer le volume du retour à son émetteur aide à prioriser la source qui a obtenu le plus d’informations.'),
  ('53ef8f4f-7051-3b31-acb3-ad42cea85d0d', array['37']::text[], 'Le journal d’accès montre l’identifiant de suivi dans l’URL, et le journal SQL le reprend sur la ligne correspondante. Une fois la jointure faite proprement, le champ « rows » indique 37. Cette lecture prouve qu’il faut croiser les deux fichiers, pas seulement observer le volume HTTP.'),
  ('5d1b64e4-6c1f-43ce-23bb-d631375a67ee', array['clients_reservations']::text[], 'Une tentative « UNION SELECT » ajoute un second jeu de lignes à l’appel SQL d’origine. Dans la ligne correspondante du journal SQL, la table injectée derrière « FROM » est clients_reservations. Identifier cette table permet d’estimer quelles infos l’attaquant cherchait à lire.'),
  ('36df6b42-9c04-e672-d726-37f4a87a65f9', array['/admin/export']::text[], 'La route à relever est celle qui appelle un shell avec une chaîne construite à partir d’une valeur reçue. Ici, /admin/export concatène directement cette valeur avant l’appel à « exec ». Ce schéma expose une injection de commandes car la donnée n’est ni validée par liste autorisée ni passée comme argument séparé.'),
  ('efeac50c-977b-f34f-94c8-5946a198d5e9', array['3']::text[], 'Le journal SQL permet ici de voir le texte exact de l’appel SQL envoyé à la base. En restant sur les lignes de connexion et en comptant celles qui introduisent un contournement logique, on obtient 3. Cette lecture est plus fiable qu’un simple comptage des codes 302, car tous les 302 ne viennent pas forcément d’une injection.'),
  ('49600a74-a6de-b09d-a91d-3cf1dea6a93c', array['staff_reception']::text[], 'Le journal SQL conserve ici le compte retourné quand l’appel de connexion réussit. Les lignes de contournement ouvrent le compte staff_reception. C’est un bon rappel qu’une injection d’authentification ne crée pas un compte : elle réutilise souvent le premier enregistrement que la base accepte de renvoyer.'),
  ('41ab155f-0453-db10-b5b9-26484877902a', array['resa_app_admin']::text[], 'Le nom de l’utilisateur SQL se lit dans la configuration du code et dans le champ dédié du journal SQL. Ici, l’application utilise resa_app_admin. Relever ce compte permet ensuite de juger si ses droits sont trop larges pour une application web qui devrait se limiter à ce dont elle a vraiment besoin.'),
  ('3551ee89-490d-51f6-49e3-330134b9f397', array['b']::text[], 'La bonne réponse est la lettre b. Le moindre privilège consiste à limiter les droits accordés à chaque composant pour réduire l’impact d’une faille restante. Si une route injectable utilise un compte trop puissant, l’attaquant peut lire ou modifier bien plus que ce que la fonctionnalité légitime exige.'),
  ('46237853-652e-92d4-9eb7-abd00942d46a', array['c']::text[], 'La bonne réponse est la lettre c. Une instruction SQL paramétrée sépare le code SQL des infos et bloque le mécanisme lui-même de l’injection. Les autres choix restent fragiles : retirer des apostrophes casse des cas légitimes, filtrer un mot se contourne et un WAF peut renforcer la défense sans corriger la cause.'),
  ('1ef68b78-419d-eae1-4951-2548d0bf4231', array['6']::text[], 'Dans ce fichier, il faut simplement repérer chaque usage de « <%- ... %> », puis les additionner sans tenir compte du contexte. On en compte 6. Ce premier tri sert de base avant de juger quels usages sont vraiment dangereux selon l’endroit où la valeur est insérée.'),
  ('595ec25e-7ba2-0e28-1874-dd22606469d9', array['g04']::text[], 'L’extrait cherché est celui qui combine deux risques : une sortie brute et un attribut non entouré de guillemets. Dans ce lot, cet extrait est G04. Ce cas mérite une attention spéciale, car l’absence de guillemets agrandit encore la surface d’injection.'),
  ('d1c42aef-a846-a19e-6e7a-b7de49307c13', array['g05']::text[], 'Ici, il faut trouver la ligne où une donnée est concaténée dans un bloc script ordinaire. L’identifiant correct est G05. Insérer une valeur dans du JavaScript brut change le contexte d’échappement et demande une défense différente de celle du corps HTML.'),
  ('a604549e-9369-33ae-8eee-6db330ab418c', array['p3']::text[], 'Une politique autorise encore les scripts en ligne parce qu’elle contient « unsafe-inline » sur la directive pertinente, y compris via le repli de « default-src ». Ici, cette politique est P3. Le test ne consiste pas seulement à lire « script-src » : il faut aussi connaître la règle de repli de CSP.'),
  ('83ea2ba3-e813-7d9c-97bb-2b79500a8034', array['p4']::text[], 'La politique qui emploie un nonce montre un choix moderne de défense en profondeur pour les scripts en ligne. Dans ce lot, c’est P4. Un nonce n’ouvre pas tous les scripts en ligne : il autorise seulement ceux qui portent la bonne valeur générée par le serveur.'),
  ('5ff79ab3-752d-5488-ef50-9c09553157ac', array['p3']::text[], 'Certaines directives ne bloquent pas une attaque seules, mais elles ferment des surfaces utiles. La seule politique qui omet en même temps « object-src » et « base-uri » est P3. Il faut donc lire la politique en entier, pas seulement la partie sur les scripts.'),
  ('4c900732-27be-8ad0-2d80-05844cf59598', array['script-src-elem']::text[], 'Les rapports de violation permettent de mesurer ce que la politique bloque le plus souvent. En regroupant par « violated-directive », un seul maximum ressort : script-src-elem. Cette lecture aide à savoir quelle famille de ressources pose encore le plus de problèmes.'),
  ('24f94c29-823a-519f-a98c-1d9fef52e8a6', array['https://cdn-legacy.palmier-or.example']::text[], 'Le champ « blocked-uri » montre ce que le navigateur a refusé de charger. En regroupant les valeurs identiques, l’origine la plus fréquente est https://cdn-legacy.palmier-or.example. Ce résultat sert ensuite à juger si une politique candidate couvre bien les dépendances encore nécessaires.'),
  ('5842e320-1db7-609a-ca09-d97d26519531', array['4']::text[], 'Pour répondre, il faut isoler les violations qui concernent des scripts en ligne, puis dédoublonner le champ « source-file ». On obtient 4 fichier(s) distinct(s). Ce comptage aide à mesurer si le problème est concentré ou réparti sur plusieurs vues de l’application.'),
  ('02c95f21-59ad-7210-2833-f531a7715fa9', array['59']::text[], 'La grille du guide attribue des points pour six familles d’en-têtes. En notant les dix pages une par une puis en additionnant, on atteint 59 point(s). Cette méthode impose une relecture de chaque colonne au lieu de se contenter d’une impression générale.'),
  ('3e57f29a-3676-8b67-4b3b-568f6e8956c3', array['/admin/import']::text[], 'Une fois les scores calculés page par page, une seule page arrive en dernier. La page la moins bien notée est /admin/import. Identifier ce plus mauvais cas aide à cibler la première correction visible et mesurable.'),
  ('81fc8d2d-98ca-70bc-e450-7279062aa63c', array['3']::text[], 'La réponse vient d’un simple comptage dans la colonne « x_content_type_options ». 3 page(s) ne portent pas « nosniff ». Ce type de contrôle rapide est utile, car l’absence d’un en-tête simple peut rester invisible si l’on ne compte pas proprement.'),
  ('01d44a2d-b202-3472-517a-c955e78f4083', array['baua4/jeb2eo5brlneq9jvap+zdh63b9ctwcqhztgvk=', 'sha256-baua4/jeb2eo5brlneq9jvap+zdh63b9ctwcqhztgvk=']::text[], 'Pour une source CSP par empreinte, il faut hacher le script exact en SHA-256 puis encoder le résultat en Base64. La valeur attendue est bAua4/jEB2eO5brLneQ9jvap+Zdh63b9CTWCQhzTgVk=. L’empreinte doit correspondre octet pour octet au script : un seul caractère de différence, retour à la ligne compris, donne une autre empreinte et le navigateur bloque le script. Une politique qui cite l’empreinte d’une ancienne version du script ne l’autorise donc pas.'),
  ('49ade3dd-099f-f1fc-fb46-ecb73669d1fb', array['c']::text[], 'La politique de la lettre b rouvre tous les scripts en ligne avec « unsafe-inline ». Les lettres a et d gardent les directives de défense mais n’autorisent aucun script en ligne : la page cesserait de fonctionner. La politique de la lettre c autorise le script par un nonce, sans « unsafe-inline », et garde « object-src », « base-uri » et « frame-ancestors ». La bonne lettre est c.'),
  ('d33f89ad-d533-74ea-4807-1d531c342d57', array['b']::text[], 'La première étape la plus prudente consiste à observer les effets d’une politique en mode essai avant de bloquer. La bonne lettre est b. Ce choix limite le risque de coupure fonctionnelle tout en donnant des preuves concrètes à corriger.'),
  ('a0b890b1-6082-3efc-5b4b-4761c9a73b46', array['client-1188']::text[], 'Le champ « sub » se trouve dans la charge utile du JWT, pas dans sa signature. Une fois la partie centrale décodée, le jeton J07 désigne client-1188. Cette méthode évite de confondre le contenu lisible du jeton avec sa preuve d’intégrité.'),
  ('bf582ada-9538-6a72-de3e-7b68d6e934ed', array['j04']::text[], 'L’en-tête d’un JWT est la première partie encodée. En lisant le champ « alg » sur chaque jeton, un seul annonce « none » : J04. Un tel jeton doit être rejeté pour cette API.'),
  ('b92068aa-f403-167c-7782-5ec80ae867b5', array['3']::text[], 'La politique impose un instant de référence unique pour tout le TP. En comparant « exp » à 2026-05-07T09:00:00Z, on trouve 3 jeton(s) expiré(s). Ce calcul doit se faire sur chaque charge utile et non à l’œil.'),
  ('703c75b8-31cd-9e6a-7c6e-ba143f7199d8', array['j03']::text[], 'Le rôle est lisible dans la charge utile du JWT. En relisant ce champ pour chaque jeton, un seul porte « admin » : J03. Même sans casser une signature, ce champ suffit déjà à mesurer la sensibilité d’un jeton.'),
  ('c0bab6f6-5a05-92e2-202a-be686f46fc73', array['2']::text[], 'La politique fixe une seule audience attendue pour l’API partenaire. En comparant tous les champs « aud » à cette valeur, 2 jeton(s) ne correspondent pas. Vérifier l’audience empêche de recycler un jeton émis pour un autre service.'),
  ('e85f9bf7-9318-1e9e-64a7-f94ea2ca7e08', array['3']::text[], 'La politique borne la durée d’un jeton d’accès. En calculant « exp - iat » sur chaque charge utile et en comparant à cette limite, 3 jeton(s) dépassent la durée autorisée. Une durée trop longue augmente l’impact d’un vol de jeton.'),
  ('e9c7b26f-66f9-7cc0-f02b-edbee70b3ef9', array['1']::text[], 'Pour un JWT HS256, la signature se recalcule sur les deux premières parties, séparées par un point. En refaisant ce calcul avec le secret d’essai, 1 jeton(s) HS256 ne valident pas. Cela révèle soit une altération de charge utile, soit une signature faite avec un autre secret.'),
  ('a75b1c2f-07ac-a5a3-4d51-4f53a4c85444', array['2']::text[], 'Une déconnexion correcte doit invalider la session côté serveur. En regroupant les événements par identifiant et en cherchant une requête acceptée après « logout », on trouve 2 session(s) distincte(s) encore actives. C’est un vrai défaut de révocation côté serveur.'),
  ('23e3fe39-975e-1805-9e40-3dc79fba3d1c', array['3']::text[], 'Une régénération d’identifiant après la connexion évite la fixation de session. En lisant chaque événement « login » et en comparant « session_id » à « rotated_to », 3 connexion(s) gardent pourtant le même identifiant. Le journal montre donc directement le défaut sans avoir besoin d’un navigateur.'),
  ('8d7b651a-9add-5003-c5f6-26d80cfc105b', array['4']::text[], 'La politique fixe une limite d’inactivité, donc il faut mesurer les écarts entre deux événements d’une même session. En ne gardant ensuite que les requêtes encore acceptées après un écart strictement supérieur à la limite, on en compte 4. Cela signale une expiration d’inactivité mal appliquée.'),
  ('6edaeb84-2318-8ac6-f47f-0aaf0ca1933a', array['argon2id']::text[], 'Le format d’empreinte se reconnaît d’abord à son préfixe. Pour le compte msylla, ce préfixe correspond à argon2id. Lire le bon algorithme est la première étape avant de parler de conformité ou de robustesse.'),
  ('cba9f4c8-bdc0-7920-3543-31f533ac348a', array['11']::text[], 'La politique ne juge pas seulement le nom de l’algorithme : elle tient aussi compte de certains paramètres. En relisant chaque empreinte avec cette règle, 11 compte(s) sont non conformes. Cette vérification transforme un simple inventaire en vrai contrôle de politique.'),
  ('eb40ce0f-e9b5-706f-23a5-e9bbf695c770', array['legacy-mobile']::text[], 'La politique donne un ordre explicite de faiblesse entre les formats. En l’appliquant à tout l’export, un seul compte arrive en dernier du point de vue de la robustesse : legacy-mobile. Cette méthode évite un jugement subjectif sur les empreintes.'),
  ('ae5bc9fc-e3cd-f1fe-6e69-54e004fb631c', array['c']::text[], 'La meilleure réponse est c, car régénérer l’identifiant après la connexion et après un changement de privilège coupe la fixation de session. Les autres propositions conservent ou aggravent le défaut au lieu de le corriger réellement.'),
  ('dbab840c-6bac-e4a5-c706-a6ec2ff2c7a1', array['b']::text[], 'La bonne réponse est b. Des jetons courts réduisent la fenêtre d’abus, et une révocation ou une version de session côté serveur permet encore d’invalider un jeton compromis avant son expiration naturelle.'),
  ('e627a09e-b5b9-04fb-b111-eb1534713483', array['19']::text[], 'Il faut d’abord ramener chaque chemin à sa route logique, lire la ligne correspondante dans la matrice, puis garder uniquement les succès 200 où la propriété est requise. En comparant ensuite l’utilisateur du jeton au propriétaire de l’objet, on trouve 19 requête(s) réussie(s) alors qu’elles n’auraient pas dû l’être. Cette méthode isole un vrai défaut de contrôle d’accès objet.'),
  ('323d7b76-1a4c-64cb-4a15-4d1c4c62cbb3', array['1318']::text[], 'Une fois les violations de propriété isolées, il faut les regrouper par utilisateur et comparer les totaux. Le maximum revient à 1318, sans égalité. Repérer l’utilisateur qui concentre ces lectures aide à séparer un défaut diffus d’une exploration méthodique d’objets voisins.'),
  ('96ab8d18-61bd-c7a3-3e72-e75e8b23126c', array['12']::text[], 'Ici, on ne garde que les lectures de réservation du même utilisateur, toujours sur des objets qui ne lui appartiennent pas. En supprimant les doublons, on obtient 12 identifiant(s) distinct(s). Ce comptage permet de mesurer l’ampleur de l’énumération et pas seulement son existence.'),
  ('4e8a8ca5-9649-f464-aa95-62d8541e3805', array['4820']::text[], 'Après tri des identifiants de réservation lus hors propriété par cet utilisateur, la borne basse de la série séquentielle est 4820. Lire la première borne d’une énumération aide à reconstituer la fenêtre d’exploration choisie par le client ou son script.'),
  ('43ca4250-6cb9-f839-af73-63274554a93a', array['4831']::text[], 'La borne haute de la même série croissante vaut 4831. Associer première et dernière borne permet ensuite d’estimer l’étendue d’une exploration séquentielle sans deviner un motif invisible dans la matrice.'),
  ('35e12d4a-a9e9-0f99-91f3-efe3176e8d3e', array['7']::text[], 'Il faut croiser le rôle vu dans le journal avec les rôles autorisés par la matrice. En gardant uniquement les requêtes de rôle « client » qui reçoivent malgré tout un 200 sur une route réservée au personnel, on en trouve 7. Cette lecture révèle un défaut d’autorisation fonctionnelle, pas seulement un défaut sur l’objet.'),
  ('1c1e9218-29e1-4670-cb8e-c5096dd558ac', array['26']::text[], 'Pour cette question, il faut réunir deux familles : les routes interdites au rôle courant et les routes où la propriété est requise mais absente. En comptant chaque requête une seule fois, on obtient 26 succès 200 contraires à la matrice. C’est une bonne mesure synthétique de l’écart entre la politique écrite et le comportement observé.'),
  ('22ffd705-dda9-e2da-74b2-793ea83b99c1', array['8']::text[], 'Le journal sortant donne la destination réellement contactée par la fonction d’aperçu. En gardant seulement les adresses privées, locales ou de lien local, on compte 8 requête(s). Ce filtrage sert à mesurer un risque SSRF sans confondre trafic externe banal et appel vers l’intérieur du réseau.'),
  ('51869e1c-2c53-265d-0d6f-46389e8a0e97', array['1318,172.20.20.15', '1318, 172.20.20.15']::text[], 'Il faut lire le journal sortant dans l’ordre chronologique, puis s’arrêter sur la première destination qui tombe dans une plage privée, locale ou de lien local. Le couple attendu est 1318,172.20.20.15. Associer utilisateur et destination évite de perdre le contexte d’origine d’un appel SSRF.'),
  ('1b825ae0-0f6f-2745-f84a-d14a4a550aa1', array['3']::text[], 'Le service de métadonnées est identifiable directement par son adresse. En gardant uniquement les lignes vers 169.254.169.254 qui reçoivent un 200, on en trouve 3. Cette mesure aide à distinguer une tentative bloquée d’un appel effectivement servi.'),
  ('8d81d3b4-a5aa-fd96-e07e-fb57eeab9960', array['7216']::text[], 'Une fois les réponses 200 du service de métadonnées isolées, il suffit d’additionner les octets renvoyés. Le total vaut 7216. Le volume donne un indice utile sur ce qui a réellement été récupéré, pas seulement sur le fait qu’un accès a réussi.'),
  ('adb35785-434e-35fc-c546-ae996bf38a75', array['29']::text[], 'Pour mesurer un martèlement, on coupe l’horodatage à la minute puis on compte les requêtes de chaque jeton dans chaque minute. Le maximum observé est 29 requête(s) par minute. Cette méthode met en évidence un abus de rythme sans avoir besoin d’un seuil externe arbitraire.'),
  ('bb9f657e-8de0-bf23-4609-3e5df7f6c613', array['09:47', '9:47']::text[], 'Le pic de débit est atteint à 09:47 UTC. Retrouver la minute du maximum permet ensuite de zoomer sur la fenêtre utile et de voir si ce jeton martèle plusieurs routes ou toujours la même.'),
  ('f1bd3312-a02c-f576-b330-28605a60aeca', array['b']::text[], 'La bonne correction consiste à vérifier côté serveur, pour chaque requête, que l’objet demandé appartient bien à l’utilisateur ou qu’un droit explicite l’autorise. Ici, la bonne lettre est b. Changer l’identifiant ou le client ne suffit jamais à remplacer un vrai contrôle d’accès objet.'),
  ('e0e62442-2b32-9017-5a6f-ba6de49b192b', array['a']::text[], 'La bonne correction combine une liste autorisée de destinations, un refus des adresses privées ou locales et une vérification côté serveur après résolution. La bonne lettre est a. Les filtres textuels simples se contournent facilement et ne remplacent pas une vraie politique de sortie.'),
  ('e2357fc6-f5fd-2855-ee74-449d1b24eb7a', array['7']::text[], 'En relisant la configuration avec la liste de contrôle du guide, on retrouve 7 règles violées. La méthode consiste à valider chaque règle une par une, pas à juger la configuration à l’intuition : le versionnage du serveur, le listage de répertoires, les protocoles TLS anciens et le cache public comptent chacun une fois, et chacun des trois en-têtes manquants compte aussi une fois.'),
  ('d07e5a64-4d91-842d-ef5f-fa256c3379e8', array['65']::text[], 'Le listage de répertoires est porté par une seule directive dédiée. En repérant cette ligne dans le bloc concerné, on obtient 65. Relever le bon numéro de ligne facilite ensuite un correctif ciblé et une preuve claire dans un rapport.'),
  ('ae916649-c666-1b72-44f2-9d44cbfdfd65', array['46']::text[], 'La directive qui choisit les protocoles TLS fait apparaître les versions autorisées sur une seule ligne. Cette ligne est la 46. La trouver permet d’isoler rapidement le réglage à durcir sans confondre protocole, chiffrements et durée de session.'),
  ('08c1b8db-7a8f-5baa-8912-cc80bbb137a5', array['8']::text[], 'Il faut d’abord associer chaque avis au paquet installé, puis vérifier si la version locale tombe bien dans la plage touchée. En raisonnant par paquets distincts, on obtient 8. Cette distinction évite de compter deux fois un même paquet touché par plusieurs avis.'),
  ('4e48b2cf-6b19-c276-de37-a5adbcc67a12', array['swb-adv-2026-002']::text[], 'Après avoir retiré les avis non applicables et calculé les notes de base des avis restants, un seul arrive en tête : swb-adv-2026-002. La bonne méthode est de filtrer avant de classer, sinon un avis déjà corrigé pourrait polluer la priorisation.'),
  ('5c31d8dc-81f9-d79d-322c-62b22975e82e', array['7.5', '7,5']::text[], 'Le vecteur de cet avis conduit à une note de base de 7.5. Il faut suivre la formule officielle de CVSS 3.1 du guide, puis appliquer l’arrondi supérieur au dixième, sans arrondir au plus proche comme dans un calcul ordinaire.'),
  ('80e05e54-8962-7f5f-a501-214abfeee0fe', array['b']::text[], 'La note de cet avis tombe dans la tranche 4,0 à 6,9. La qualification attendue est donc « moyenne », soit la lettre b. Relier une note à sa tranche est indispensable pour présenter une synthèse exploitable à une personne non technique.'),
  ('4c848369-cd87-6030-3560-52ff5f15114a', array['2']::text[], 'On ne compte ici que les avis à la fois critiques et applicables aux versions présentes. Il y en a 2. Cette double condition évite de surestimer le risque en mélangeant gravité théorique et exposition réelle du parc installé.'),
  ('9e7b31b7-5414-a06c-cf15-862fb3709789', array['template-fast']::text[], 'Le seul paquet qui doit franchir un changement de version majeure pour atteindre sa première version corrigée est template-fast. Cette lecture sert à anticiper un correctif potentiellement plus risqué qu’un simple patch de maintenance.'),
  ('5ed70356-0113-f77d-5f3c-434f35188d68', array['2.4.5']::text[], 'Comme plusieurs avis touchent le même paquet, il faut choisir la plus petite version qui dépasse toutes les bornes corrigées. Ici, la version minimale sûre est 2.4.5. Cette comparaison évite d’appliquer une mise à jour incomplète.'),
  ('6a8dcda5-7a9b-6d9c-5c56-3fa7bbae9641', array['3']::text[], 'Certains avis concernent bien des paquets installés, mais la version locale est déjà au niveau corrigé ou au-delà. Il y en a 3. Savoir les retirer du lot t’évite de gonfler artificiellement la dette de correction.'),
  ('e4c8cf43-f227-9fdb-64d1-110e5ccf6ba2', array['c']::text[], 'Le choix le plus critique est le fichier d’environnement, car il peut révéler des secrets applicatifs et accélérer une compromission. La bonne lettre est donc c. Dans un audit, on priorise ce qui ouvre directement la voie à d’autres actions.'),
  ('42c485d9-917e-df66-6742-07e3835f78cd', array['4']::text[], 'La liste du guide vise les fichiers d’environnement, Git, les archives et les pages de diagnostic. En gardant seulement ceux qui répondent encore en 200, on en compte 4. Cette étape permet de distinguer exposition réelle et simple présence d’un nom dans une arborescence.'),
  ('fa38478d-647d-9883-aa83-5e2bf1f568ac', array['c']::text[], 'Le choix le plus solide consiste à traiter d’abord ce qui est applicable, exposé sur Internet et déjà exploité, puis à poursuivre par gravité. La bonne lettre est c. Une priorisation utile combine toujours contexte d’exposition et sévérité technique.'),
  ('7d833cc5-0b2a-d2a4-d53a-f49195952397', array['d']::text[], 'Un fichier d’environnement accessible doit être traité comme compromis jusqu’à preuve du contraire. La bonne réponse est d : retirer l’accès, faire tourner les secrets et vérifier les journaux. Retirer seulement le lien ou le renommer ne supprime ni l’exposition passée ni le risque résiduel.'),
  ('bc57d170-f3b8-4bd4-59e2-befe67c97af1', array['a05']::text[], 'Le constat F01 montre une route qui concatène directement une entrée utilisateur dans une requête SQL. La catégorie OWASP 2025 adaptée est donc A05, car la donnée non fiable est interprétée comme une instruction par le moteur SQL.'),
  ('8b37b81f-f280-2a64-e83e-8900d76604c8', array['a05']::text[], 'Le constat F02 provient d’un affichage HTML qui réinjecte une donnée stockée sans échappement. Cette famille reste rattachée à A05 en 2025, car du contenu non fiable devient une instruction interprétable dans le navigateur.'),
  ('984d8a60-1869-489f-f0a3-b887e19e0a9d', array['a01']::text[], 'La route de F03 renvoie le détail d’une réservation dès qu’un utilisateur est authentifié, sans vérifier que l’objet lui appartient. C’est un contrôle d’accès brisé, donc la bonne catégorie OWASP 2025 est A01.'),
  ('43dc7ee4-7270-eeb3-c1f0-0424cb47f867', array['a07']::text[], 'Un secret de signature de session codé en dur fragilise directement l’authentification et la confiance accordée à la session. Dans la grille fournie, ce constat se rattache à A07 car il compromet le mécanisme d’authentification et d’émission des sessions.'),
  ('776fd52a-0b59-eb8a-a733-8837c97b5a2f', array['a01']::text[], 'F05 permet au serveur d’aller chercher une ressource choisie par l’utilisateur, y compris des destinations internes. Dans l’édition 2025 du Top 10 OWASP, cette forme de SSRF se rattache à A01, avec les autres ruptures de contrôle d’accès.'),
  ('a990f741-8339-50cb-5546-36753c385237', array['a03']::text[], 'F07 provient d’une dépendance touchée par un avis de sécurité alors qu’elle reste installée dans l’application. Cette situation relève de la chaîne d’approvisionnement logicielle et la grille la range donc dans A03.'),
  ('f84c9088-7ff4-e26e-9415-7f2d185b2b6b', array['9.4', '9,4']::text[], 'Le constat F01 fournit son vecteur CVSS dans le tableau des constats. En appliquant exactement la formule et la règle d’arrondi supérieur de la grille, on obtient la note de base attendue pour cette injection SQL.'),
  ('1975932e-4222-3bd7-6c90-70af9cabad75', array['7.4', '7,4']::text[], 'Le vecteur de F05 utilise une portée modifiée, ce qui oblige à reprendre les valeurs PR correspondantes et la formule d’impact pour S:C. Le calcul complet donne une note différente de celle d’un cas à portée inchangée.'),
  ('695932da-6cf8-e663-c14d-8cd287dbe9d6', array['8.8', '8,8']::text[], 'Le paquet vulnérable de F07 est décrit avec un vecteur CVSS complet. En appliquant la grille, on retrouve une note critique qui sert ensuite de base au calcul de la priorité mais ne la remplace pas.'),
  ('91aab013-d90c-1dc7-97b6-3d4537aec02e', array['112.8', '112,8']::text[], 'La priorité de F01 se calcule à partir de sa note CVSS, de la criticité de l’application et de la valeur de certitude « démontrée ». Le résultat chiffré permet de comparer objectivement ce constat aux autres.'),
  ('4ae7aebe-af45-5cef-2f6d-375011d1c98c', array['88.8', '88,8']::text[], 'F05 vise le même actif critique que d’autres constats, mais sa priorité dépend aussi de la certitude de la preuve. La multiplication imposée par la grille donne la valeur numérique attendue.'),
  ('c56285ca-37c4-abb3-02e2-06cc6e7e7046', array['140.8', '140,8']::text[], 'La dépendance touchée par un avis critique ne devient prioritaire qu’après multiplication par la criticité de l’application et la certitude confirmée. C’est ce calcul qui place F07 devant les autres constats techniques.'),
  ('78660fed-370a-8b44-f65f-de2badb794b3', array['06', '6']::text[], 'Le bon numéro est celui du constat dont la priorité numérique est la plus élevée, sans égalité. La grille force une comparaison explicite et évite de traiter d’abord un sujet simplement plus parlant que les autres.'),
  ('185074e6-9b5c-7ea1-6cac-ba334ff4e90d', array['08', '8']::text[], 'Le faux positif se reconnaît parce que le scanner affirme l’absence d’un en-tête qui est pourtant bien visible dans l’export brut de la page visée. Il faut donc rejeter ce constat plutôt que le prioriser.'),
  ('110b9171-4d63-3709-976e-25b9cd21640f', array['06', '6']::text[], 'Le journal montre un téléversement suivi d’un appel vers un script devenu publiquement accessible. Cela confirme qu’un constat de code a déjà été transformé en exploitation réelle et qu’il ne reste plus théorique.'),
  ('3b935b0d-56ec-bc02-c2cb-3c9eaa2821f3', array['09:11:43, 198.51.100.77', '09:11:43,198.51.100.77']::text[], 'La première tentative exploitée est la toute première requête malveillante qui dépose le fichier dangereux, pas la vérification qui suit. L’heure UTC et l’adresse source se lisent sur la même ligne du journal et ouvrent la chronologie de l’incident.'),
  ('49df8a3d-3933-e888-affa-f00e3cbcc4ce', array['b']::text[], 'Les exportations TLS montrent encore l’acceptation de protocoles obsolètes, ce qui affaiblit nettement la surface HTTPS. Les autres options de la question décrivent au contraire un comportement neutre ou positif.'),
  ('ca7bc0d1-9aa8-507b-9a00-98b4e2ea640d', array['c']::text[], 'La correction attendue se concentre sur la séparation entre code SQL et données, puis sur le moindre privilège du compte applicatif. Les autres options masquent le symptôme ou laissent la faille structurelle en place.'),
  ('d64378d4-0896-521f-d4b7-de6f0f594b64', array['13']::text[], 'Le constat F04 n’est pas abstrait : il pointe une ligne précise du code qui stocke en clair le secret de signature. Relever ce numéro de ligne rend la recommandation directement vérifiable pendant la correction.')
insert into public.lab_assets (id, lab_id, kind, title, description, url, position) values
  ('127beb14-efa9-5979-4c15-8614cfe9a7cd', '4db9f43c-9fb5-ee9e-df35-22051e0dddc3', 'log', 'Échanges HTTP bruts', 'Douze échanges requête plus réponse HTTP/1.1, numérotés, avec quelques accès en clair et plusieurs codes utiles.', '/labs/swb-tp1-echanges.http', 1),
  ('baf9a75b-dda2-19fa-3ef2-4a5c3278dbef', '4db9f43c-9fb5-ee9e-df35-22051e0dddc3', 'log', 'Cookies observés', 'Liste de cookies « Set-Cookie » avec des attributs variés, dont une combinaison incorrecte de SameSite et Secure.', '/labs/swb-tp1-cookies.txt', 2),
  ('44f07430-6e85-fd3b-7b4d-7e1fc5206ee5', '4db9f43c-9fb5-ee9e-df35-22051e0dddc3', 'log', 'Extrait de certificat', 'Sortie abrégée de style OpenSSL pour trois noms d’hôtes, avec sujet, SAN, dates, protocole et suite.', '/labs/swb-tp1-certificat.txt', 3),
  ('d256f378-2a6b-da41-d62b-44b4c8416f38', '4db9f43c-9fb5-ee9e-df35-22051e0dddc3', 'log', 'En-têtes de réponse', 'Dix blocs d’en-têtes de réponse HTTP pour comparer HSTS, CSP, nosniff, Server et d’autres réglages.', '/labs/swb-tp1-en-tetes.txt', 4),
  ('579bac8f-319d-4456-a988-73f35d8f8f57', '4db9f43c-9fb5-ee9e-df35-22051e0dddc3', 'guide', 'Guide du TP 1', 'Méthode pour lire un échange HTTP, juger un cookie, convertir un Max-Age et comparer un SAN.', '/labs/swb-tp1-guide.pdf', 5),
  ('7c213d91-7583-4a93-6a18-b7fd937302db', '943b8b9a-2d4b-1792-a3eb-b891d4ddf5a0', 'log', 'Journal d’accès nginx', 'Journal web au format combined, en UTC, avec trafic légitime, robots, supervision et tentatives d’injection.', '/labs/swb-tp2-acces.log', 1),
  ('c7a1be8e-ebcd-6a19-5eb4-2297bc84bc1e', '943b8b9a-2d4b-1792-a3eb-b891d4ddf5a0', 'log', 'Journal SQL de l’application', 'Une ligne par requête SQL exécutée avec identifiant de requête, route, utilisateur SQL, texte final, nombre de lignes et durée.', '/labs/swb-tp2-requetes-sql.log', 2),
  ('d1d9343d-7ca2-e85a-9849-09ff0a24ec1e', '943b8b9a-2d4b-1792-a3eb-b891d4ddf5a0', 'log', 'Extrait du code Express', 'Routes Express syntaxiquement valides, dont une recherche, une connexion, une réservation et un export.', '/labs/swb-tp2-appli.js', 3),
  ('3bdc65ae-927c-4d11-7292-dcbf05919be5', '943b8b9a-2d4b-1792-a3eb-b891d4ddf5a0', 'guide', 'Guide du TP 2', 'Méthode pour décoder une chaîne de requête, compter les motifs retenus et relier un accès à son SQL.', '/labs/swb-tp2-guide.pdf', 4),
  ('f291cedc-79e3-26ab-1e8c-977856e84804', '1903f4c5-e240-9c3a-8042-ca88944a5ac9', 'log', 'Extraits de gabarits', 'Douze extraits numérotés de gabarits côté serveur avec leur contexte de sortie HTML.', '/labs/swb-tp3-gabarits.txt', 1),
  ('303f05cf-3911-fc49-d8d5-73c65246969b', '1903f4c5-e240-9c3a-8042-ca88944a5ac9', 'log', 'Politiques CSP candidates', 'Six politiques Content-Security-Policy numérotées de P1 à P6.', '/labs/swb-tp3-politiques.txt', 2),
  ('49aa164f-49b2-6b96-6288-21575747ce50', '1903f4c5-e240-9c3a-8042-ca88944a5ac9', 'log', 'Rapports de violation CSP', 'Rapports JSON lignes collectés en mode essai sur l’application de réservation.', '/labs/swb-tp3-rapports.jsonl', 3),
  ('34ac499b-b4f0-4545-39cf-4dee0120fb83', '1903f4c5-e240-9c3a-8042-ca88944a5ac9', 'log', 'Tableau des en-têtes HTTP', 'Dix pages et leurs principaux en-têtes de protection, au format CSV séparé par des points-virgules.', '/labs/swb-tp3-en-tetes.csv', 4),
  ('d01bb9f4-9138-cfd9-d506-f4a19d363c51', '1903f4c5-e240-9c3a-8042-ca88944a5ac9', 'log', 'Script en ligne autorisé', 'Texte exact d’un script en ligne encore présent, utile pour calculer une source CSP par empreinte.', '/labs/swb-tp3-script-en-ligne.txt', 5),
  ('2535cb24-3ee6-e966-d3c9-23f11298d199', '1903f4c5-e240-9c3a-8042-ca88944a5ac9', 'guide', 'Guide du TP 3', 'Méthode pour juger des contextes de sortie, lire une CSP et noter des en-têtes de protection.', '/labs/swb-tp3-guide.pdf', 6),
  ('462f183e-5f8d-7ace-8e29-fb375ba77ce9', '37a116c2-ddeb-94a9-9e00-58920074fbff', 'log', 'Liste des jetons JWT', 'Douze jetons d’accès fictifs fournis un par un avec leur identifiant interne.', '/labs/swb-tp4-jetons.txt', 1),
  ('87c8c86b-147b-cd27-499c-510fcdd9ddd5', '37a116c2-ddeb-94a9-9e00-58920074fbff', 'log', 'Journal des sessions', 'Cycle de vie des sessions de réservation : connexion, requêtes, déconnexion et expiration.', '/labs/swb-tp4-sessions.log', 2),
  ('9752a153-60fb-1b6f-595b-f2dfb8a52db2', '37a116c2-ddeb-94a9-9e00-58920074fbff', 'log', 'Export des empreintes', 'Inventaire fictif des formats d’empreintes stockées pour des comptes clients, staff et service.', '/labs/swb-tp4-empreintes.csv', 3),
  ('ff9919ca-4610-f743-7cd9-3e58b1be7a5b', '37a116c2-ddeb-94a9-9e00-58920074fbff', 'guide', 'Politique interne', 'Règles de l’hôtel pour la durée des jetons, l’expiration des sessions et les formats d’empreintes admis.', '/labs/swb-tp4-politique.pdf', 4),
  ('25d70cdd-55d6-85bc-2d6e-dfb2a364cabe', '37a116c2-ddeb-94a9-9e00-58920074fbff', 'guide', 'Guide de méthode', 'Méthode pour décoder un JWT, relire un journal de sessions et classer des empreintes sans divulguer les réponses.', '/labs/swb-tp4-guide.pdf', 5),
  ('e92f4ee9-4ddb-c6fc-e50c-6839d276bdab', '25dfbe51-b6c9-2393-8e07-477a4e2beece', 'log', 'Journal de la passerelle d’API', 'Export JSON lignes des requêtes API avec jeton, utilisateur, rôle, route, propriétaire de l’objet, statut et volume.', '/labs/swb-tp5-api.jsonl', 1),
  ('006abe4f-287c-5608-8074-8656dc33b9e1', '25dfbe51-b6c9-2393-8e07-477a4e2beece', 'log', 'Matrice des droits', 'Table CSV qui décrit les routes logiques, les rôles autorisés et l’obligation éventuelle de propriété.', '/labs/swb-tp5-droits.csv', 2),
  ('c9ab131c-feb0-77d3-ad0c-6c550da44e26', '25dfbe51-b6c9-2393-8e07-477a4e2beece', 'log', 'Journal des requêtes sortantes', 'Journal texte des appels sortants déclenchés par la fonction d’aperçu d’URL, avec destination réelle, statut et octets.', '/labs/swb-tp5-sortant.log', 3),
  ('1b75dfb1-d192-ec36-ea65-0c699ffb5471', '25dfbe51-b6c9-2393-8e07-477a4e2beece', 'guide', 'Guide du TP 5', 'Méthode pour comparer la matrice, reconnaître une énumération, mesurer un débit et repérer un SSRF.', '/labs/swb-tp5-guide.pdf', 4),
  ('08434dda-b529-90a1-1352-e392873cf328', 'df8d5da2-9664-8b97-bc8c-23e99fe7966f', 'log', 'Configuration nginx', 'Configuration du serveur frontal HTTPS de l’application de réservation.', '/labs/swb-tp6-nginx.conf', 1),
  ('32e64795-f57e-2d41-7304-22e4990113cf', 'df8d5da2-9664-8b97-bc8c-23e99fe7966f', 'log', 'Racine du site exposée', 'Liste des chemins visibles à la racine du site avec leur statut HTTP et leur taille.', '/labs/swb-tp6-racine-site.txt', 2),
  ('4de832b8-bfda-abef-6db2-aa7bf570df4c', 'df8d5da2-9664-8b97-bc8c-23e99fe7966f', 'log', 'Dépendances Node.js', 'Inventaire des paquets installés et de leurs versions exactes.', '/labs/swb-tp6-dependances.csv', 3),
  ('4ba6649c-a2cc-01ee-3e3d-64c94e9bef97', 'df8d5da2-9664-8b97-bc8c-23e99fe7966f', 'log', 'Avis de sécurité', 'Export d’avis fictifs avec plage touchée, version corrigée et vecteur CVSS 3.1.', '/labs/swb-tp6-avis.csv', 4),
  ('949a9139-46fb-6ba4-f8e1-a5276a7780b7', 'df8d5da2-9664-8b97-bc8c-23e99fe7966f', 'guide', 'Guide du TP 6', 'Méthode de lecture de la configuration, de comparaison des versions et de calcul CVSS 3.1.', '/labs/swb-tp6-guide.pdf', 5),
  ('4785e152-b6e1-d0cf-1cb0-6a087ac3adfc', '1b051777-0a06-51bc-de49-0ccc97a055f3', 'guide', 'Lettre de mission', 'Le périmètre, les limites et les livrables attendus pour l’audit.', '/labs/swb-proj-mission.pdf', 1),
  ('1a2fe968-dce6-6e5b-6132-5e0c234d86cb', '1b051777-0a06-51bc-de49-0ccc97a055f3', 'log', 'En-têtes HTTP exportés', 'Six réponses HTTP brutes à comparer avec les constats du scanner.', '/labs/swb-proj-en-tetes.txt', 2),
  ('ce80ccb4-de66-7490-b4ea-6b32acf34f44', '1b051777-0a06-51bc-de49-0ccc97a055f3', 'log', 'Extrait du code Express', 'Le code applicatif à relire pour relier les constats techniques à une ligne précise.', '/labs/swb-proj-code.js', 3),
  ('238f6f3b-1c38-e9ce-7e79-048cb96fc233', '1b051777-0a06-51bc-de49-0ccc97a055f3', 'log', 'Dépendances installées', 'La liste des paquets Node.js et de leurs versions installées.', '/labs/swb-proj-dependances.csv', 4),
  ('151586b4-f28d-f71d-e4f0-81b6c7f54b92', '1b051777-0a06-51bc-de49-0ccc97a055f3', 'log', 'Avis de sécurité', 'Les paquets touchés, leurs versions corrigées et les vecteurs CVSS annoncés.', '/labs/swb-proj-avis.csv', 5),
  ('bd31b112-d3cb-8204-cc4f-40bd876654c1', '1b051777-0a06-51bc-de49-0ccc97a055f3', 'log', 'Analyse TLS', 'Les protocoles, les suites et les informations du certificat exportés pour l’audit.', '/labs/swb-proj-tls.txt', 6),
  ('7c4c8e64-4b2e-26dc-f37e-54812d2534b8', '1b051777-0a06-51bc-de49-0ccc97a055f3', 'log', 'Journal d’accès web', 'Le trafic normal, le bruit et les traces d’exploitation réelle à dater.', '/labs/swb-proj-journaux.log', 7),
  ('21e1d8e2-3929-ea0c-334a-d2657415ba2f', '1b051777-0a06-51bc-de49-0ccc97a055f3', 'log', 'Constats préliminaires', 'Le tableau des constats F01 à F09 avec source, emplacement et certitude.', '/labs/swb-proj-constats.csv', 8),
  ('3ed5dcd9-2353-9a5e-4c24-02d7060caf38', '1b051777-0a06-51bc-de49-0ccc97a055f3', 'guide', 'Grille d’évaluation', 'Les catégories OWASP 2025, la formule CVSS 3.1 et l’échelle de priorité.', '/labs/swb-proj-grille.pdf', 9),
  ('3fd1f6e3-6188-c956-2b07-9bbdab48a678', '1b051777-0a06-51bc-de49-0ccc97a055f3', 'report_template', 'Modèle de rapport', 'Un squelette sobre pour le résumé de direction et le tableau final des constats.', '/labs/swb-proj-modele-rapport.pdf', 10),
  ('b6a4cf19-fbea-538c-5f10-505a8fcadaeb', '1b051777-0a06-51bc-de49-0ccc97a055f3', 'guide', 'Guide de méthode', 'Une méthode générique pour qualifier, noter, prioriser et rédiger sans toucher à un système réel.', '/labs/swb-proj-guide.pdf', 11)
insert into public.skills (id, domain_id, slug, name, description, position) values
  ('8c17f629-3d27-13af-234f-36f1c38ab127', 'fd805117-cb22-fe14-7c0e-4f383168d1ea', 'lire-http-securite', 'HTTP, cookies et HTTPS vus par la sécurité', 'Lire une requête et une réponse HTTP, juger des cookies, d’un certificat et d’en-têtes de sécurité.', 710),
  ('dbdba026-d791-7d7c-1e91-2ec5886f99e8', 'fd805117-cb22-fe14-7c0e-4f383168d1ea', 'reperer-injections', 'Reconnaître et corriger les injections', 'Repérer une injection dans du code et dans des journaux, et choisir la correction qui sépare le code des données.', 720),
  ('0fd2bef8-65e4-f227-1328-21bfa13433d9', 'fd805117-cb22-fe14-7c0e-4f383168d1ea', 'prevenir-xss-csp', 'Prévenir le XSS et évaluer une CSP', 'Encoder les sorties selon leur contexte, évaluer une politique de sécurité du contenu et lire ses rapports.', 730),
  ('840a12d5-1206-2a39-954f-4053f22fc103', 'fd805117-cb22-fe14-7c0e-4f383168d1ea', 'securiser-sessions-jetons', 'Sécuriser sessions, jetons et mots de passe', 'Contrôler des sessions, des jetons JWT et le stockage des mots de passe d’après une politique écrite.', 740),
  ('b5766dc7-11f5-447d-717a-f6e507053456', 'fd805117-cb22-fe14-7c0e-4f383168d1ea', 'controler-acces-api', 'Contrôle d’accès, API et SSRF', 'Repérer l’accès à l’objet d’un autre, les fonctions interdites et les requêtes sortantes vers l’intérieur dans des journaux.', 750),
  ('1e0dec19-8326-aaae-7d77-23a8b7a68d36', 'fd805117-cb22-fe14-7c0e-4f383168d1ea', 'durcir-configuration', 'Durcir la configuration et les dépendances', 'Trouver ce qui est mal réglé dans une configuration et quels composants installés sont touchés par un avis de sécurité.', 760),
  ('e45d4086-fc65-06e8-e6ee-09a0dba09e19', 'fd805117-cb22-fe14-7c0e-4f383168d1ea', 'noter-prioriser-vulnerabilites', 'Noter et prioriser les vulnérabilités', 'Calculer une note CVSS 3.1, la qualifier et ordonner les corrections en tenant compte du contexte.', 770),
  ('ca8aea7e-200c-8f9c-dc36-b04de07a4c44', 'fd805117-cb22-fe14-7c0e-4f383168d1ea', 'auditer-application-web', 'Auditer une application web et rédiger le rapport', 'Mener un audit dans un cadre autorisé, qualifier les constats, recommander et rédiger un rapport défendable.', 780)
