update public.quiz_questions set explanation = 'HTTPS protège avant tout le trajet réseau : confidentialité, intégrité et authentification du serveur. La mauvaise réponse tentante est de croire qu’il garantit aussi l’honnêteté commerciale du site, alors qu’un site frauduleux peut très bien présenter un certificat valide pour son propre nom.'
where id = '869908dc-03b1-9de3-d182-819686242c3d' and explanation = 'HTTPS protège le transport des données, pas les intentions de celui qui exploite le site.';
update public.quiz_questions set explanation = 'Oui, un site avec un cadenas peut être frauduleux. Le cadenas dit que la connexion est protégée jusqu’au serveur qui possède ce certificat, pas que ce serveur mérite ta confiance ni qu’il ne cherche pas à te tromper.'
where id = 'c9f48fa1-4af2-fa55-1a49-7d669a585ffb' and explanation = 'Les sites frauduleux peuvent obtenir des certificats valides. Le domaine et le contexte restent essentiels.';
update public.quiz_questions set explanation = 'Un mot de passe unique par service évite qu’une fuite chez un prestataire entraîne immédiatement la compromission des autres comptes. La mauvaise idée la plus tentante est de réutiliser le même secret avec une petite variante, car une fuite ou un credential stuffing effacent vite cet avantage apparent.'
where id = '7f565638-5c5e-5201-5ba9-c3ffd0ce1b6f' and explanation = 'La réutilisation permet à une fuite sur un service de compromettre les autres.';
update public.quiz_questions set explanation = 'Les codes de récupération doivent rester dans un endroit sûr distinct de l’appareil principal, justement pour servir quand cet appareil est perdu, volé ou bloqué. Les publier, les envoyer à un inconnu ou les laisser dans le même coffre non protégé annule presque toute leur utilité.'
where id = 'd0572fe9-46dc-504e-418f-1ae46e9ea0b9' and explanation = 'Ces codes doivent rester secrets et accessibles si ton appareil principal est perdu.';
update public.quiz_questions set explanation = 'Le canal officiel indépendant casse la mise en scène du fraudeur. Répondre au message ou cliquer sur le lien te laisse dans le décor choisi par l’attaquant, alors qu’un numéro déjà connu, une application ouverte par toi-même ou un collègue identifié donnent une vérification réellement séparée.'
where id = '40e940f8-ee6b-935c-f1fc-8827d447f272' and explanation = 'L’auteur du message peut répondre lui-même et copier un logo. Un canal connu limite ce risque.';
update public.quiz_questions set explanation = 'Un code de connexion demandé par un inconnu reste un secret, même s’il ne dure que quelques secondes. Le ton poli, l’urgence ou le logo ne changent rien : partager ce code revient souvent à remettre la seconde preuve d’authentification à l’attaquant lui-même.'
where id = '5624196e-e91d-4b53-821f-44824b92ae48' and explanation = 'Un code de connexion est un secret, même s’il n’est valable que quelques secondes.';

update public.courses c set estimated_duration = least(10000, s.total)
from (select course_id, sum(duration_minutes)::integer as total from public.lessons group by course_id) s
where c.id = '40abe0c4-0341-1c25-adee-8292a16408cf' and s.course_id = c.id and c.estimated_duration < s.total;

update public.courses set short_description = 'Comprendre HTTP et HTTPS, reconnaître et corriger les failles des applications web (injections, XSS, sessions, contrôle d’accès, API), puis auditer un site et rédiger le rapport.', description = 'Ce parcours t’apprend comment fonctionne le web, pourquoi et comment les applications web sont attaquées, comment les défendre et comment auditer un site avec méthode, jusqu’au rapport. Tu pars des réflexes du quotidien (HTTPS, comptes, phishing), tu apprends à lire une requête, un cookie, un certificat et des en-têtes, puis tu étudies les grandes familles de failles : injections, XSS et politique de sécurité du contenu, sessions et jetons, contrôle d’accès, CSRF et CORS, fichiers, SSRF et API, configuration et dépendances. Dix modules progressifs suivent le référentiel OWASP Top 10 dans son édition 2025.

Chaque leçon propose un cours détaillé, des extraits de code et de requêtes commentés, des démonstrations guidées que tu rejoues sur ton ordinateur, des exemples corrigés et un quiz avec correction. Six travaux pratiques guidés et un projet final t’apprennent à lire des captures HTTP, des journaux, du code, des configurations et des listes de dépendances, à calculer une note CVSS et à classer des correctifs, avec des critères de réussite vérifiés par la plateforme.

Tout est défensif et légal : tu analyses des fichiers fictifs fournis par la plateforme ou ton propre site, tu ne testes jamais un système sans autorisation écrite, et chaque leçon indique où t’entraîner légalement. Compétences visées : lire HTTP, cookies et en-têtes, reconnaître et corriger une injection, encoder et évaluer une politique de sécurité du contenu, contrôler sessions, jetons et mots de passe, repérer un défaut de contrôle d’accès ou un SSRF, durcir une configuration, noter et prioriser des vulnérabilités, puis rédiger un rapport d’audit défendable.

Aucun prérequis autre que la curiosité et les bases des cours Réseaux et Fondamentaux : un ordinateur Windows avec Node.js, PowerShell ou Git Bash suffit pour rejouer les démonstrations, et les travaux pratiques se font à partir de fichiers fournis, sans serveur ni outil offensif. Les vidéos sont en préparation : chaque leçon indique clairement quand la sienne n’est pas encore disponible, et le cours écrit couvre déjà l’essentiel.'
where id = '40abe0c4-0341-1c25-adee-8292a16408cf' and short_description = 'HTTPS, comptes sécurisés et détection du phishing : les bons réflexes du web.' and description = 'HTTPS, gestionnaire de mots de passe, MFA et détection du phishing : les réflexes qui protègent tes comptes et ceux de ton équipe.';

